window._pbbScript5Started = true;

// Fallback for getLocalDateString (defined in script-11, which may load after script-5 on iOS)
if (typeof getLocalDateString !== 'function') {
    window.getLocalDateString = function(date) {
        var d = date ? new Date(date) : new Date();
        return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    };
}

// On iOS this script is deferred until after pbbInitComplete, which fires well after
// DOMContentLoaded. Use _onDomReady() instead of addEventListener('DOMContentLoaded')
// so handlers run immediately when the script loads (DOM is already parsed).
function _onDomReady(fn) {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', fn);
    } else {
        fn();
    }
}

// A short-lived release accidentally left part of a guided-tour stylesheet
// after </html>. A cached native shell can still parse that orphaned text into
// the Course page. Remove only that unmistakable legacy fragment whenever a
// delayed/cached document hands control to the current app script.
function removeLegacyGuidedTourTextLeak() {
    const marker = '#guided-tour-overlay.tour-keyboard-open';
    [document.documentElement, document.body].filter(Boolean).forEach(function(root) {
        Array.from(root.childNodes || []).forEach(function(node) {
            if (node.nodeType === Node.TEXT_NODE && String(node.textContent || '').includes(marker)) {
                node.remove();
            }
        });
    });
}

_onDomReady(function() {
    removeLegacyGuidedTourTextLeak();
    const root = document.documentElement;
    if (!root || typeof MutationObserver === 'undefined') return;
    const cleanupObserver = new MutationObserver(removeLegacyGuidedTourTextLeak);
    cleanupObserver.observe(root, { childList: true });
    setTimeout(function() { cleanupObserver.disconnect(); }, 5000);
});

// Initialize Stripe for in-app purchases
// On iOS Safari, Stripe.js is deferred until after init completes to reduce memory pressure.
// Guard against Stripe being undefined to prevent the script from failing entirely.
try {
    if (typeof Stripe !== 'undefined') {
        window.stripe = Stripe('pk_live_51GmycUCGCyRUsOfK9lOtnZNvinxCcjf7rZnpC0ter8eShFPATzVKB7ypy2BPQbMRkuWT67mf04tjzvu18jQvmlZX00BvlGLyds');
    } else {
        // Stripe not loaded yet (deferred on iOS) — will initialize when script loads
        window.addEventListener('pbbInitComplete', function() {
            setTimeout(function() {
                if (typeof Stripe !== 'undefined') {
                    window.stripe = Stripe('pk_live_51GmycUCGCyRUsOfK9lOtnZNvinxCcjf7rZnpC0ter8eShFPATzVKB7ypy2BPQbMRkuWT67mf04tjzvu18jQvmlZX00BvlGLyds');
                }
            }, 5000); // Wait 5s after init for deferred Stripe script to load
        }, { once: true });
    }
} catch(e) {
    console.warn('Stripe init deferred:', e);
}

// PWA & Navigation Logic
_onDomReady(() => {
    // Handle Coin Pack purchase return
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('coin_purchase') === 'success') {
        const packName = urlParams.get('pack') || 'coins';
        window.history.replaceState({}, document.title, window.location.pathname);
        setTimeout(() => {
            alert('Coins added to your balance! Time to compete.');
            if (typeof loadCoinBalance === 'function') loadCoinBalance();
        }, 500);
    }

    // Handle tab deep-link (e.g., returning from workout-duel page)
    const deepLinkTab = urlParams.get('tab');
    if (deepLinkTab) {
        window.history.replaceState({}, document.title, window.location.pathname);
        setTimeout(() => {
            if (typeof switchAppTab === 'function') {
                switchAppTab(deepLinkTab);
            }
        }, 300);
    }

    // Handle legacy challenge pass/buyin returns
    if (urlParams.get('challenge_pass') === 'success' || urlParams.get('challenge_buyin') === 'success') {
        window.history.replaceState({}, document.title, window.location.pathname);
        setTimeout(() => {
            const pendingId = urlParams.get('challenge_id') || sessionStorage.getItem('pending_challenge_id');
            sessionStorage.removeItem('pending_challenge_id');
            if (pendingId && typeof doAcceptChallenge === 'function') {
                doAcceptChallenge(pendingId);
            }
        }, 500);
    }

    // 0. Chat History now loaded in consolidated auth-aware block

    // 1. Move Sections out of Meals Container
    // We want Movement and Support to be top-level app views, not sub-views of Meals
    const moveIds = ['movement-tab', 'group', 'sleep', 'view-active-workout', 'view-workout-success', 'view-profile'];
    const container = document.querySelector('.container');
    const bottomNav = document.querySelector('.bottom-nav');
    
    moveIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.classList.remove('active');
            el.classList.add('app-view'); // Treat as top level view
            el.style.display = 'none'; // Hide initially
            // Move to main container
            container.appendChild(el);
        }
    });

    // Move fixed overlay views to body level to avoid z-index stacking context issues
    // AND so they aren't hidden when their current parent tab (e.g. view-meals) has display:none.
    const overlayIds = ['view-your-workouts', 'view-workout-library', 'view-workout-subcategories', 'view-workout-list', 'view-workout-overview', 'view-week-workouts', 'view-week-session'];
    overlayIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            document.body.appendChild(el);
        }
    });

    // 2. Initialize (Now handled by the consolidated listener above)
    // initProgramDate(); 
    // switchAppTab('dashboard', document.querySelector('.nav-item')); // Default to Home
});

async function openBillingPortal() {
    const btn = document.getElementById('settings-payment-method-btn');
    const originalText = btn ? btn.textContent : '';
    try {
        const platformName = window.Platform && typeof window.Platform.name === 'function'
            ? window.Platform.name()
            : (window.Capacitor && typeof window.Capacitor.getPlatform === 'function'
                ? window.Capacitor.getPlatform()
                : 'web');

        if (platformName === 'ios' || platformName === 'android') {
            const storeUrl = platformName === 'ios'
                ? 'https://apps.apple.com/account/subscriptions'
                : 'https://play.google.com/store/account/subscriptions?package=com.fitgotchi.app';

            if (btn) {
                btn.disabled = true;
                btn.textContent = 'Opening...';
            }

            if (window.Capacitor?.Plugins?.Browser?.open) {
                await window.Capacitor.Plugins.Browser.open({ url: storeUrl });
            } else {
                const opened = window.open(storeUrl, '_blank', 'noopener,noreferrer');
                if (!opened) window.location.href = storeUrl;
            }
            return;
        }

        if (!window.currentUser?.id) {
            throw new Error('Please log in again to manage your payment method.');
        }

        let session = null;
        if (window.authHelpers && typeof window.authHelpers.getSession === 'function') {
            session = await window.authHelpers.getSession();
        } else if (window.supabaseClient?.auth && typeof window.supabaseClient.auth.getSession === 'function') {
            const result = await window.supabaseClient.auth.getSession();
            session = result?.data?.session || null;
        }

        const accessToken = session?.access_token;
        if (!accessToken) {
            throw new Error('Please log in again to manage your payment method.');
        }

        if (btn) {
            btn.disabled = true;
            btn.textContent = 'Opening...';
        }

        const returnUrl = window.location.origin + window.location.pathname + '?tab=profile';
        const response = await fetch('/.netlify/functions/create-billing-portal-session', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': 'Bearer ' + accessToken
            },
            body: JSON.stringify({ returnUrl })
        });

        let data = {};
        try { data = await response.json(); } catch(e) {}
        if (!response.ok || !data.url) {
            throw new Error(data.error || 'Could not open payment settings yet.');
        }

        window.location.href = data.url;
    } catch (error) {
        console.error('Billing portal failed:', error);
        if (typeof showToast === 'function') {
            showToast(error.message || 'Could not open payment settings yet.', 'error');
        } else {
            alert(error.message || 'Could not open payment settings yet.');
        }
    } finally {
        if (btn) {
            btn.disabled = false;
            btn.textContent = originalText || 'Manage';
        }
    }
}

// --- DAILY CONTENT LOGIC ---
async function initProgramDate() {
    let startDate = null;
    try {
        const profile = await window.getUserProfile();
        startDate = profile?.program_start_date;
    } catch(e) {}

    if (!startDate) {
        startDate = localStorage.getItem('pbb_start_date');
    }

    if (!startDate) {
        startDate = new Date().toISOString();
    }

    // Always ensure localStorage is synced with the current start date
    localStorage.setItem('pbb_start_date', startDate);

    const start = new Date(startDate);
    const now = new Date();
    const diffTime = Math.abs(now - start);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    let currentDay = diffDays;
    if (currentDay < 1) currentDay = 1;

    updateDailyContent(currentDay);
}

function updateDailyContent(day) {
    const counterEl = document.getElementById('daily-progress-counter');
    if (counterEl) {
        counterEl.innerText = `Day ${day} of 28`;
        if (day > 28) counterEl.innerText = `Day ${day} (Maintenance)`;
    }

    // Update Movement Tab Header
    const moveDate = document.getElementById('movement-today-date');
    if (moveDate) {
        moveDate.innerText = `Day ${day}`;
    }

    // --- NEW: Render Today's Meals Logic ---
    const todayContainer = document.getElementById('today-meals-content');
    if (todayContainer) {
        const weekNum = Math.ceil(day / 7);
        const dayIndex = (day - 1) % 7;
        const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
        const dayName = days[dayIndex];
        const sourceId = `week${weekNum}-${dayName}`;
        
        const sourceCard = document.getElementById(sourceId);
        
        if (sourceCard) {
            // Clone content but keep it generic/clean
            todayContainer.innerHTML = ''; // Clear loading
            const clone = sourceCard.cloneNode(true);
            
            // Adjust styling for 'Today' view if needed, or just append
            // We want it open by default
            clone.classList.add('open');
            clone.style.marginBottom = '20px';
            
            // Remove the ID to avoid duplicates in DOM
            clone.removeAttribute('id');
            
            // Fix onclick to toggle THIS clone, not the original ID
            const header = clone.querySelector('.card-header');
            if(header) header.setAttribute('onclick', 'toggleCard(this.parentElement)');
            
            todayContainer.appendChild(clone);
        } else {
            // Fallback if content not found
            todayContainer.innerHTML = `
                <div style="text-align:center; padding:40px; color:var(--text-muted);">
                    <p>Meals for Day ${day} (${dayName}, Week ${weekNum}) are loading...</p>
                    <button onclick="switchWeek('week${weekNum}', this)" style="margin-top:10px; padding:10px 20px; border-radius:30px; border:1px solid var(--primary); background:transparent; color:var(--primary); cursor:pointer;">View Week ${weekNum} Plan</button>
                    <!-- Debug: Looked for #${sourceId} -->
                </div>
            `;
        }
    }
}

// Real syncQuizDataToDb implementation - replaces the early stub
async function _syncQuizDataToDbRealImpl() {
    const user = window.currentUser;
    if (!user) return;

    try {
        const activeUserId = user.id || user.user_id;
        const pendingMetaClaim = !!(window.BalanceMetaAdTrial && window.BalanceMetaAdTrial.hasPendingClaim());
        const quizDataFromSession = readSessionProfileForActiveUser({ allowGuestClaim: pendingMetaClaim });
        const quizJson = quizDataFromSession ? JSON.stringify(quizDataFromSession) : null;
        const hormoneType = sessionStorage.getItem('userResult');

        let quizData = {};
        if (quizJson) quizData = quizDataFromSession;

        // A missing or rejected profile means this tab contains no onboarding
        // data owned by the active user. Never fall through to a database update.
        if (!quizData || Object.keys(quizData).length === 0) return;

        const embeddedUserId = quizData.id || quizData.user_id || null;
        const embeddedEmail = String(quizData.email || '').trim().toLowerCase();
        const activeEmail = String(user.email || '').trim().toLowerCase();
        if ((embeddedUserId && embeddedUserId !== activeUserId) ||
            (embeddedEmail && activeEmail && embeddedEmail !== activeEmail)) {
            console.warn('[profile-scope] Rejected onboarding data belonging to another account.');
            sessionStorage.removeItem('userProfile');
            sessionStorage.removeItem('userResult');
            sessionStorage.removeItem('pbb_profile_owner_user_id');
            return;
        }

        stampSessionProfileForActiveUser(activeUserId);

        // Add hormone type if present
        if (hormoneType) {
            quizData.profile = hormoneType;
        }

        // Map 'sex' to 'user_gender' for quiz users
        // Quiz collects 'sex' field, but we need 'user_gender' for UI/localStorage
        if (quizData.sex && !quizData.user_gender) {
            quizData.user_gender = quizData.sex;
            cacheActiveUserGender(quizData.sex, activeUserId);
        }

        // NOTE: Symptom derivation from quiz REMOVED
        // Symptoms can ONLY be set via daily wellness check-in to prevent persistent stale data
        // This ensures equipment selection is respected and symptoms stay current

        if (Object.keys(quizData).length > 0) {
            console.log("Syncing quiz data to DB...", quizData);

            // SPLIT DATA: Users table vs User Facts (personal_details)
            // sex is a core user attribute stored in users table
            // equipment_access is stored in quiz_results table (not users table)
            const userColumns = ['name', 'email', 'profile_photo', 'program_start_date', 'theme_preference', 'background_preference', 'location', 'sex', 'ig_handle'];
            const coreData = {};
            const factsData = {};

            Object.keys(quizData).forEach(k => {
                if (userColumns.includes(k)) coreData[k] = quizData[k];
                else factsData[k] = quizData[k];
            });

            // 1. Update Core User Data (user row already exists from signup)
            if (Object.keys(coreData).length > 0) {
                try {
                    await dbHelpers.users.update(user.id, coreData);
                } catch(updateErr) {
                    // If a column doesn't exist yet (schema cache miss), retry without it
                    // so other fields still save. Common during DB migrations.
                    const msg = updateErr?.message || String(updateErr);
                    const colMatch = msg.match(/Could not find the '(\w+)' column/);
                    if (colMatch) {
                        console.warn(`[syncQuizDataToDb] Column '${colMatch[1]}' missing in DB — skipping it for this sync:`, msg);
                        const saferData = { ...coreData };
                        delete saferData[colMatch[1]];
                        if (Object.keys(saferData).length > 0) {
                            await dbHelpers.users.update(user.id, saferData);
                        }
                    } else {
                        throw updateErr;
                    }
                }
            }

            // 2. Update Extension Data (User Facts)
            if (Object.keys(factsData).length > 0) {
                // Get existing facts first to merge
                let existingFacts = {};
                try { existingFacts = await dbHelpers.userFacts.get(user.id); } catch(e){}

                const currentDetails = existingFacts?.personal_details || {};

                await dbHelpers.userFacts.upsert(user.id, {
                    personal_details: { ...currentDetails, ...factsData }
                });
            }

            // 3. Calculate and Save Nutrition Goals if we have the required data
            // Check if nutrition goals were already pre-calculated by the onboarding wizard
            const hasPreCalculatedGoals = quizData.bmr && quizData.tdee && quizData.calorie_goal &&
                                          quizData.protein_goal_g && quizData.carbs_goal_g && quizData.fat_goal_g;

            // Default goalBodyType to 'Athletic' if not provided (balanced middle-ground for non-quiz users)
            const effectiveGoalBodyType = quizData.goalBodyType || 'Athletic';

            // Required fields: age, height, weight, goal_weight, activity_level, sex
            // goalBodyType is now optional (defaults to 'Athletic')
            const hasRequiredFields = quizData.age && quizData.height && quizData.weight &&
                                      quizData.goal_weight && quizData.activity_level && quizData.sex;

            if (hasPreCalculatedGoals || hasRequiredFields) {
                try {
                    let nutritionGoals;
                    let metricData;

                    if (hasPreCalculatedGoals) {
                        // Use pre-calculated values from onboarding wizard
                        console.log("Using pre-calculated nutrition goals from wizard");
                        nutritionGoals = {
                            bmr: quizData.bmr,
                            tdee: quizData.tdee,
                            calorie_goal: quizData.calorie_goal,
                            protein_goal_g: quizData.protein_goal_g,
                            carbs_goal_g: quizData.carbs_goal_g,
                            fat_goal_g: quizData.fat_goal_g
                        };
                        // For metric data, use direct values (wizard already uses metric)
                        metricData = {
                            age: quizData.age,
                            height: quizData.height,
                            weight: quizData.weight,
                            goal_weight: quizData.goal_weight,
                            sex: quizData.sex,
                            activity_level: quizData.activity_level,
                            goalBodyType: effectiveGoalBodyType
                        };
                    } else {
                        // Convert quiz data to metric units and calculate
                        const dataWithBodyType = { ...quizData, goalBodyType: effectiveGoalBodyType };
                        metricData = convertQuizDataToMetric(dataWithBodyType);
                        nutritionGoals = calculateNutritionGoals(metricData);
                    }

                    if (nutritionGoals) {
                        console.log("Calculated nutrition goals:", nutritionGoals);

                        // Save to quiz_results table
                        const quizResultData = {
                            menopause_status: quizData.menopause_status,
                            cycle_description: quizData.cycle_desc,
                            activity_level: quizData.activity_level,
                            weight_storage_location: quizData.weight_gain_location,
                            goal_body_type: effectiveGoalBodyType,
                            sleep_hours: quizData.sleep_hours,
                            sleep_quality: quizData.wake_feel,
                            energy_level: quizData.energy_level || quizData.energy_status, // Support both field names
                            energy_crashes: quizData.midday_crash,
                            caffeine_relationship: quizData.caffeine,
                            hormone_profile: hormoneType,
                            equipment_access: quizData.equipment_access || 'none',
                            dietary_preference: quizData.dietary_preference || localStorage.getItem('dietaryPreference') || null,
                            age: metricData.age,
                            height: metricData.height,
                            weight: metricData.weight,
                            goal_weight: metricData.goal_weight,
                            sex: metricData.sex,
                            bmr: nutritionGoals.bmr,
                            tdee: nutritionGoals.tdee,
                            calorie_goal: nutritionGoals.calorie_goal,
                            protein_goal_g: nutritionGoals.protein_goal_g,
                            carbs_goal_g: nutritionGoals.carbs_goal_g,
                            fat_goal_g: nutritionGoals.fat_goal_g
                        };

                        await dbHelpers.quizResults.create(user.id, quizResultData);
                        console.log("Quiz results with nutrition goals saved to database");

                        // Update daily_nutrition goals for ALL existing entries
                        // This ensures that when onboarding is redone, all historical entries
                        // reflect the new calorie/macro goals instead of keeping stale values
                        const goalsToUpdate = {
                            calorie_goal: nutritionGoals.calorie_goal,
                            protein_goal_g: nutritionGoals.protein_goal_g,
                            carbs_goal_g: nutritionGoals.carbs_goal_g,
                            fat_goal_g: nutritionGoals.fat_goal_g
                        };

                        // First update all existing entries
                        await dbHelpers.nutrition.updateAllGoals(user.id, goalsToUpdate);
                        console.log("All daily nutrition goals updated");

                        // Also ensure today has an entry (updateAllGoals only updates existing rows)
                        const today = getLocalDateString();
                        await dbHelpers.nutrition.updateGoals(user.id, today, goalsToUpdate);
                        console.log("Today's nutrition goals ensured");

                        // CRITICAL FIX: Save sex to users table so it persists on page reload
                        // This fixes the bug where gender resets to female on refresh
                        await dbHelpers.users.update(user.id, {
                            sex: metricData.sex
                        });
                        console.log("User sex field saved to users table:", metricData.sex);
                    }

                    // Save meal timing schedule if set during quiz
                    if (quizData.meal_time_breakfast || quizData.meal_time_lunch || quizData.meal_time_dinner) {
                        try {
                            await dbHelpers.mealSchedule.upsert(user.id, {
                                breakfast: quizData.meal_time_breakfast || '08:00',
                                lunch: quizData.meal_time_lunch || '12:30',
                                dinner: quizData.meal_time_dinner || '18:30'
                            });
                            console.log("Meal schedule saved:", {
                                breakfast: quizData.meal_time_breakfast,
                                lunch: quizData.meal_time_lunch,
                                dinner: quizData.meal_time_dinner
                            });
                        } catch (mealScheduleError) {
                            console.error("Failed to save meal schedule:", mealScheduleError);
                        }
                    }
                } catch (nutritionError) {
                    console.error("Failed to calculate/save nutrition goals:", nutritionError);
                }
            }

            // Update local cache
            window.userProfile = { ...window.userProfile, ...quizData };
            console.log("Quiz data synced successfully");
        }
    } catch (e) {
        console.error("Failed to sync quiz data:", e);
    }
}
// Register real implementation
_syncQuizDataToDbReal = _syncQuizDataToDbRealImpl;
syncQuizDataToDb = _syncQuizDataToDbRealImpl;

async function handleLogout() {
    // Guest mode: just clear guest state and go to login
    if (window.guestMode) {
        sessionStorage.removeItem('guestMode');
        sessionStorage.removeItem('guestBannerDismissed');
        window.location.replace('/login.html');
        return;
    }
    if (confirm('Are you sure you want to log out?')) {
        try {
            await authHelpers.signOut();
            // Clear any cached data
            sessionStorage.clear();

            // Clear all user-specific localStorage items to prevent data leak between accounts
            const userSpecificKeys = [
                'userProfile',
                'userGender',
                'pbb_user_gender_owner_id',
                'onboardingComplete',
                'characterColors',
                'userThemePreference',
                'userCycleData',
                'profile_photo',
                'selected_meal_plan',
                'user_food_preferences',
                'meal_reminder_settings',
                'lastWellnessCheck',
                'lastWeighInPromptDate',
                'equipmentUpdatedAt',
                'gym_split_start_date',
                'calendarViewPreference',
                'referral_banner_dismissed',
                'pwa_banner_dismissed_v2'
            ];

            userSpecificKeys.forEach(key => localStorage.removeItem(key));

            window.location.href = '/login.html';
        } catch (error) {
            console.error('Logout failed:', error);
            alert('Failed to log out. Please try again.');
        }
    }
}

/**
 * Delete account - clears all user data and allows retesting onboarding
 */
async function handleDeleteAccount() {
    const confirmed = confirm('Are you sure you want to DELETE your account?\n\n• All your data and progress will be permanently erased\n• This cannot be undone');
    if (!confirmed) return;

    const typed = prompt('Type DELETE to confirm:');
    if (!typed || typed.trim().toUpperCase() !== 'DELETE') {
        alert('Account deletion cancelled.');
        return;
    }

    const deleteBtn = document.querySelector('[onclick="handleDeleteAccount()"]');
    if (deleteBtn) { deleteBtn.disabled = true; deleteBtn.textContent = 'Deleting...'; }

    try {
        // Get the current session JWT to authenticate the server-side delete
        const { data: { session } } = await window.supabaseClient.auth.getSession();
        if (!session) throw new Error('No active session');

        const response = await fetch('/api/delete-account', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${session.access_token}`
            }
        });

        const result = await response.json();
        if (!response.ok) throw new Error(`${result.error || 'Deletion failed'}${result.detail ? ': ' + result.detail : ''}`);

        // Clear local storage and redirect
        sessionStorage.clear();
        localStorage.clear();
        alert('Your account has been permanently deleted.');
        window.location.replace('/login.html');

    } catch (error) {
        console.error('Account deletion failed:', error);
        alert('Failed to delete account: ' + error.message);
        if (deleteBtn) { deleteBtn.disabled = false; deleteBtn.textContent = 'DELETE ACCOUNT'; }
    }
}

function getActiveDashboardUserId() {
    return window.currentUser && (window.currentUser.id || window.currentUser.user_id) || null;
}

function stampSessionProfileForActiveUser(userId) {
    const ownerId = userId || getActiveDashboardUserId() || (window.guestMode ? 'guest' : null);
    if (!ownerId) return false;
    sessionStorage.setItem('pbb_profile_owner_user_id', ownerId);
    return true;
}

function readSessionProfileForActiveUser(options) {
    let profile = null;
    try { profile = JSON.parse(sessionStorage.getItem('userProfile') || 'null'); } catch(e) {}
    if (!profile || typeof profile !== 'object') return null;

    const opts = options || {};
    const activeUserId = getActiveDashboardUserId();
    const ownerId = sessionStorage.getItem('pbb_profile_owner_user_id');
    const lastUserId = localStorage.getItem('pbb_last_user_id');

    if (activeUserId && ownerId && ownerId !== activeUserId) {
        if (!(ownerId === 'guest' && opts.allowGuestClaim)) return null;
    }
    if (activeUserId && !ownerId && lastUserId && lastUserId !== activeUserId && !opts.allowGuestClaim) {
        return null;
    }
    return profile;
}

function cacheActiveUserGender(value, userId) {
    const gender = normalizeGenderValue(value);
    if (!gender) return false;
    const ownerId = userId || getActiveDashboardUserId() || (window.guestMode ? 'guest' : null);
    if (!ownerId) return false;
    localStorage.setItem('userGender', gender);
    localStorage.setItem('pbb_user_gender_owner_id', ownerId);
    return true;
}

async function getLatestQuizResultCached() {
    const userId = getActiveDashboardUserId();
    if (!userId || typeof dbHelpers === 'undefined' || !dbHelpers.quizResults) return null;

    if (window._pbbLatestQuizResultUserId === userId) {
        return window._pbbLatestQuizResult || null;
    }
    if (window._pbbLatestQuizResultPromise && window._pbbLatestQuizResultPromiseUserId === userId) {
        return await window._pbbLatestQuizResultPromise;
    }

    window._pbbLatestQuizResultPromiseUserId = userId;
    window._pbbLatestQuizResultPromise = dbHelpers.quizResults.getLatest(userId).then(function(result) {
        if (getActiveDashboardUserId() !== userId) return null;
        window._pbbLatestQuizResult = result || null;
        window._pbbLatestQuizResultUserId = userId;
        return window._pbbLatestQuizResult;
    }).catch(function(e) {
        console.warn("Quiz results fetching error", e);
        return null;
    }).finally(function() {
        if (window._pbbLatestQuizResultPromiseUserId === userId) {
            window._pbbLatestQuizResultPromise = null;
            window._pbbLatestQuizResultPromiseUserId = null;
        }
    });

    return await window._pbbLatestQuizResultPromise;
}

async function getTodayCheckinCached(dateKey) {
    const userId = getActiveDashboardUserId();
    if (!userId || typeof dbHelpers === 'undefined' || !dbHelpers.checkins) return null;

    const cacheKey = userId + ':' + dateKey;
    if (window._pbbTodayCheckinCacheKey === cacheKey) {
        return window._pbbTodayCheckinCache || null;
    }
    if (window._pbbTodayCheckinPromise && window._pbbTodayCheckinPromiseKey === cacheKey) {
        return await window._pbbTodayCheckinPromise;
    }

    window._pbbTodayCheckinPromiseKey = cacheKey;
    window._pbbTodayCheckinPromise = dbHelpers.checkins.get(userId, dateKey).then(function(result) {
        if (getActiveDashboardUserId() !== userId) return null;
        window._pbbTodayCheckinCache = result || null;
        window._pbbTodayCheckinCacheKey = cacheKey;
        return window._pbbTodayCheckinCache;
    }).catch(function(e) {
        console.warn('Could not check today\'s check-in status:', e);
        return null;
    }).finally(function() {
        if (window._pbbTodayCheckinPromiseKey === cacheKey) {
            window._pbbTodayCheckinPromise = null;
            window._pbbTodayCheckinPromiseKey = null;
        }
    });

    return await window._pbbTodayCheckinPromise;
}

// Real loadProfileData implementation - replaces the early stub
async function _loadProfileDataRealImpl() {
    let profile = null;
    let quizResult = null;

    const profilePromise = (typeof window.getUserProfile === 'function'
        ? window.getUserProfile()
        : Promise.resolve(null)
    ).catch(function(e) {
        console.warn("Profile fetching error", e);
        return null;
    });

    const quizPromise = (window.currentUser?.id && typeof dbHelpers !== 'undefined'
        ? getLatestQuizResultCached()
        : Promise.resolve(null)
    ).catch(function(e) {
        console.warn("Quiz results fetching error", e);
        return null;
    });

    [profile, quizResult] = await Promise.all([profilePromise, quizPromise]);

    // Merge quiz results into profile for easy access. The users table is the
    // authoritative gender source; older quiz rows can have sex=null.
    if (quizResult) {
        const profileSex = profile?.sex || profile?.user_gender || null;
        const quizSex = quizResult?.sex || quizResult?.user_gender || null;
        profile = { ...profile, ...quizResult };
        const resolvedSex = profileSex || quizSex || profile?.sex || profile?.user_gender;
        if (resolvedSex) {
            profile.sex = resolvedSex;
            if (!profile.user_gender) profile.user_gender = resolvedSex;
        }

        // Sync important quiz fields from database to localStorage
        try {
            const localProfile = JSON.parse(localStorage.getItem('userProfile') || '{}');
            let needsSave = false;

            // CRITICAL FIX: Sync equipment_access to localStorage so calendar/movement views have correct data
            if (quizResult.equipment_access && localProfile.equipment_access !== quizResult.equipment_access) {
                localProfile.equipment_access = quizResult.equipment_access;
                needsSave = true;
                console.log('✅ Equipment access synced from DB to localStorage:', quizResult.equipment_access);
            }

            // Sync cycle sync preferences
            if (quizResult.cycle_sync_preference && localProfile.cycle_sync_preference !== quizResult.cycle_sync_preference) {
                localProfile.cycle_sync_preference = quizResult.cycle_sync_preference;
                needsSave = true;
            }
            if (quizResult.period_energy_response && localProfile.period_energy_response !== quizResult.period_energy_response) {
                localProfile.period_energy_response = quizResult.period_energy_response;
                needsSave = true;
            }

            // Sync dietary preference
            if (quizResult.dietary_preference && localProfile.dietary_preference !== quizResult.dietary_preference) {
                localProfile.dietary_preference = quizResult.dietary_preference;
                localStorage.setItem('dietaryPreference', quizResult.dietary_preference);
                needsSave = true;
                console.log('Dietary preference synced from DB:', quizResult.dietary_preference);
            }

            if (profile?.workout_calendar) {
                const parsedCalendar = parseStoredWorkoutCalendar(profile.workout_calendar);
                if (parsedCalendar) {
                    const calendarJson = JSON.stringify(parsedCalendar);
                    if (localStorage.getItem('workoutCalendar') !== calendarJson) {
                        localStorage.setItem('workoutCalendar', calendarJson);
                    }
                    if (localProfile.workout_calendar !== calendarJson) {
                        localProfile.workout_calendar = calendarJson;
                        needsSave = true;
                    }
                }
            }

            if (profile?.exercise_preferences) {
                const exercisePrefsJson = JSON.stringify(profile.exercise_preferences);
                if (JSON.stringify(localProfile.exercise_preferences || null) !== exercisePrefsJson) {
                    localProfile.exercise_preferences = profile.exercise_preferences;
                    needsSave = true;
                }
                try { localStorage.setItem('exercise_preferences', exercisePrefsJson); } catch(e) {}
            }

            if (needsSave) {
                localStorage.setItem('userProfile', JSON.stringify(localProfile));
                console.log('✅ Profile preferences synced from database');
            }
        } catch (e) {
            console.warn('Error syncing profile to localStorage:', e);
        }
    }

    // Sync water goal settings from DB to localStorage (for cross-device persistence)
    if (profile?.water_goal_ml && !localStorage.getItem('pbb_water_goal_ml')) {
        localStorage.setItem('pbb_water_goal_ml', profile.water_goal_ml.toString());
        localStorage.setItem('pbb_water_glass_size', (profile.water_glass_size || 250).toString());
        localStorage.setItem('pbb_water_total_glasses', (profile.water_total_glasses || Math.ceil(profile.water_goal_ml / (profile.water_glass_size || 250))).toString());
        console.log('Restored water goal from DB:', profile.water_goal_ml, 'ml');
    }

    function getProfileFallbackForActiveUser() {
        const activeUser = window.currentUser || {};
        const activeUserId = activeUser.id || activeUser.user_id || null;
        const metadata = activeUser.user_metadata || {};
        let fallback = {};

        try {
            const localProfile = JSON.parse(localStorage.getItem('userProfile') || '{}');
            const lastUserId = localStorage.getItem('pbb_last_user_id');
            const localUserId = localProfile.id || localProfile.user_id || lastUserId || null;
            if (!activeUserId || !localUserId || localUserId === activeUserId || lastUserId === activeUserId) {
                fallback = { ...fallback, ...localProfile };
            }
        } catch(e) {}

        try {
            const sessionProfile = readSessionProfileForActiveUser();
            if (sessionProfile) fallback = { ...fallback, ...sessionProfile };
        } catch(e) {}

        const email = fallback.email || activeUser.email || '';
        const name = fallback.name || metadata.full_name || metadata.name || (email ? email.split('@')[0] : '');
        return {
            ...fallback,
            id: fallback.id || fallback.user_id || activeUserId || null,
            email,
            name,
            profile_photo: fallback.profile_photo || metadata.avatar_url || metadata.picture || activeUser.profile_photo || null,
            sex: fallback.sex || activeUser.sex || activeUser.user_gender || null,
            user_gender: fallback.user_gender || activeUser.user_gender || activeUser.sex || null
        };
    }

    const profileFallback = getProfileFallbackForActiveUser();
    if (!profile || Object.keys(profile).length === 0) {
        profile = profileFallback;
    } else {
        profile = { ...profileFallback, ...profile };
    }

    const context = {
        name: profile?.name || window.currentUser?.user_metadata?.full_name || window.currentUser?.user_metadata?.name || (profile?.email ? profile.email.split('@')[0] : 'Profile'),
        email: profile?.email || window.currentUser?.email || 'Loading...',
        age: profile?.age || profile?.age_years || 'Not set',
        weight: profile?.weight || profile?.weight_kg || profile?.current_weight_kg || '',
        goal: profile?.goal_weight || profile?.goal || profile?.primary_goal || 'Not set',
        profile: profile?.profile || (sessionStorage.getItem('userResult') || 'Cortisol').toUpperCase(),
        energy_level: profile?.energy_level || 'normal'
    };

    // Store energy_level globally for gender-specific UI
    window.userEnergyLevel = context.energy_level;

    // NOTE: Symptoms are NO LONGER loaded from profile
    // Symptoms now ONLY come from daily check-ins to prevent stale data from affecting recommendations

    if(document.getElementById('profile-default-initial')) {
        const initialSource = String(context.name || context.email || '').trim();
        document.getElementById('profile-default-initial').innerText = initialSource ? initialSource.charAt(0).toUpperCase() : '?';
    }
    if(document.getElementById('profile-name-display')) document.getElementById('profile-name-display').innerText = context.name;
    if(typeof window.updateHomeWelcome === 'function') window.updateHomeWelcome(context.name);
    if(document.getElementById('profile-email-display')) document.getElementById('profile-email-display').innerText = context.email;
    if(document.getElementById('profile-age-display')) document.getElementById('profile-age-display').innerText = context.age;
    
    const wStr = String(context.weight).toLowerCase();
    const weightDisplay = !context.weight
        ? 'Not set'
        : wStr.includes('k') || wStr.includes('l')
        ? context.weight 
        : context.weight + " kg";

    if(document.getElementById('profile-weight-display')) document.getElementById('profile-weight-display').innerText = weightDisplay;
    if(document.getElementById('profile-goal-display')) document.getElementById('profile-goal-display').innerText = context.goal;
    
    const equipment = profile?.equipment_access || 'none';
    const eqMap = {
        'gym': 'Full Gym Access',
        'dumbbells': 'Home / Dumbbells',
        'home': 'Home / Dumbbells',  // Legacy value support
        'bands': 'Resistance Bands',
        'yoga_only': 'Yoga / Stretching Only',
        'none': 'No Equipment',
        'bodyweight': 'No Equipment'  // Legacy value support
    };
    const eqDisplay = document.getElementById('profile-equipment-display');
    if(eqDisplay) {
        eqDisplay.innerText = eqMap[equipment] || 'No Equipment';
        eqDisplay.dataset.raw = equipment; // Store raw value for edit mode mapping
    }

    // Display dietary requirements (multi-select). Falls back to the single-string
    // legacy `dietary_preference` for users who haven't migrated yet.
    const dietDisplay = document.getElementById('profile-diet-display');
    if (dietDisplay) {
        const reqLabels = {
            omnivore: 'Omnivore', flexitarian: 'Flexitarian', pescatarian: 'Pescatarian',
            vegetarian: 'Vegetarian', vegan: 'Vegan', mediterranean: 'Mediterranean',
            keto: 'Keto', paleo: 'Paleo', whole30: 'Whole30',
            gluten_free: 'Gluten-Free', dairy_free: 'Dairy-Free', nut_free: 'Nut-Free',
            soy_free: 'Soy-Free', egg_free: 'Egg-Free', shellfish_free: 'Shellfish-Free',
            low_fodmap: 'Low FODMAP', low_sodium: 'Low Sodium', low_sugar: 'Low Sugar',
            halal: 'Halal', kosher: 'Kosher'
        };
        let reqs = [];
        try {
            const fromLs = JSON.parse(localStorage.getItem('dietaryRequirements') || 'null');
            if (Array.isArray(fromLs)) reqs = fromLs;
        } catch (e) {}
        if (!reqs.length) {
            try {
                const fp = JSON.parse(localStorage.getItem('user_food_preferences') || '{}');
                if (Array.isArray(fp.dietary_requirements)) reqs = fp.dietary_requirements;
            } catch (e) {}
        }
        if (!reqs.length) {
            const legacy = profile?.dietary_preference || localStorage.getItem('dietaryPreference') || '';
            if (legacy && reqLabels[legacy]) reqs = [legacy];
        }
        dietDisplay.textContent = reqs.length
            ? reqs.map(r => reqLabels[r] || r).join(', ')
            : 'Not set';
    }

    // Display symptoms from latest check-in (NOT from profile)
    // Symptoms can only be updated via daily wellness check-in
    let symptomsText = 'None';

    // Look for most recent check-in with symptoms
    if (userCycleData.logs && Object.keys(userCycleData.logs).length > 0) {
        // Get all dates sorted descending (most recent first)
        const dates = Object.keys(userCycleData.logs).sort().reverse();

        // Find the most recent check-in that has symptoms
        for (const date of dates) {
            const log = userCycleData.logs[date];
            if (log.symptoms && Array.isArray(log.symptoms) && log.symptoms.length > 0) {
                symptomsText = log.symptoms.map(s =>
                    s.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ')
                ).join(', ');
                break;
            }
        }
    }

    if(document.getElementById('profile-symptoms-display')) {
        document.getElementById('profile-symptoms-display').innerText = symptomsText;
    }

    // Load saved avatar if exists
    const savedPhoto = localStorage.getItem('profile_photo') || profile?.profile_photo || '';
    if(savedPhoto) {
        if (!localStorage.getItem('profile_photo')) {
            try { localStorage.setItem('profile_photo', savedPhoto); } catch (_) {}
        }
        const mainImg = document.getElementById('profile-photo-img');
        if(mainImg) mainImg.src = savedPhoto;
        document.querySelectorAll('.profile-icon').forEach(el => {
            el.innerHTML = `<img src="${savedPhoto}" style="width:100%; height:100%; border-radius:50%; object-fit:cover;">`;
            el.style.background = 'transparent';
        });
    }

    // CRITICAL: Always sync gender from database to localStorage
    // Database is the source of truth - always overwrite localStorage
    // This fixes the bug where localStorage has wrong gender value
    // Check both fields, preferring users.sex after the null-safe profile merge.
    const genderFromDb = profile?.sex || profile?.user_gender;
    if (genderFromDb) {
        const currentLocalGender = localStorage.getItem('userGender');
        if (currentLocalGender !== genderFromDb) {
            console.log("Gender mismatch detected - DB:", genderFromDb, "localStorage:", currentLocalGender);
        }
        // Skip localStorage write in admin view-as mode to prevent state leakage
        if (!window.isAdminViewing) cacheActiveUserGender(genderFromDb);
        console.log("Synced gender from DB to localStorage:", genderFromDb);
    }

    // CRITICAL: Restore theme preference from database to localStorage
    // This ensures theme persists even when cache is cleared
    // Skip in admin view-as mode to prevent theme leakage to admin's localStorage
    if (profile?.theme_preference && !localStorage.getItem('userThemePreference') && !window.isAdminViewing) {
        localStorage.setItem('userThemePreference', profile.theme_preference);
        console.log("Restored theme preference from DB to localStorage:", profile.theme_preference);
    }

    // Restore background preference from database to localStorage
    // This ensures background persists even when cache/localStorage is cleared
    if (profile?.background_preference && !localStorage.getItem('selectedBackground') && !window.isAdminViewing) {
        localStorage.setItem('selectedBackground', profile.background_preference);
        console.log("Restored background preference from DB to localStorage:", profile.background_preference);
        // Apply immediately since the 2500ms init may have already run with the wrong background
        if (window.selectBackground) {
            window.selectBackground(profile.background_preference);
        }
    }

    // CRITICAL FIX: Restore sex field to sessionStorage for nutrition calculations
    // This fixes the bug where gender resets to female on page refresh
    if (profile?.sex) {
        let currentProfile = {};
        try { currentProfile = JSON.parse(sessionStorage.getItem('userProfile') || '{}'); } catch(e) {}
        currentProfile.sex = profile.sex;
        sessionStorage.setItem('userProfile', JSON.stringify(currentProfile));
        stampSessionProfileForActiveUser();
        console.log("Restored sex from DB to sessionStorage:", profile.sex);
    }

    // ALWAYS apply gender-specific UI after profile loads
    // This uses localStorage (which may have been set during onboarding or restored from DB above)
    if (typeof applyGenderTheme === 'function') {
        applyGenderTheme();
    }
    if (typeof applyGenderSpecificUI === 'function') {
        applyGenderSpecificUI();
    }
    // Update settings icon to show Dragon Ball for DBZ themes
    if (typeof updateSettingsIcon === 'function') {
        updateSettingsIcon();
    }
    // Re-render cycle status with correct gender
    if (typeof renderCycleStatus === 'function') {
        renderCycleStatus();
    }

    // Load today's check-in from Supabase to sync localStorage
    if (window.currentUser && typeof dbHelpers !== 'undefined') {
        try {
            const today = getLocalDateString();
            const todayCheckin = await getTodayCheckinCached(today);
            if (todayCheckin) {
                // User has already checked in today - mark localStorage
                localStorage.setItem('lastWellnessCheck', new Date().toDateString());
                console.log('✅ Today\'s check-in found in DB');

                // Update symptoms display from check-in data
                const additionalData = todayCheckin.additional_data || {};
                const checkInSymptoms = additionalData.symptoms || [];
                if (checkInSymptoms.length > 0) {
                    const symptomsEl = document.getElementById('profile-symptoms-display');
                    if (symptomsEl) {
                        const formattedSymptoms = checkInSymptoms.map(s =>
                            s.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ')
                        ).join(', ');
                        symptomsEl.textContent = formattedSymptoms;
                    }
                }
            }
        } catch (e) {
            console.warn('Could not check today\'s check-in status:', e);
        }
    }

}
// Register real implementation
_loadProfileDataReal = _loadProfileDataRealImpl;
loadProfileData = _loadProfileDataRealImpl;

async function syncProfilePhotoToAccount(photoData) {
    if (!photoData || !window.currentUser?.id || !window.dbHelpers?.users?.update) return;
    try {
        const updated = await window.dbHelpers.users.update(window.currentUser.id, { profile_photo: photoData });
        window.currentUser.profile_photo = photoData;
        window.userProfile = { ...(window.userProfile || {}), profile_photo: photoData };
        try {
            const stored = JSON.parse(localStorage.getItem('userProfile') || '{}');
            stored.profile_photo = photoData;
            localStorage.setItem('userProfile', JSON.stringify(stored));
        } catch (_) {}
        return updated;
    } catch (error) {
        console.error('Failed to sync profile photo to account:', error);
        if (typeof showToast === 'function') {
            showToast('Photo saved on this device, but account sync failed.', 'error');
        }
    }
}

function handlePhotoUpload(input) {
    if (input.files && input.files[0]) {
        const file = input.files[0];

        // Validate file type
        if (!file.type.startsWith('image/')) {
            alert('Please select an image file.');
            input.value = '';
            return;
        }

        // Show loading state
        const mainImg = document.getElementById('profile-photo-img');
        if (mainImg) mainImg.style.opacity = '0.5';

        // Resize image to prevent localStorage overflow (max 500KB)
        resizeImageFile(file, 400, 0.8).then(photoData => {
            // Update main profile photo
            if (mainImg) {
                mainImg.src = photoData;
                mainImg.style.opacity = '1';
            }

            // Save to localStorage
            try {
                localStorage.setItem('profile_photo', photoData);
            } catch (e) {
                console.error('Failed to save photo to localStorage:', e);
            }

            // Update all small icons
            document.querySelectorAll('.profile-icon').forEach(el => {
                el.innerHTML = `<img src="${photoData}" style="width:100%; height:100%; border-radius:50%; object-fit:cover;">`;
                el.style.background = 'transparent';
            });

            syncProfilePhotoToAccount(photoData);

            // Reset input to allow re-selecting the same file
            input.value = '';
        }).catch(err => {
            console.error('Failed to process image:', err);
            alert('Failed to process image. Please try a different photo.');
            if (mainImg) mainImg.style.opacity = '1';
            input.value = '';
        });
    }
}

// Helper function to resize image before storing
function resizeImageFile(file, maxSize, quality) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = function(e) {
            const img = new Image();
            img.onload = function() {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;

                // Scale down if larger than maxSize
                if (width > height && width > maxSize) {
                    height = (height * maxSize) / width;
                    width = maxSize;
                } else if (height > maxSize) {
                    width = (width * maxSize) / height;
                    height = maxSize;
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0, width, height);

                resolve(canvas.toDataURL('image/jpeg', quality));
            };
            img.onerror = function() {
                reject(new Error('Failed to load image'));
            };
            img.src = e.target.result;
        };
        reader.onerror = function() {
            reject(new Error('Failed to read file'));
        };
        reader.readAsDataURL(file);
    });
}

// Handle profile photo upload during onboarding wizard
function handleWizardProfilePhoto(input) {
    if (input.files && input.files[0]) {
        const file = input.files[0];

        if (!file.type.startsWith('image/')) {
            alert('Please select an image file.');
            input.value = '';
            return;
        }

        const container = document.getElementById('wizard-profile-photo-container');
        const placeholder = document.getElementById('wizard-profile-photo-placeholder');
        const img = document.getElementById('wizard-profile-photo-img');

        if (container) container.style.opacity = '0.5';

        resizeImageFile(file, 400, 0.8).then(photoData => {
            // Show the image, hide placeholder
            if (img) {
                img.src = photoData;
                img.style.display = 'block';
            }
            if (placeholder) placeholder.style.display = 'none';
            if (container) container.style.opacity = '1';

            // Save to localStorage (same key as main profile photo)
            try {
                localStorage.setItem('profile_photo', photoData);
            } catch (e) {
                console.error('Failed to save wizard profile photo:', e);
            }

            // Also update main profile photo elements if they exist
            const mainImg = document.getElementById('profile-photo-img');
            if (mainImg) mainImg.src = photoData;
            document.querySelectorAll('.profile-icon').forEach(el => {
                el.innerHTML = `<img src="${photoData}" style="width:100%; height:100%; border-radius:50%; object-fit:cover;">`;
                el.style.background = 'transparent';
            });

            syncProfilePhotoToAccount(photoData);

            input.value = '';
        }).catch(err => {
            console.error('Failed to process wizard profile photo:', err);
            alert('Failed to process image. Please try a different photo.');
            if (container) container.style.opacity = '1';
            input.value = '';
        });
    }
}

function connectApp(appName) {
    const btn = event.target;
    btn.innerText = "Connecting...";
    btn.disabled = true;
    
    setTimeout(() => {
        btn.innerText = "Connected";
        btn.classList.add('connected');
        alert(`${appName} connected successfully! (Simulation)`);
    }, 1500);
}




function scheduleDashboardTaskForActiveUser(task, delayMs) {
    const userId = getActiveDashboardUserId();
    const adminView = !!window.isAdminViewing;
    if (!userId) return;

    setTimeout(function() {
        if (getActiveDashboardUserId() !== userId || (!!window.isAdminViewing) !== adminView) return;
        const fn = typeof task === 'string' ? window[task] : task;
        if (typeof fn !== 'function') return;
        try {
            const result = fn.call(window);
            if (result && typeof result.catch === 'function') {
                result.catch(function(e) {
                    console.warn('Dashboard refresh task failed:', fn.name || task, e);
                });
            }
        } catch (e) {
            console.warn('Dashboard refresh task failed:', fn.name || task, e);
        }
    }, delayMs || 0);
}

function isOnboardingNavigationLocked() {
    const wizard = document.getElementById('onboarding-wizard');
    const wizardIsOpen = !!(wizard && (
        wizard.classList.contains('active') ||
        wizard.style.display === 'flex' ||
        wizard.dataset.launchState
    ));
    return localStorage.getItem('onboardingComplete') !== 'true'
        && (window._onboardingWizardPending === true || wizardIsOpen);
}

function setOnboardingNavigationGate(locked) {
    const bottomNav = document.querySelector('.bottom-nav');
    if (bottomNav) {
        bottomNav.style.display = locked ? 'none' : 'flex';
        bottomNav.inert = locked;
        bottomNav.setAttribute('aria-hidden', locked ? 'true' : 'false');
    }

    const closeButton = document.getElementById('onboarding-wizard-close');
    if (closeButton) {
        const canExitPreview = window.metaAdTrialMode === true;
        closeButton.style.display = locked && !canExitPreview ? 'none' : '';
        closeButton.disabled = locked && !canExitPreview;
        closeButton.setAttribute('aria-hidden', locked && !canExitPreview ? 'true' : 'false');
    }
}

// Real switchAppTab implementation - replaces the early stub
function _switchAppTabReal(tabName, btn) {
    // First-run setup is a required guided gate. Keep this check at the shared
    // navigation boundary as a safety net even when another feature tries to
    // restore or invoke the bottom tabs while the wizard is open.
    if (isOnboardingNavigationLocked()) {
        setOnboardingNavigationGate(true);
        return false;
    }

    // Track current active tab for level-up animation visibility
    if (typeof currentActiveTab !== 'undefined') {
        currentActiveTab = tabName;
    }

    // Sync Spotify mini player visibility (only show on dashboard and movement tab)
    const _spotifyWidget = document.getElementById('spotify-now-playing');
    if (_spotifyWidget) {
        const showSpotify = (tabName === 'dashboard' || tabName === 'movement-tab') && window._snpPlaying;
        _spotifyWidget.style.display = showSpotify ? 'block' : 'none';
    }

    // 1. Update Bottom Nav UI
    document.querySelectorAll('.bottom-nav .nav-item').forEach(b => b.classList.remove('active'));
    if(btn) btn.classList.add('active');
    else {
        // simple fallback
    }

    // 1.5. Restore bottom navigation visibility for normal tabs
    const bottomNav = document.querySelector('.bottom-nav');
    if (bottomNav) bottomNav.style.display = 'flex';

    // 1.6. Clear Android navigation stack when switching to main tabs
    try {
        if (typeof clearNavigationStack === 'function') {
            clearNavigationStack();
        }
    } catch(e) { /* ignore — navigationStack may not be initialized yet */ }

    // 2. Clear All Views
    hideAllAppViews();

    // 2.5. iOS: keep the model-viewer loaded across tab switches.
    // The old approach removed src to free GPU memory, but this forced
    // a full model reload (frozen character) every time the user returned
    // to the home tab. Since the dashboard view itself is hidden via
    // display:none (step 2 hideAllAppViews), the GPU isn't rendering the
    // model while on other tabs — memory impact is minimal.

    // 3. Show Target View
    if (tabName === 'dashboard') {
        document.getElementById('view-dashboard').style.display = 'block';

        // Show pending level-up celebration if user leveled up while on another screen
        // (This is a fallback - the new celebration system auto-navigates, so this rarely triggers)
        if (typeof pendingLevelUp !== 'undefined' && pendingLevelUp) {
            setTimeout(() => {
                triggerLevelUpCelebration(
                    pendingLevelUp.level,
                    pendingLevelUp.title,
                    pendingLevelUp.previousLevel,
                    pendingLevelUp.lifetimePoints,
                    pendingLevelUp.currentStreak || 0,
                    pendingLevelUp.previousProgress || 0
                );
                pendingLevelUp = null;
            }, 500);
        }

        // Check for celebration that was interrupted by page reload
        if (typeof checkPendingLevelUpCelebration === 'function') {
            setTimeout(() => checkPendingLevelUpCelebration(), 1500);
        }

        // Hide Today's Priority section if user doesn't have meal plan access
        const todaysPrioritySection = document.getElementById('todays-priority-section');
        if (todaysPrioritySection) {
            const access = typeof checkMealPlanAccess === 'function' ? checkMealPlanAccess() : { hasAccess: true };
            todaysPrioritySection.style.display = access.hasAccess ? '' : 'none';
        }

        // Stagger home data refreshes so the first screen can paint before
        // Supabase/API-heavy cards compete for the main thread.
        if (typeof loadCoinBalance === 'function') scheduleDashboardTaskForActiveUser(loadCoinBalance, 75);
        if (typeof loadHomeChallenges === 'function') scheduleDashboardTaskForActiveUser(loadHomeChallenges, 150);
        if (typeof renderFeaturedRareCard === 'function') scheduleDashboardTaskForActiveUser(renderFeaturedRareCard, 225);
        if (typeof checkAndShowWeighInModal === 'function') scheduleDashboardTaskForActiveUser(checkAndShowWeighInModal, 275);
        if (typeof checkAndShowWeighInCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowWeighInCard, 325);
        if (typeof checkAndShowMoodCheckinCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowMoodCheckinCard, 425);
        if (typeof checkAndShowFitnessDiaryCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowFitnessDiaryCard, 525);
        if (typeof checkAndShowDailyQuizCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowDailyQuizCard, 625);
        if (typeof checkAndShowMealTipCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowMealTipCard, 725);
        if (typeof checkAndShowProgressPhotoCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowProgressPhotoCard, 825);
        if (typeof checkAndShowNudgeFriendsCard === 'function') scheduleDashboardTaskForActiveUser(checkAndShowNudgeFriendsCard, 1050);
        if (typeof window.renderFitbitImportedActivityHomeCard === 'function') scheduleDashboardTaskForActiveUser(window.renderFitbitImportedActivityHomeCard, 1125);
        if (typeof initPerformanceCard === 'function') scheduleDashboardTaskForActiveUser(initPerformanceCard, 1200);
        if (typeof refreshRaffleStateFromServer === 'function') scheduleDashboardTaskForActiveUser(refreshRaffleStateFromServer, 1350);
        if (typeof window.syncRareUnlocksFromServer === 'function') scheduleDashboardTaskForActiveUser(window.syncRareUnlocksFromServer, 1500);
        if (typeof checkAndDrawMonthlyRaffle === 'function') scheduleDashboardTaskForActiveUser(checkAndDrawMonthlyRaffle, 1650);
        if (typeof maybeShowMonthlyRafflePopup === 'function') scheduleDashboardTaskForActiveUser(maybeShowMonthlyRafflePopup, 1800);
        if (typeof checkAndCompleteExpiredChallenges === 'function') scheduleDashboardTaskForActiveUser(checkAndCompleteExpiredChallenges, 1950);
        if (typeof loadAdaptiveAdjustment === 'function') scheduleDashboardTaskForActiveUser(loadAdaptiveAdjustment, 2100);
        if (typeof refreshWeeklyMealEvolutionHomeCard === 'function') scheduleDashboardTaskForActiveUser(refreshWeeklyMealEvolutionHomeCard, 2250);
    } else if (tabName === 'meals') {
        document.getElementById('view-meals').style.display = 'block';

        // Initialize meal plan view (handles quiz vs non-quiz users)
        if (typeof initializeMealPlanView === 'function') {
            initializeMealPlanView();
        }

        if (!document.querySelector('#meals-content-container .view-section.active')) {
            // Default to calorie tracker for all users
            switchWeek('calorie-tracker');
        } else if (document.getElementById('today').classList.contains('active')) {
            renderTodayMeals(); // Refresh today view if active
        }
    } else if (tabName === 'movement-tab') {
        const el = document.getElementById('movement-tab');
        if(el) {
            el.classList.add('active');
            el.style.display='block';
            renderMovementView().catch(function(e) { console.error('renderMovementView error:', e); });

            // Auto-Check-in Logic (Once per day)
            const todayStr = new Date().toDateString();
            const lastAuto = localStorage.getItem('last_auto_checkin_date');

            // Auto check-in disabled per user request
            // if (lastAuto !== todayStr) { ... }
        }
    } else if (tabName === 'support') {
        // Support view removed - open coach chat modal instead
        openCoachChatModal();
    } else if (tabName === 'profile') {
        const el = document.getElementById('view-profile');
        if(el) {
            el.classList.add('active');
            el.style.display='block';
            // Decouple data loading so errors don't stop view from showing
            setTimeout(loadProfileData, 10);
            // Update settings icon when profile view is shown
            if (typeof updateSettingsIcon === 'function') {
                setTimeout(updateSettingsIcon, 100);
            }
            // Show/hide allocate battle stats button based on unallocated points
            setTimeout(() => {
                const allocBtn = document.getElementById('settings-allocate-stats-btn');
                if (allocBtn && typeof getUnallocatedPoints === 'function') {
                    const pts = getUnallocatedPoints();
                    allocBtn.style.display = pts > 0 ? 'flex' : 'none';
                }
            }, 200);
        }
    } else if (tabName === 'progress') {
        // Progress is now inside Movement tab - redirect there and open progress view
        const movEl = document.getElementById('movement-tab');
        if(movEl) {
            movEl.classList.add('active');
            movEl.style.display='block';
            renderMovementView();
        }
        // Auto-open progress view from movement
        setTimeout(() => { if(typeof openProgressFromMovement === 'function') openProgressFromMovement(); }, 100);
    } else if (tabName === 'learning') {
        const el = document.getElementById('view-learning');
        if(el) {
            el.style.display = 'block';
            if(typeof initLearning === 'function') initLearning();
        }
    } else if (tabName === 'ask-balance') {
        const el = document.getElementById('view-ask-balance');
        if(el) {
            el.style.display = 'flex';
            if (typeof window.refreshAskBalanceTitleColor === 'function') {
                window.refreshAskBalanceTitleColor();
            }
            setTimeout(function() {
                var input = document.getElementById('ai-assistant-input');
                if (input) input.focus();
            }, 100);
        }
    } else if (tabName === 'cycle') {
        const el = document.getElementById('view-cycle');
        if(el) {
            el.style.display = 'block';
            if(typeof initCycleView === 'function') initCycleView();
        }
    } else if (tabName === 'friends') {
        const el = document.getElementById('view-friends');
        if(el) {
            el.style.display = 'block';
            if(typeof initFriendsView === 'function') initFriendsView();
        }
    }

    // Trigger Cycle Sync Check if entering Dashboard
    if(tabName === 'dashboard' && typeof checkAndRenderCycleSync === 'function') {
        scheduleDashboardTaskForActiveUser(checkAndRenderCycleSync, 500);
    }

    window.scrollTo(0,0);
}

// Mark real implementation as ready and process any queued calls
_switchAppTabReady = true;
switchAppTab = _switchAppTabReal;
if (_switchAppTabQueue && _switchAppTabQueue.length > 0) {
    console.log('Processing ' + _switchAppTabQueue.length + ' queued switchAppTab calls');
    try {
        _switchAppTabQueue.forEach(function(call) {
            _switchAppTabReal(call.tabName, call.btn);
        });
    } catch(e) { console.error('switchAppTab queue replay error:', e); }
    _switchAppTabQueue = [];
}

function _waitForBalanceShortcut(label, predicate, onReady, onTimeout) {
    var attempts = 0;
    var timer = setInterval(function() {
        attempts++;
        var result = null;
        try { result = predicate(); } catch(e) { result = null; }
        if (result) {
            clearInterval(timer);
            try { onReady(result); } catch(e) { console.warn('Shortcut action failed:', label, e); }
        } else if (attempts > 70) {
            clearInterval(timer);
            if (typeof onTimeout === 'function') onTimeout();
            else console.warn('Shortcut target was not ready:', label);
        }
    }, 200);
}

function _balanceShortcutNavButton(fragment) {
    return document.querySelector('.bottom-nav .nav-item[onclick*="' + fragment + '"]');
}

function _dismissShortcutLoadingOverlay() {
    var overlay = document.getElementById('login-loading-overlay');
    if (!overlay || !overlay.parentNode) return;
    overlay.classList.add('fade-out');
    setTimeout(function() {
        if (overlay.parentNode) overlay.remove();
    }, 120);
}

function _clearBalanceShortcutLaunchState(action) {
    if (!action) return;
    if (window._pendingBalanceShortcutAction === action) window._pendingBalanceShortcutAction = null;
    if (window._pbbShortcutLaunchAction === action) window._pbbShortcutLaunchAction = null;
}

function _hideShortcutElement(id) {
    var el = document.getElementById(id);
    if (!el) return;
    var classDrivenModal = /^(meal-builder-modal|meal-builder-text-modal|meal-builder-portion-modal|meal-text-modal|recent-meals-modal)$/.test(id);
    el.style.display = classDrivenModal ? '' : 'none';
    el.classList.remove('visible');
    el.classList.remove('hidden-for-camera');
    el.classList.remove('active');
}

function _closeMealShortcutSurfaces(targetFnName) {
    try {
        if (document.activeElement && typeof document.activeElement.blur === 'function') {
            document.activeElement.blur();
        }
    } catch(e) {}

    if (targetFnName !== 'openQuickMealTextInput') {
        if (typeof window.closeQuickMealTextInput === 'function') {
            try { window.closeQuickMealTextInput(); } catch(e) { _hideShortcutElement('quick-meal-text-overlay'); }
        } else {
            _hideShortcutElement('quick-meal-text-overlay');
        }
    }

    if (targetFnName !== 'openQuickManualEntry') {
        if (typeof window.closeQuickManualEntry === 'function') {
            try { window.closeQuickManualEntry(); } catch(e) { _hideShortcutElement('quick-manual-entry-overlay'); }
        } else {
            _hideShortcutElement('quick-manual-entry-overlay');
        }
    }

    if (targetFnName !== 'openMealBuilder') {
        if (typeof window.closeMealBuilder === 'function') {
            try { window.closeMealBuilder(); } catch(e) { _hideShortcutElement('meal-builder-modal'); }
        } else {
            _hideShortcutElement('meal-builder-modal');
        }
    }

    if (targetFnName !== 'openRecentMealsModal') {
        if (typeof window.closeRecentMealsModal === 'function') {
            try { window.closeRecentMealsModal(); } catch(e) { _hideShortcutElement('recent-meals-modal'); }
        } else {
            _hideShortcutElement('recent-meals-modal');
        }
    }

    ['meal-builder-text-modal',
     'meal-builder-portion-modal',
     'meal-preview-modal',
     'meal-text-modal',
     'barcode-result-modal',
     'unified-camera-modal',
     'workout-camera-modal'].forEach(_hideShortcutElement);
}

function _runMealShortcut(label, fnName, args, options) {
    window._pbbMealShortcutActive = true;
    window._pbbMealShortcutSequence = (window._pbbMealShortcutSequence || 0) + 1;
    var shortcutSequence = window._pbbMealShortcutSequence;
    var shortcutAction = options && options.action;
    _clearBalanceShortcutLaunchState(shortcutAction);
    _closeMealShortcutSurfaces(fnName);

    var invoke = function() {
        var ensure = typeof window.ensureMealTrackerScripts === 'function'
            ? window.ensureMealTrackerScripts(options || {})
            : Promise.resolve();

        Promise.resolve(ensure).then(function() {
            if (shortcutSequence !== window._pbbMealShortcutSequence) return;
            var fn = window[fnName];
            if (typeof fn !== 'function') return;
            _dismissShortcutLoadingOverlay();
            _clearBalanceShortcutLaunchState(shortcutAction);
            _closeMealShortcutSurfaces(fnName);
            fn.apply(window, args || []);
        }).catch(function(e) {
            console.warn('Meal shortcut failed:', label, e);
        });
    };

    if (typeof window[fnName] === 'function' || typeof window.ensureMealTrackerScripts === 'function') {
        invoke();
        return true;
    }

    _waitForBalanceShortcut(label, function() {
        return (typeof window[fnName] === 'function' || typeof window.ensureMealTrackerScripts === 'function') ? true : null;
    }, invoke);
    return true;
}

function _handleBalanceShortcutAction(action) {
    if (!action) return false;
    _clearBalanceShortcutLaunchState(action);

    if (action === 'ask-balance') {
        switchAppTab('ask-balance');
        return true;
    }

    if (action === 'feed') {
        switchAppTab('friends', _balanceShortcutNavButton('friends'));
        return true;
    }

    if (action === 'feed-photo') {
        switchAppTab('friends', _balanceShortcutNavButton('friends'));
        _waitForBalanceShortcut('feed photo', function() {
            return (document.getElementById('story-upload-modal') && document.getElementById('story-file-input')) ? true : null;
        }, function() {
            _dismissShortcutLoadingOverlay();
            var modal = document.getElementById('story-upload-modal');
            var fileInput = document.getElementById('story-file-input');
            if (modal) modal.style.display = 'flex';
            if (fileInput && typeof fileInput.click === 'function') {
                setTimeout(function() { fileInput.click(); }, 80);
            }
        });
        return true;
    }

    if (action === 'today-workout') {
        switchAppTab('movement-tab', _balanceShortcutNavButton('movement'));
        _waitForBalanceShortcut('today workout', function() {
            return document.getElementById('today-workout-card');
        }, function(card) {
            card.click();
        }, function() {
            switchAppTab('movement-tab', _balanceShortcutNavButton('movement'));
        });
        return true;
    }

    if (action === 'meal-plan') {
        switchAppTab('meals', _balanceShortcutNavButton('meals'));
        _waitForBalanceShortcut('meal plan', function() {
            return (typeof switchWeek === 'function' && document.getElementById('browse-plans-pill'))
                ? document.getElementById('browse-plans-pill')
                : null;
        }, function(pill) {
            switchWeek('meal-plan-store', pill);
        });
        return true;
    }

    if (action === 'fitgotchi') {
        switchAppTab('dashboard', _balanceShortcutNavButton('dashboard'));
        setTimeout(function() {
            var widget = document.getElementById('tamagotchi-widget-container');
            if (widget && widget.scrollIntoView) widget.scrollIntoView({ block: 'start', behavior: 'smooth' });
            if (typeof reloadTamagotchiModel === 'function') reloadTamagotchiModel();
        }, 300);
        return true;
    }

    if (action === 'daily-quiz') {
        switchAppTab('dashboard', _balanceShortcutNavButton('dashboard'));
        _waitForBalanceShortcut('daily quiz', function() {
            return (typeof window.checkAndShowDailyQuizCard === 'function' && document.getElementById('daily-quiz-card')) ? true : null;
        }, function() {
            _dismissShortcutLoadingOverlay();
            Promise.resolve(window.checkAndShowDailyQuizCard()).then(function() {
                var card = document.getElementById('daily-quiz-card');
                if (card && card.style.display !== 'none') {
                    card.click();
                    return;
                }
                var doneCard = document.getElementById('daily-quiz-done-card');
                if (doneCard && doneCard.style.display !== 'none' && doneCard.scrollIntoView) {
                    doneCard.scrollIntoView({ block: 'center', behavior: 'smooth' });
                    return;
                }
                switchAppTab('learning', _balanceShortcutNavButton('learning'));
            }).catch(function() {
                switchAppTab('learning', _balanceShortcutNavButton('learning'));
            });
        }, function() {
            switchAppTab('learning', _balanceShortcutNavButton('learning'));
        });
        return true;
    }

    if (action === 'coach') {
        _waitForBalanceShortcut('coach message', function() {
            return (typeof openCoachChatModal === 'function') ? openCoachChatModal : null;
        }, function(fn) { fn(); });
        return true;
    }

    if (action === 'form-check') {
        switchAppTab('movement-tab', _balanceShortcutNavButton('movement'));
        _waitForBalanceShortcut('form check', function() {
            return (typeof openFormCheck === 'function') ? openFormCheck : null;
        }, function(fn) { fn({ source: 'ask-balance' }); });
        return true;
    }

    if (action === 'workout-library') {
        switchAppTab('movement-tab', _balanceShortcutNavButton('movement'));
        _waitForBalanceShortcut('workout library', function() {
            return (typeof openWorkoutLibrary === 'function') ? openWorkoutLibrary : null;
        }, function(fn) { fn(); });
        return true;
    }

    if (action === 'workout-builder') {
        switchAppTab('movement-tab', _balanceShortcutNavButton('movement'));
        _waitForBalanceShortcut('workout builder', function() {
            return (typeof openWorkoutBuilder === 'function') ? openWorkoutBuilder : null;
        }, function(fn) { fn(); });
        return true;
    }

    if (action === 'meal-builder') {
        return _runMealShortcut('meal builder', 'openMealBuilder', [], { withBuilder: true, action: action });
    }

    if (action === 'quick-log') {
        window._quickMealMode = false;
        return _runMealShortcut('quick log', 'openQuickMealTextInput', [], { action: action });
    }

    if (action === 'quick-log-photo') {
        return _runMealShortcut('meal photo', 'openMealCameraDirect', ['widget'], { action: action });
    }

    if (action === 'barcode') {
        return _runMealShortcut('barcode scanner', 'openMealBarcodeScanner', ['widget'], { action: action });
    }

    if (action === 'manual-log') {
        return _runMealShortcut('manual macros', 'openQuickManualEntry', ['widget'], { action: action });
    }

    if (action === 'recent-meals') {
        return _runMealShortcut('recent meals', 'openRecentMealsModal', [], { action: action });
    }

    if (action === 'calorie-tracker') {
        switchAppTab('meals', _balanceShortcutNavButton('meals'));
        _waitForBalanceShortcut('calorie tracker', function() {
            return (typeof switchWeek === 'function' && document.getElementById('calorie-tracker')) ? true : null;
        }, function() {
            switchWeek('calorie-tracker', document.querySelector('.pill-btn[onclick*="calorie-tracker"]'));
        });
        return true;
    }

    if (action === 'movement') {
        switchAppTab('movement-tab', _balanceShortcutNavButton('movement'));
        return true;
    }

    if (action === 'weigh-in') {
        switchAppTab('dashboard', _balanceShortcutNavButton('dashboard'));
        _waitForBalanceShortcut('daily weigh-in', function() {
            return (typeof window.checkAndShowWeighInCard === 'function' && document.getElementById('daily-weigh-in-card')) ? true : null;
        }, function() {
            _dismissShortcutLoadingOverlay();
            Promise.resolve(window.checkAndShowWeighInCard()).then(function() {
                var card = document.getElementById('daily-weigh-in-card');
                if (card && card.style.display !== 'none' && card.scrollIntoView) {
                    card.scrollIntoView({ block: 'center', behavior: 'smooth' });
                    return;
                }
                var doneCard = document.getElementById('daily-weigh-in-done-card');
                if (doneCard && doneCard.style.display !== 'none' && doneCard.scrollIntoView) {
                    doneCard.scrollIntoView({ block: 'center', behavior: 'smooth' });
                }
            });
        });
        return true;
    }

    if (action === 'mood-check') {
        switchAppTab('dashboard', _balanceShortcutNavButton('dashboard'));
        _waitForBalanceShortcut('mood check', function() {
            return (typeof window.checkAndShowMoodCheckinCard === 'function' && document.getElementById('mood-checkin-card')) ? true : null;
        }, function() {
            _dismissShortcutLoadingOverlay();
            Promise.resolve(window.checkAndShowMoodCheckinCard()).then(function() {
                var card = document.getElementById('mood-checkin-card');
                if (card && card.style.display !== 'none' && card.scrollIntoView) {
                    card.scrollIntoView({ block: 'center', behavior: 'smooth' });
                    return;
                }
                var doneCard = document.getElementById('mood-checkin-done-card');
                if (doneCard && doneCard.style.display !== 'none' && doneCard.scrollIntoView) {
                    doneCard.scrollIntoView({ block: 'center', behavior: 'smooth' });
                }
            });
        });
        return true;
    }

    if (action === 'dashboard') {
        switchAppTab('dashboard', _balanceShortcutNavButton('dashboard'));
        return true;
    }

    return false;
}

window.handleBalanceShortcutAction = _handleBalanceShortcutAction;
if (window._pendingBalanceShortcutAction) {
    var _pendingBalanceShortcutAction = window._pendingBalanceShortcutAction;
    window._pendingBalanceShortcutAction = null;
    _handleBalanceShortcutAction(_pendingBalanceShortcutAction);
}

// Check for pending app shortcut action (long-press icon -> native route)
try {
    if (window.NativePermissions && typeof window.NativePermissions.getPendingShortcutAction === 'function') {
        var _shortcutAction = window.NativePermissions.getPendingShortcutAction();
        if (_shortcutAction === 'admin-dashboard') {
            if (window.isBalanceAdminEmail && window.isBalanceAdminEmail(window.currentUser && window.currentUser.email)) {
                window.location.href = '/admin-dashboard.html';
            } else {
                console.warn('Admin dashboard shortcut ignored for non-admin user');
            }
        } else if (_shortcutAction === 'build-meal') {
            // Launched from QuickMealActivity's "+ Build New Meal" button.
            // Wait for openMealBuilder to be defined, then open it.
            var _bmAttempts = 0;
            var _bmInterval = setInterval(function() {
                _bmAttempts++;
                if (typeof openMealBuilder === 'function') {
                    clearInterval(_bmInterval);
                    openMealBuilder();
                } else if (_bmAttempts > 60) {
                    clearInterval(_bmInterval);
                    console.warn('Build meal shortcut: openMealBuilder never became available');
                }
            }, 200);
        } else if (_shortcutAction === 'calorie-tracker') {

            // Enable quick meal mode — after submit the app minimizes
            // and a local notification is fired with the meal summary.
            window._quickMealMode = true;

            // Signal early so the loading overlay skips its minimum wait time
            window._shortcutPhotoSessionActive = true;

            // Dismiss the loading overlay immediately so the meal preview isn't hidden behind it.
            function _dismissLoadingOverlayNow() {
                var _ov = document.getElementById('login-loading-overlay');
                if (_ov && _ov.parentNode) {
                    _ov.classList.add('fade-out');
                    setTimeout(function() { if (_ov.parentNode) _ov.remove(); }, 600);
                }
            }

            // Helper: once we have a native photo data-URL, wait for the meal preview
            // function to be ready then skip the camera and go straight to preview.
            function _applyNativeShortcutPhoto(dataUrl) {
                var _fnAttempts = 0;
                var _fnInterval = setInterval(function() {
                    _fnAttempts++;
                    if (typeof showMealPhotoPreview === 'function' && typeof capturedMealFile !== 'undefined') {
                        clearInterval(_fnInterval);
                        try {
                            var arr = dataUrl.split(',');
                            var mime = arr[0].match(/:(.*?);/)[1];
                            var bstr = atob(arr[1]);
                            var u8arr = new Uint8Array(bstr.length);
                            for (var i = 0; i < bstr.length; i++) u8arr[i] = bstr.charCodeAt(i);
                            var blob = new Blob([u8arr], { type: mime });
                            capturedMealFile = new File([blob], 'meal-' + Date.now() + '.jpg', { type: mime });
                            var reader = new FileReader();
                            reader.onload = function(e) {
                                // Dismiss loading overlay first so it doesn't cover the preview
                                _dismissLoadingOverlayNow();
                                showMealPhotoPreview(e.target.result);
                            };
                            reader.readAsDataURL(capturedMealFile);
                        } catch (e) {
                            console.warn('App shortcut: native photo apply failed, opening camera', e);
                            if (typeof openMealCameraDirect === 'function') openMealCameraDirect('shortcut');
                        }
                    } else if (_fnAttempts > 50) {
                        clearInterval(_fnInterval);
                        if (typeof openMealCameraDirect === 'function') openMealCameraDirect('shortcut');
                    }
                }, 200);
            }

            // Check whether the native Android camera was launched for this shortcut.
            // consumePendingNativePhoto() returns:
            //   ""         — photo still processing (keep polling)
            //   "data:..."  — photo ready
            //   null        — no native camera used (open in-app camera instead)
            var _nativePhoto = null;
            var _nativePhotoAvailable = false;
            if (typeof window.NativePermissions.consumePendingNativePhoto === 'function') {
                _nativePhoto = window.NativePermissions.consumePendingNativePhoto();
                _nativePhotoAvailable = (_nativePhoto !== null);
            }

            if (_nativePhotoAvailable) {
                if (_nativePhoto !== '') {
                    // Photo already encoded and ready
                    console.log('App shortcut: native photo ready, showing preview');
                    _applyNativeShortcutPhoto(_nativePhoto);
                } else {
                    // Still encoding — poll until ready (usually < 1 s)
                    console.log('App shortcut: native photo processing, polling...');
                    var _photoAttempts = 0;
                    var _photoInterval = setInterval(function() {
                        _photoAttempts++;
                        var _p = null;
                        try { _p = window.NativePermissions.consumePendingNativePhoto(); } catch(e) {}
                        if (_p && _p !== '') {
                            clearInterval(_photoInterval);
                            console.log('App shortcut: native photo ready after poll');
                            _applyNativeShortcutPhoto(_p);
                        } else if (_p === null || _photoAttempts > 50) {
                            // Cancelled or timeout — show quick text input in quick mode
                            clearInterval(_photoInterval);
                            if (window._quickMealMode && typeof openQuickMealTextInput === 'function') {
                                _dismissLoadingOverlayNow();
                                openQuickMealTextInput();
                            } else if (typeof openMealCameraDirect === 'function') {
                                openMealCameraDirect('shortcut');
                            }
                        }
                    }, 200);
                }
            } else {
                // No native camera photo — show quick text input or open in-app camera
                console.log('App shortcut: waiting for functions to be ready');
                window._pendingShortcutCamera = true;
                var _shortcutAttempts = 0;
                var _shortcutInterval = setInterval(function() {
                    _shortcutAttempts++;
                    if (window._quickMealMode && typeof openQuickMealTextInput === 'function') {
                        clearInterval(_shortcutInterval);
                        console.log('App shortcut: opening quick text input');
                        _dismissLoadingOverlayNow();
                        openQuickMealTextInput();
                        window._pendingShortcutCamera = false;
                    } else if (typeof openMealCameraDirect === 'function') {
                        clearInterval(_shortcutInterval);
                        console.log('App shortcut: opening calorie tracker camera');
                        openMealCameraDirect('shortcut');
                        window._pendingShortcutCamera = false;
                    } else if (_shortcutAttempts > 50) {
                        clearInterval(_shortcutInterval);
                        console.warn('App shortcut: camera function never became available');
                        window._pendingShortcutCamera = false;
                    }
                }, 200);
            }
        } else {
            _handleBalanceShortcutAction(_shortcutAction);
        }

    }

    // Always check for a pending quick meal from QuickMealActivity.
    // The native overlay calls the API itself and fires the notification,
    // but the result still needs to be persisted to Supabase next time the
    // app opens. This runs silently regardless of which shortcut was used.
    var _qmAttempts = 0;
    var _qmInterval = setInterval(function() {
        _qmAttempts++;
        if (typeof _processQuickMealFromNative === 'function') {
            clearInterval(_qmInterval);
            _processQuickMealFromNative();
        } else if (_qmAttempts > 50) {
            clearInterval(_qmInterval);
        }
    }, 200);
} catch(e) { console.warn('Shortcut check failed:', e); }

// --- CALENDAR & CYCLE LOGIC ---
const PHASE_INFO = {
    menstrual: { name: 'Menstrual Phase', color: '#E57373', css: 'phase-menstrual', rec: 'Rest, Walking, Yin Yoga', hideHeroRec: true, icon: '🩸' },
    follicular: { name: 'Follicular Phase', color: '#F06292', css: 'phase-follicular', rec: 'HIIT, Strength, Cardio', icon: '⚡' },
    ovulation: { name: 'Ovulation Phase', color: '#BA68C8', css: 'phase-ovulation', rec: 'Max Effort, PB Attempts', icon: '🥚' },
    luteal: { name: 'Luteal Phase', color: '#FFB74D', css: 'phase-luteal', rec: 'Strength (Mod), Pilates', icon: '🌙' },
    wellness: { name: 'Wellness Cycle', color: '#4DB6AC', css: 'phase-follicular', rec: 'Balanced Activity / Strength', icon: '🌿' },
    performance: { name: 'Performance Mode', color: '#3b82f6', css: 'phase-performance', rec: 'Strength, HIIT, Progressive Overload', icon: '💪' }
};

// Update userCycleData (already declared early to prevent undefined errors)
userCycleData = {
    lastPeriod: null,
    cycleLength: 28,
    mood: null, // 'strong' or 'tired'
    noPeriodMode: false,
    symptoms: [],
    logs: {}, // { "YYYY-MM-DD": { flow, symptoms:[], mood, energy } }
    dailyCheckIn: null // { date: "YYYY-MM-DD", status: "completed" }
};

function setCycleMood(mood, btn) {
    userCycleData.mood = mood;
    // UI Update
    document.querySelectorAll('.mood-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    
    // Re-render suggestions
    renderCycleStatus();
    renderWeeklyCalendar();
}

function toggleNoPeriodMode() {
    const isChecked = document.getElementById('no-period-toggle-profile').checked;
    userCycleData.noPeriodMode = isChecked;

    const inputContainer = document.getElementById('last-period-input-profile');
    if(inputContainer) inputContainer.disabled = isChecked;

    updateCycleData();
}

async function initCalendarView() {
    // 1. Try to load from localStorage first (works for non-logged-in users)
    try {
        const savedCycleData = localStorage.getItem('userCycleData');
        if (savedCycleData) {
            const parsed = JSON.parse(savedCycleData);
            if (parsed.lastPeriod) {
                userCycleData.lastPeriod = parsed.lastPeriod;
                const lastPeriodInput = document.getElementById('last-period-input-profile');
                if (lastPeriodInput) lastPeriodInput.value = userCycleData.lastPeriod;
            }
            if (parsed.cycleLength) {
                userCycleData.cycleLength = parseInt(parsed.cycleLength);
                const cycleLengthInput = document.getElementById('cycle-length-input-profile');
                if (cycleLengthInput) cycleLengthInput.value = userCycleData.cycleLength;
            }
            if (parsed.noPeriodMode) {
                userCycleData.noPeriodMode = true;
                const noPeriodToggle = document.getElementById('no-period-toggle-profile');
                if (noPeriodToggle) noPeriodToggle.checked = true;
                const lastPeriodInput = document.getElementById('last-period-input-profile');
                if (lastPeriodInput) lastPeriodInput.disabled = true;
            }
            // Load logs for Cycle Sync
            if (parsed.logs) {
                userCycleData.logs = parsed.logs;
            }
            if (parsed.workoutDayOrder) {
                cacheWorkoutDayOrder(parsed.workoutDayOrder);
            }
        }
    } catch (e) {
        console.log("Error loading cycle data from localStorage", e);
    }

    // 2. Fetch Cycle Data from DB (user_facts) - overrides localStorage if logged in
    if (window.currentUser) {
        try {
            const userId = window.currentUser.id || window.currentUser.user_id;
            const facts = typeof window.getUserFacts === 'function'
                ? await window.getUserFacts()
                : await dbHelpers.userFacts.get(userId);
            console.log('📊 Loaded user_facts from DB:', facts);
            console.log('📊 additional_data:', facts?.additional_data);
            if (facts && facts.additional_data) {
                if (facts.additional_data.last_period_start) {
                    userCycleData.lastPeriod = facts.additional_data.last_period_start;
                    const lastPeriodInput = document.getElementById('last-period-input-profile');
                    if (lastPeriodInput) lastPeriodInput.value = userCycleData.lastPeriod;
                    console.log('✅ Loaded lastPeriod from DB:', userCycleData.lastPeriod);
                }
                if (facts.additional_data.cycle_length) {
                    userCycleData.cycleLength = parseInt(facts.additional_data.cycle_length);
                    const cycleLengthInput = document.getElementById('cycle-length-input-profile');
                    if (cycleLengthInput) cycleLengthInput.value = userCycleData.cycleLength;
                    console.log('✅ Loaded cycleLength from DB:', userCycleData.cycleLength);
                }
                if (facts.additional_data.no_period_mode) {
                    userCycleData.noPeriodMode = true;
                    const noPeriodToggle = document.getElementById('no-period-toggle-profile');
                    if (noPeriodToggle) noPeriodToggle.checked = true;
                    const lastPeriodInput = document.getElementById('last-period-input-profile');
                    if (lastPeriodInput) lastPeriodInput.disabled = true;
                    console.log('✅ Loaded noPeriodMode from DB:', userCycleData.noPeriodMode);
                }

                if (facts.additional_data.workout_day_order) {
                    cacheWorkoutDayOrder(facts.additional_data.workout_day_order);
                    console.log('Loaded workout day order from DB:', getWorkoutDayOrder());
                }

                // Load dismissed dates for tip cards to prevent them reappearing
                if (facts.additional_data.dismissed_dates) {
                    window._pbbDismissedDates = facts.additional_data.dismissed_dates;
                    console.log('✅ Loaded dismissed dates from DB:', window._pbbDismissedDates);
                }
            } else {
                console.warn('⚠️ No additional_data found in user_facts');
            }
        } catch (e) {
            console.log("❌ No existing cycle data found or error fetching", e);
        }

        // Load active custom program so the weekly calendar shows the user's
        // own schedule instead of the equipment fallback. Without this, users
        // who open Cycle before Movement see a generic schedule.
        try {
            if (typeof dbHelpers !== 'undefined' && dbHelpers.customPrograms) {
                const userId = window.currentUser.id || window.currentUser.user_id;
                window.activeCustomProgramCache = await dbHelpers.customPrograms.getActive(userId);
            }
        } catch (e) {
            console.warn('Failed to load active custom program for cycle calendar', e);
        }
    }

    renderCycleStatus();
    renderWeeklyCalendar();

    // Restore saved calendar view preference (weekly/monthly)
    const savedViewPref = localStorage.getItem('calendarViewPreference');
    if (savedViewPref === 'monthly') {
        switchCalendarView('monthly');
    }
}

async function updateCycleData() {
    const startInput = document.getElementById('last-period-input-profile').value;
    const lengthInput = document.getElementById('cycle-length-input-profile').value;
    const noPeriod = document.getElementById('no-period-toggle-profile').checked;

    userCycleData.noPeriodMode = noPeriod;

    if (!noPeriod && !startInput) return; // Wait for input if not in wellness mode

    userCycleData.lastPeriod = startInput;
    userCycleData.cycleLength = parseInt(lengthInput);

    // Always save to localStorage first (works for all users)
    localStorage.setItem('userCycleData', JSON.stringify(userCycleData));

    // Also save to DB if logged in (background, non-blocking)
    if (window.currentUser) {
        (async () => {
            try {
                const userId = window.currentUser.id || window.currentUser.user_id;
                let existingFacts = {};
                try {
                    existingFacts = await dbHelpers.userFacts.get(userId);
                } catch(err) { /* ignore not found */ }
                
                const currentAdditional = existingFacts?.additional_data || {};
                
                await dbHelpers.userFacts.upsert(userId, {
                    additional_data: {
                        ...currentAdditional,
                        last_period_start: userCycleData.lastPeriod,
                        cycle_length: userCycleData.cycleLength,
                        no_period_mode: userCycleData.noPeriodMode,
                        workout_day_order: getWorkoutDayOrder()
                    }
                });
            } catch (e) {
                // DB save failed but localStorage worked, user data is safe
                console.warn("Cycle data saved locally. Cloud sync pending.", e.message);
            }
        })();
    }

    renderCycleStatus();
    renderWeeklyCalendar();

    // Also update monthly calendar if visible
    const monthlyCalendar = document.getElementById('monthly-calendar');
    if (monthlyCalendar && monthlyCalendar.style.display !== 'none') {
        renderMonthlyCalendar();
    }
}

function getCyclePhase(dayOfCycle, cycleLen) {
    // For male users, always return 'performance' (no cycle tracking)
    if (typeof isMaleUser === 'function' && isMaleUser()) {
        return 'performance';
    }

    // Basic Algo
    // Day 1-5: Menstrual
    // Day 6-13: Follicular
    // Day 14: Ovulation (approx mid-cycle)
    // Day 15-End: Luteal

    // Adjust for cycle length:
    // Menstrual is usually fixed ~5
    // Luteal is usually fixed ~14 days before end.
    // Follicular varies.

    const ovulationDay = cycleLen - 14;

    if (dayOfCycle <= 5) return 'menstrual';
    if (dayOfCycle < ovulationDay) return 'follicular';
    if (dayOfCycle === ovulationDay) return 'ovulation';
    return 'luteal';
}

function renderCycleStatus() {
    // For male users, show Performance Mode (no cycle tracking)
    if (typeof isMaleUser === 'function' && isMaleUser()) {
        const phase = PHASE_INFO['performance'];
        const phaseName = document.getElementById('cycle-phase-name');
        const phaseDesc = document.getElementById('cycle-phase-desc');
        const cycleDayDisplay = document.getElementById('cycle-day-display');

        if (phaseName) {
            phaseName.innerText = phase.name;
            phaseName.style.color = phase.color;
        }
        if (cycleDayDisplay && cycleDayDisplay.parentElement) {
            cycleDayDisplay.parentElement.style.display = 'none'; // Hide day counter for males
        }
        if (phaseDesc) {
            phaseDesc.style.display = '';
            phaseDesc.innerText = "Train based on energy and recovery. Push hard, recover smart.";
        }

        // Update recommendation
        let suggestion = phase.rec;
        const recText = document.getElementById('rec-text');
        if (recText) recText.innerText = suggestion;

        const recCard = document.getElementById('today-workout-rec');
        if (recCard) recCard.style.background = phase.color;

        return;
    }

    if (userCycleData.noPeriodMode) {
        // Wellness Mode View
        const phase = PHASE_INFO['wellness'];
        document.getElementById('cycle-phase-name').innerText = phase.name;
        document.getElementById('cycle-phase-name').style.color = phase.color;
        document.getElementById('cycle-day-display').innerText = "General Wellness";
        document.getElementById('cycle-phase-desc').style.display = '';
        document.getElementById('cycle-phase-desc').innerText = "Focus on a balanced routine of Strength, Cardio, and Rest.";
        
        const iconContainer = document.getElementById('cycle-phase-icon');
        if(iconContainer) {
            iconContainer.style.background = phase.color + '40';
            iconContainer.style.color = phase.color;
            iconContainer.innerHTML = phase.icon;
        }

        let suggestion = phase.rec;
        if (userCycleData.mood === 'tired') suggestion = "Rest / Light Walking";
        else if (userCycleData.mood === 'strong') suggestion = "Strength / HIIT";

        document.getElementById('rec-text').innerText = suggestion;
        const recCard = document.getElementById('today-workout-rec');
        if(recCard) recCard.style.background = phase.color;
        
        return;
    }

    if (!userCycleData.lastPeriod) {
        document.getElementById('cycle-phase-name').innerText = "Setup Required";
        document.getElementById('cycle-day-display').innerText = "Complete onboarding";
        document.getElementById('cycle-phase-desc').style.display = '';
        document.getElementById('cycle-phase-desc').innerText = "Go to Settings > Edit Profile to complete your onboarding and see your cycle insights.";
        return;
    }

    const start = new Date(userCycleData.lastPeriod);
    const today = new Date();
    const msPerDay = 24 * 60 * 60 * 1000;
    const daysSinceStart = Math.floor((today - start) / msPerDay);
    
    // Handle cycle looping
    let currentDayRaw = (daysSinceStart % userCycleData.cycleLength) + 1;
    if (currentDayRaw < 1) currentDayRaw = 1; // Basic safety

    const phaseKey = getCyclePhase(currentDayRaw, userCycleData.cycleLength);
    const phase = PHASE_INFO[phaseKey];

    document.getElementById('cycle-phase-name').innerText = phase.name;
    document.getElementById('cycle-phase-name').style.color = phase.color;
    document.getElementById('cycle-day-display').innerText = `Day ${currentDayRaw} of ${userCycleData.cycleLength}`;
    
    // Icon
    const iconContainer = document.getElementById('cycle-phase-icon');
    if(iconContainer) {
        iconContainer.style.background = phase.color + '40'; // Low opacity bg
        iconContainer.style.color = phase.color;
        iconContainer.innerHTML = phase.icon;
    }

    // Description & Suggestion based on Mood
    let suggestion = phase.rec;
    if (userCycleData.mood === 'tired') {
        suggestion = "Restorative Yoga / Stretching (Listen to body)";
        if (phaseKey === 'follicular') suggestion = "Light Cardio / Walk";
    } else if (userCycleData.mood === 'strong' && phaseKey === 'menstrual') {
        suggestion = "Light Resistance / Pilates";
    }

    const phaseDescription = document.getElementById('cycle-phase-desc');
    phaseDescription.style.display = phase.hideHeroRec ? 'none' : '';
    phaseDescription.innerText = phase.hideHeroRec ? '' : `You are in ${phase.name}. Usual focus: ${phase.rec}.`;
    
    // Update Today's Rec Card (if it exists)
    const recText = document.getElementById('rec-text');
    if(recText) recText.innerText = suggestion;
    
    const recCard = document.getElementById('today-workout-rec');
    if(recCard) recCard.style.background = phase.color;
    
}

