/**
 * Start the meal plan purchase flow
 */
function startMealPlanPurchase(planSlug) {
    console.log('Starting purchase flow for:', planSlug);
    // Open the preference wizard modal (defined in script block at bottom)
    if (typeof openPreferenceWizard === 'function') {
        openPreferenceWizard(planSlug);
    } else {
        console.error('Preference wizard not loaded');
        alert('Something went wrong. Please refresh and try again.');
    }
}

// ============================================================
// AI-GENERATED MEAL PLAN SYSTEM
// ============================================================

// In-memory cache of the current AI meal plan
let _aiMealPlanCache = null;
let _aiMealPlanCurrentWeek = 1;
let _aiMealPlanCurrentDay = 0;
let _aiMealPlanLoadPromise = null;
let _aiMealPlanGenerationInProgress = false;
let _aiMealPlanLoggedTypes = [];
let _aiMealPlanLoggedDayKey = '';
let _aiMealPlanMealSelection = null;
let _metaPreviewMealPlanBuildPromise = null;
let _metaPreviewMealPlanBuildSignature = '';
let _metaPreviewMealPlanBuildState = { status: 'idle', progress: 0, message: '' };

function getAiMealPlanTodayIndex() {
    const sundayFirstDay = new Date().getDay();
    return sundayFirstDay === 0 ? 6 : sundayFirstDay - 1;
}

function escapeAiPlanText(value) {
    return String(value ?? '').replace(/[&<>"']/g, character => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[character]);
}

function getAiPlanShoppingWeek() {
    if (!_aiMealPlanCache?.weeks) return null;
    return _aiMealPlanCache.weeks.find(week => Number(week.week_number) === Number(_aiMealPlanCurrentWeek)) || null;
}

function getAiPlanShoppingItems() {
    const helper = window.BalanceMealPlanShopping;
    return helper?.buildWeekItems ? helper.buildWeekItems(getAiPlanShoppingWeek()) : [];
}

function getAiPlanShoppingStorageKey() {
    const planKey = _aiMealPlanCache?.id || _aiMealPlanCache?.plan_name || 'meal-plan';
    return `pbb_ai_plan_shopping:${planKey}:week:${_aiMealPlanCurrentWeek}`;
}

function getAiPlanCheckedShoppingItems() {
    try {
        const saved = JSON.parse(localStorage.getItem(getAiPlanShoppingStorageKey()) || '[]');
        return new Set(Array.isArray(saved) ? saved.map(String) : []);
    } catch(e) {
        return new Set();
    }
}

function saveAiPlanCheckedShoppingItems(checked) {
    try {
        localStorage.setItem(getAiPlanShoppingStorageKey(), JSON.stringify(Array.from(checked)));
    } catch(e) {}
}

function updateAiPlanShoppingStatus(items, checked) {
    const status = document.getElementById('ai-plan-shopping-status');
    if (!status) return;
    status.textContent = items.length ? `${checked.size} of ${items.length} checked` : 'No ingredients found for this week';
}

function renderAiPlanShoppingList() {
    const list = document.getElementById('ai-plan-shopping-list');
    const summary = document.getElementById('ai-plan-shopping-summary');
    const download = document.getElementById('ai-plan-shopping-download');
    if (!list || !summary) return;

    const helper = window.BalanceMealPlanShopping;
    if (!helper?.buildWeekItems) {
        list.innerHTML = '';
        summary.textContent = 'Shopping list is loading';
        if (download) download.disabled = true;
        updateAiPlanShoppingStatus([], new Set());
        return;
    }

    const items = getAiPlanShoppingItems();
    const checked = getAiPlanCheckedShoppingItems();
    const availableKeys = new Set(items.map(item => item.key));
    const validChecked = new Set(Array.from(checked).filter(key => availableKeys.has(key)));
    if (validChecked.size !== checked.size) saveAiPlanCheckedShoppingItems(validChecked);

    summary.textContent = `Week ${_aiMealPlanCurrentWeek} · ${items.length} ingredient${items.length === 1 ? '' : 's'}`;
    list.innerHTML = items.map(item => {
        const isChecked = validChecked.has(item.key);
        const encodedKey = escapeAiPlanText(encodeURIComponent(item.key));
        return `<label class="ai-plan-shopping__item${isChecked ? ' is-checked' : ''}">
            <input type="checkbox" data-shopping-key="${encodedKey}" ${isChecked ? 'checked' : ''} onchange="updateAiPlanShoppingItem(this)">
            <span><strong>${escapeAiPlanText(item.name)}</strong>${item.amount ? `<small>${escapeAiPlanText(item.amount)}</small>` : ''}</span>
        </label>`;
    }).join('');

    if (download) download.disabled = items.length === 0;
    updateAiPlanShoppingStatus(items, validChecked);
}

function updateAiPlanShoppingItem(input) {
    let key = '';
    try { key = decodeURIComponent(input?.dataset?.shoppingKey || ''); } catch(e) {}
    if (!key) return;

    const checked = getAiPlanCheckedShoppingItems();
    if (input.checked) checked.add(key);
    else checked.delete(key);
    saveAiPlanCheckedShoppingItems(checked);
    input.closest('.ai-plan-shopping__item')?.classList.toggle('is-checked', input.checked);
    updateAiPlanShoppingStatus(getAiPlanShoppingItems(), checked);
}

function toggleAiPlanShoppingList(forceOpen) {
    const toggle = document.getElementById('ai-plan-shopping-toggle');
    const panel = document.getElementById('ai-plan-shopping-panel');
    if (!toggle || !panel) return false;

    const isOpen = typeof forceOpen === 'boolean' ? forceOpen : panel.hidden;
    panel.hidden = !isOpen;
    toggle.setAttribute('aria-expanded', String(isOpen));
    if (isOpen) renderAiPlanShoppingList();
    return isOpen;
}

async function openAiMealPlanShoppingList(btn, options = {}) {
    // The paid preview keeps its prepared plan locally until checkout. Moving
    // through the calorie tracker must not make the shopping-list handoff wait
    // on an older account plan or a second generation request.
    if (!_aiMealPlanCache && window.metaAdTrialMode === true) {
        try {
            const previewPlan = JSON.parse(localStorage.getItem('ai_meal_plan') || 'null');
            if (previewPlan && Array.isArray(previewPlan.weeks)) _aiMealPlanCache = previewPlan;
        } catch (e) {}
    }
    const planView = document.getElementById('meal-plan-store');
    const planAlreadyOpen = !!(planView && planView.classList.contains('active') && _aiMealPlanCache);
    if (!planAlreadyOpen) {
        openAiMealPlanView(btn || document.getElementById('meal-plan-shopping-pill'));
        if (typeof loadExistingAiMealPlan === 'function') await loadExistingAiMealPlan();
    }
    if (!_aiMealPlanCache) return;

    if (options.resetChecked === true) {
        try { localStorage.removeItem(getAiPlanShoppingStorageKey()); } catch(e) {}
    }
    renderAiPlanShoppingList();
    toggleAiPlanShoppingList(true);
    const card = document.getElementById('ai-plan-shopping-card');
    if (card) {
        try {
            card.scrollIntoView({
                behavior: options.scrollBehavior || 'smooth',
                block: options.scrollBlock || 'center'
            });
        } catch(e) {}
    }
}

function downloadAiPlanShoppingList() {
    const helper = window.BalanceMealPlanShopping;
    const items = getAiPlanShoppingItems();
    if (!helper?.toText || !items.length) return;

    const checked = getAiPlanCheckedShoppingItems();
    const text = helper.toText({
        planName: _aiMealPlanCache?.plan_name,
        weekNumber: _aiMealPlanCurrentWeek,
        items,
        checked
    });
    const url = URL.createObjectURL(new Blob(['\ufeff' + text], { type: 'text/plain;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `balance-week-${_aiMealPlanCurrentWeek}-shopping-list.txt`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);

    const status = document.getElementById('ai-plan-shopping-status');
    if (status) status.textContent = 'Shopping list downloaded';
}

function formatAiPlanPreparation(value) {
    const text = String(value || '').trim();
    if (!text) return '';
    const steps = text.split(/\s*(?=\d+\.\s+)/).map(step => step.replace(/^\d+\.\s*/, '').trim()).filter(Boolean);
    if (steps.length < 2) return `<p>${escapeAiPlanText(text)}</p>`;
    return `<ol>${steps.map(step => `<li>${escapeAiPlanText(step)}</li>`).join('')}</ol>`;
}

async function loadAiMealPlanLoggedTypes(dayNum) {
    const user = window.currentUser;
    const todayIndex = getAiMealPlanTodayIndex();
    if (!user || !window.supabaseClient || dayNum !== todayIndex) {
        _aiMealPlanLoggedTypes = [];
        _aiMealPlanLoggedDayKey = `inactive:${_aiMealPlanCurrentWeek}:${dayNum}`;
        return;
    }

    const dateKey = typeof getLocalDateString === 'function'
        ? getLocalDateString()
        : new Date().toISOString().slice(0, 10);
    const requestKey = `${user.id}:${dateKey}`;
    if (_aiMealPlanLoggedDayKey === requestKey || _aiMealPlanLoggedDayKey === `loading:${requestKey}`) return;
    _aiMealPlanLoggedDayKey = `loading:${requestKey}`;

    try {
        const { data, error } = await window.supabaseClient
            .from('meal_logs')
            .select('meal_type')
            .eq('user_id', user.id)
            .eq('meal_date', dateKey)
            .neq('meal_type', 'water');
        if (error) throw error;
        _aiMealPlanLoggedTypes = (data || []).map(row => row.meal_type).filter(Boolean);
    } catch (error) {
        console.warn('[meal-plan] could not read today\'s logged meals:', error);
        _aiMealPlanLoggedTypes = [];
    } finally {
        _aiMealPlanLoggedDayKey = requestKey;
        if (_aiMealPlanCurrentDay === dayNum) renderAiPlanDay(dayNum);
    }
}

function isAiMealPlanViewActive() {
    const storeSection = document.getElementById('meal-plan-store');
    return !!(storeSection && storeSection.classList.contains('active'));
}

function updateAiPlanGeneratingStatus(text, progressWidth) {
    const statusEl = document.getElementById('ai-plan-gen-status');
    const progressEl = document.getElementById('ai-plan-gen-progress');
    if (statusEl && text) statusEl.textContent = text;
    if (progressEl && progressWidth) progressEl.style.width = progressWidth;
}

function waitForCurrentUser(timeoutMs = 15000) {
    if (window.currentUser) return Promise.resolve(window.currentUser);

    return new Promise(resolve => {
        const startedAt = Date.now();
        const timer = setInterval(() => {
            if (window.currentUser) {
                clearInterval(timer);
                resolve(window.currentUser);
            } else if (Date.now() - startedAt >= timeoutMs) {
                clearInterval(timer);
                resolve(null);
            }
        }, 150);
    });
}

function areMealPlanDependenciesReady() {
    return typeof window.populatePreparedMealPlan === 'function'
        && typeof window.buildPreparedMealPlan === 'function'
        && typeof window.getUserNutritionTargets === 'function'
        && typeof window.isVeganChallengeUser === 'function'
        && typeof window.resolveMealPlanPhoto === 'function';
}

function resolveMealPlanPhotoUrl(meal) {
    try {
        if (typeof window.resolveMealPlanPhoto === 'function') return window.resolveMealPlanPhoto(meal) || '';
    } catch (error) {
        console.warn('[meal-plan] photo resolution failed:', error);
    }
    return String(meal?.image_url || meal?.image || '').trim();
}

async function persistResolvedMealPlanPhotos(rows) {
    const pending = (Array.isArray(rows) ? rows : []).filter(row => row?.id && row?.image_url);
    if (!pending.length || !window.supabaseClient) return;

    const grouped = new Map();
    pending.forEach(row => {
        if (!grouped.has(row.image_url)) grouped.set(row.image_url, []);
        grouped.get(row.image_url).push(row.id);
    });

    const results = await Promise.allSettled([...grouped.entries()].map(([imageUrl, ids]) =>
        window.supabaseClient.from('ai_generated_meals').update({ image_url: imageUrl }).in('id', ids)
    ));
    const failed = results.filter(result => result.status === 'rejected' || result.value?.error);
    if (failed.length) console.warn(`[meal-plan] ${failed.length} photo backfill batch(es) could not be saved`);
}

const _mealPhotoGenerationPlans = new Set();

function mealPhotoGenerationSignature(meal) {
    const ingredients = (Array.isArray(meal?.ingredients) ? meal.ingredients : []).map(ingredient =>
        typeof ingredient === 'string'
            ? ingredient
            : `${ingredient?.name || ''} ${ingredient?.amount || ''}`.trim()
    );
    return JSON.stringify([
        String(meal?.name || '').trim().toLowerCase(),
        String(meal?.description || '').trim().toLowerCase(),
        ingredients.map(value => value.toLowerCase())
    ]);
}

function mealsInPlan(plan) {
    return (plan?.weeks || []).flatMap(week =>
        (week.days || []).flatMap(day => day.meals || [])
    );
}

async function mealPhotoAuthToken() {
    if (window.authHelpers && typeof window.authHelpers.getSession === 'function') {
        const session = await window.authHelpers.getSession();
        if (session?.access_token) return session.access_token;
    }
    if (window.supabaseClient?.auth && typeof window.supabaseClient.auth.getSession === 'function') {
        const result = await window.supabaseClient.auth.getSession();
        return result?.data?.session?.access_token || '';
    }
    return '';
}

async function generateExactMealPhoto(meal, userId, planId, token) {
    const response = await fetch('/.netlify/functions/generate-meal-image', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
            mealName: meal.name,
            mealDescription: meal.description,
            ingredients: meal.ingredients || [],
            userId,
            planId,
            mealId: meal.id
        })
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || !result.success || !/^https:\/\//i.test(result.imageUrl || '')) {
        const failureStage = String(result.stage || 'photo_service').replace(/[^a-z_]/gi, '');
        throw new Error(`${result.error || `Meal photo generation failed (${response.status})`} [${failureStage}]`);
    }
    return result.imageUrl;
}

/**
 * Generate one exact photo per unique photo-less meal and persist it for every
 * matching row. Curated recipes keep their hand-picked exact photos.
 */
async function ensureExactMealPlanPhotos(plan, userId, options = {}) {
    const planId = plan?.id;
    if (!planId || !userId || _mealPhotoGenerationPlans.has(planId)) return { generated: 0, failed: 0 };

    const candidateMeals = Array.isArray(options.meals) ? options.meals : mealsInPlan(plan);
    const missing = candidateMeals.filter(meal =>
        meal?.id && window.resolveMealPlanPhotoDetails?.(meal)?.source === 'missing'
    );
    if (!missing.length) return { generated: 0, failed: 0 };

    const token = await mealPhotoAuthToken();
    if (!token) throw new Error('No active session for meal photo generation');

    const groups = new Map();
    missing.forEach(meal => {
        const signature = mealPhotoGenerationSignature(meal);
        if (!groups.has(signature)) groups.set(signature, []);
        groups.get(signature).push(meal);
    });

    _mealPhotoGenerationPlans.add(planId);
    const queue = [...groups.values()];
    let generated = 0;
    let failed = 0;
    let failureStage = '';
    let completed = 0;
    const worker = async () => {
        while (queue.length) {
            const group = queue.shift();
            const representative = group[0];
            try {
                const imageUrl = await generateExactMealPhoto(representative, userId, planId, token);
                const ids = group.map(meal => meal.id).filter(Boolean);
                const update = await window.supabaseClient
                    .from('ai_generated_meals')
                    .update({ image_url: imageUrl })
                    .in('id', ids);
                if (update.error) throw update.error;
                group.forEach(meal => { meal.image_url = imageUrl; });
                generated += 1;
                if (_aiMealPlanCache === plan) renderAiPlanDay(_aiMealPlanCurrentDay);
            } catch (error) {
                failed += 1;
                failureStage = String(error?.message || '').match(/\[([a-z_]+)\]/i)?.[1] || failureStage || 'photo_service';
                console.warn(`[meal-plan] exact photo failed for ${representative?.name || 'meal'}:`, error);
            } finally {
                completed += 1;
                if (typeof options.onProgress === 'function') options.onProgress(completed, groups.size);
            }
        }
    };

    try {
        await Promise.all(Array.from({ length: Math.min(2, queue.length) }, () => worker()));
        try { localStorage.setItem('ai_meal_plan', JSON.stringify(plan)); } catch (e) {}
        if (_aiMealPlanCache === plan) renderAiPlanDay(_aiMealPlanCurrentDay);
        return { generated, failed, failureStage };
    } finally {
        _mealPhotoGenerationPlans.delete(planId);
    }
}

async function isCurrentUserVeganChallengeUser(user) {
    if (!user || !window.supabaseClient) return false;
    if (typeof window.isVeganChallengeUser === 'function') {
        return await window.isVeganChallengeUser(window.supabaseClient, user.id);
    }

    try {
        const { data, error } = await window.supabaseClient
            .from('cohort_invitations')
            .select('id')
            .eq('claimed_by_user_id', user.id)
            .eq('cohort_type', 'plant_based_30')
            .limit(1)
            .maybeSingle();
        if (error) {
            console.warn('[meal-plan] vegan-challenge gate lookup error:', error);
            return false;
        }
        return !!(data && data.id);
    } catch (e) {
        console.warn('[meal-plan] vegan-challenge gate lookup threw:', e);
        return false;
    }
}

function waitForMealPlanDependencies(timeoutMs = 10000) {
    if (areMealPlanDependenciesReady()) return Promise.resolve(true);

    return new Promise(resolve => {
        const startedAt = Date.now();
        const timer = setInterval(() => {
            if (areMealPlanDependenciesReady()) {
                clearInterval(timer);
                resolve(true);
            } else if (Date.now() - startedAt >= timeoutMs) {
                clearInterval(timer);
                resolve(false);
            }
        }, 150);
    });
}

/**
 * Load existing AI meal plan from Supabase
 */
async function loadExistingAiMealPlan() {
    if (_aiMealPlanLoadPromise) {
        if (isAiMealPlanViewActive()) {
            showAiPlanGenerating();
            updateAiPlanGeneratingStatus('Loading your meal plan...', '35%');
        }
        return _aiMealPlanLoadPromise;
    }

    _aiMealPlanLoadPromise = loadExistingAiMealPlanInner();
    try {
        return await _aiMealPlanLoadPromise;
    } finally {
        _aiMealPlanLoadPromise = null;
    }
}

async function loadExistingAiMealPlanInner() {
    const user = window.currentUser || await waitForCurrentUser();
    if (!user) return;

    // Check cache first
    if (_aiMealPlanCache) {
        showAiPlanLoaded(_aiMealPlanCache);
        return;
    }

    try {
        // Fetch the latest active AI meal plan for this user
        const { data: plan, error } = await window.supabaseClient
            .from('ai_generated_meal_plans')
            .select('*')
            .eq('user_id', user.id)
            .eq('status', 'active')
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();

        if (error) {
            console.warn('Error loading AI meal plan:', error);
            showAiPlanEmpty();
            return;
        }

        if (!plan) {
            // Also check localStorage for offline/demo plans
            const localPlan = localStorage.getItem('ai_meal_plan');
            if (localPlan) {
                try {
                    _aiMealPlanCache = JSON.parse(localPlan);
                    showAiPlanLoaded(_aiMealPlanCache);
                    return;
                } catch (e) {}
            }

            const isChallenge = await isCurrentUserVeganChallengeUser(user);

            if (isChallenge && isAiMealPlanViewActive()) {
                showAiPlanGenerating();
                updateAiPlanGeneratingStatus('Loading your meal plan...', '35%');
            }

            if (isChallenge && !areMealPlanDependenciesReady()) {
                await waitForMealPlanDependencies();
            }

            if (_aiMealPlanGenerationInProgress) return;

            // Challenge funnel signups should never see the manual
            // "Generate My Meal Plan" CTA — populate on-demand if the
            // cohort-enrollment hook hasn't fired yet (or failed).
            try {
                if (isChallenge && areMealPlanDependenciesReady()) {
                    showAiPlanGenerating();
                    updateAiPlanGeneratingStatus('Plating up your 4-week plan...', '60%');

                    const targets = await window.getUserNutritionTargets(window.supabaseClient, user.id);
                    const result = await window.populateVeganChallengeMealPlan(
                        window.supabaseClient, user.id, targets || {}
                    );
                    updateAiPlanGeneratingStatus(null, '100%');
                    _aiMealPlanCache = result.plan;
                    _aiMealPlanCurrentWeek = 1;
                    _aiMealPlanCurrentDay = 0;
                    try { localStorage.setItem('ai_meal_plan', JSON.stringify(result.plan)); } catch (e) {}
                    showAiPlanLoaded(result.plan);
                    return;
                }
            } catch (autoErr) {
                console.warn('[meal-plan] auto-populate on view load failed:', autoErr);
            }

            showAiPlanEmpty();
            return;
        }

        // Fetch meals and week themes
        const [mealsResult, weeksResult] = await Promise.allSettled([
            window.supabaseClient
                .from('ai_generated_meals')
                .select('*')
                .eq('plan_id', plan.id)
                .order('week_number', { ascending: true })
                .order('day_of_week', { ascending: true })
                .order('meal_slot', { ascending: true }),
            window.supabaseClient
                .from('ai_meal_plan_weeks')
                .select('*')
                .eq('plan_id', plan.id)
                .order('week_number', { ascending: true })
        ]);

        const meals = mealsResult.status === 'fulfilled' ? mealsResult.value.data || [] : [];
        const weekThemes = weeksResult.status === 'fulfilled' ? weeksResult.value.data || [] : [];

        // Reconstruct the plan structure
        const weekNumbers = [...new Set([
            ...weekThemes.map(w => Number(w.week_number)),
            ...meals.map(m => Number(m.week_number))
        ].filter(Boolean))].sort((a, b) => a - b);

        const resolvedPhotoRows = [];
        const fullPlan = {
            id: plan.id,
            plan_name: plan.plan_name,
            plan_description: plan.plan_description,
            generated_at: plan.generated_at || plan.created_at,
            weeks: (weekNumbers.length ? weekNumbers : [1]).map(wn => {
                const weekTheme = weekThemes.find(w => w.week_number === wn) || {};
                const weekMeals = meals.filter(m => m.week_number === wn);
                return {
                    week_number: wn,
                    theme: weekTheme.theme || `Week ${wn}`,
                    theme_description: weekTheme.theme_description || '',
                    days: [0, 1, 2, 3, 4, 5, 6].map(d => {
                        const dayNames = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
                        const dayMeals = weekMeals.filter(m => m.day_of_week === d);
                        return {
                            day_of_week: d,
                            day_name: dayNames[d],
                            meals: dayMeals.map(m => {
                                const imageUrl = resolveMealPlanPhotoUrl(m);
                                if (!String(m.image_url || '').trim() && imageUrl) {
                                    resolvedPhotoRows.push({ id: m.id, image_url: imageUrl });
                                }
                                return {
                                    id: m.id,
                                    meal_slot: m.meal_slot,
                                    meal_time: m.meal_time,
                                    name: m.name,
                                    description: m.description,
                                    calories: m.calories,
                                    protein_g: m.protein_g,
                                    carbs_g: m.carbs_g,
                                    fat_g: m.fat_g,
                                    fiber_g: m.fiber_g,
                                    ingredients: m.ingredients || [],
                                    preparation: m.preparation,
                                    prep_time_mins: m.prep_time_mins,
                                    cook_time_mins: m.cook_time_mins,
                                    tags: m.tags || [],
                                    cuisine: m.cuisine,
                                    image_url: imageUrl
                                };
                            })
                        };
                    })
                };
            })
        };

        _aiMealPlanCache = fullPlan;
        showAiPlanLoaded(fullPlan);
        persistResolvedMealPlanPhotos(resolvedPhotoRows).catch(error => {
            console.warn('[meal-plan] background photo backfill failed:', error);
        });
        ensureExactMealPlanPhotos(fullPlan, user.id).catch(error => {
            console.warn('[meal-plan] exact photo backfill could not start:', error);
        });
    } catch (err) {
        console.error('Error loading AI meal plan:', err);
        showAiPlanEmpty();
    }
}

/**
 * Show the empty state (no plan yet)
 */
function showAiPlanEmpty() {
    const empty = document.getElementById('ai-plan-empty');
    const generating = document.getElementById('ai-plan-generating');
    const loaded = document.getElementById('ai-plan-loaded');
    if (empty) empty.style.display = 'block';
    if (generating) generating.style.display = 'none';
    if (loaded) loaded.style.display = 'none';
}

/**
 * Show the generating state
 */
function showAiPlanGenerating() {
    const empty = document.getElementById('ai-plan-empty');
    const generating = document.getElementById('ai-plan-generating');
    const loaded = document.getElementById('ai-plan-loaded');
    if (empty) empty.style.display = 'none';
    if (generating) generating.style.display = 'block';
    if (loaded) loaded.style.display = 'none';
}

/**
 * Show the loaded plan
 */
function showAiPlanLoaded(plan) {
    const empty = document.getElementById('ai-plan-empty');
    const generating = document.getElementById('ai-plan-generating');
    const loaded = document.getElementById('ai-plan-loaded');
    if (empty) empty.style.display = 'none';
    if (generating) generating.style.display = 'none';
    if (loaded) loaded.style.display = 'block';

    // Set plan header
    const nameEl = document.getElementById('ai-plan-name');
    const descEl = document.getElementById('ai-plan-desc');
    if (nameEl) nameEl.textContent = 'Your meal plan';
    if (descEl) descEl.textContent = plan.plan_name || 'Tailored to your goals';

    // Render week tabs dynamically
    renderAiPlanWeekTabs(plan);

    // Default to the first available week and today's day.
    const firstWeek = plan.weeks?.[0]?.week_number || 1;
    _aiMealPlanCurrentWeek = firstWeek;
    _aiMealPlanCurrentDay = getAiMealPlanTodayIndex();
    _aiMealPlanMealSelection = null;
    renderAiPlanShoppingList();
    document.querySelectorAll('#ai-plan-day-tabs .sub-btn').forEach((button, index) => {
        button.classList.toggle('active', index === _aiMealPlanCurrentDay);
    });

    // Render current week/day
    renderAiPlanWeek(_aiMealPlanCurrentWeek);
    renderAiPlanDay(_aiMealPlanCurrentDay);
    renderAiPlanGuidance(plan);
    setTimeout(() => maybeBuildWeeklyPlanAtWeekEnd(plan), 800);
}

function renderAiPlanGuidance(plan) {
    const card = document.getElementById('ai-plan-weekly-guidance');
    if (!card) return;
    const firstWeek = plan?.weeks?.[0];
    const guidance = firstWeek?.theme_description || '';
    const isEvolvingPlan = plan?.plan_name === 'Your Evolving Weekly Plan';
    card.textContent = isEvolvingPlan ? guidance : '';
    card.style.display = isEvolvingPlan && guidance ? 'block' : 'none';
}

/**
 * Render week tabs dynamically based on how many weeks exist in the plan.
 * Also shows a "+ Generate Next Week" button if fewer than 4 weeks exist.
 */
function renderAiPlanWeekTabs(plan) {
    const container = document.getElementById('ai-plan-week-tabs');
    if (!container) return;

    const weekCount = plan.weeks?.length || 0;
    let html = '';

    for (let i = 0; i < weekCount; i++) {
        const w = plan.weeks[i];
        const isActive = w.week_number === _aiMealPlanCurrentWeek;
        html += `<button class="pill-btn ${isActive ? 'active' : ''}" onclick="switchAiPlanWeek(${w.week_number}, this)">Week ${w.week_number}</button>`;
    }

    // Show "+ Next Week" button if under 4 weeks
    if (weekCount < 4) {
        html += `<button class="pill-btn" onclick="generateNextWeek()" style="background: linear-gradient(135deg, var(--primary), #10b981); color: white; border: none; font-size: 0.8rem;">+ Next Week</button>`;
    }

    container.innerHTML = html;
}

/**
 * Switch AI plan week tab
 */
function switchAiPlanWeek(weekNum, btn) {
    _aiMealPlanCurrentWeek = weekNum;
    _aiMealPlanCurrentDay = getAiMealPlanTodayIndex();
    _aiMealPlanMealSelection = null;
    _aiMealPlanLoggedDayKey = '';

    // Update week pills
    if (btn) {
        document.querySelectorAll('#ai-plan-week-tabs .pill-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    // Update day pills - return to today.
    document.querySelectorAll('#ai-plan-day-tabs .sub-btn').forEach((b, i) => {
        b.classList.toggle('active', i === _aiMealPlanCurrentDay);
    });

    renderAiPlanWeek(weekNum);
    renderAiPlanDay(_aiMealPlanCurrentDay);
    renderAiPlanShoppingList();
}

/**
 * Switch AI plan day tab
 */
function switchAiPlanDay(dayNum, btn) {
    _aiMealPlanCurrentDay = dayNum;
    _aiMealPlanMealSelection = null;
    _aiMealPlanLoggedDayKey = '';

    if (btn) {
        document.querySelectorAll('#ai-plan-day-tabs .sub-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
    }

    renderAiPlanDay(dayNum);
}

/**
 * Render the week theme (week theme card removed from UI)
 */
function renderAiPlanWeek(weekNum) {
    // Week theme card removed - function kept as stub for callers
}

function selectAiPlanMeal(index) {
    _aiMealPlanMealSelection = Number(index);
    renderAiPlanDay(_aiMealPlanCurrentDay);
    const hero = document.querySelector('#ai-plan-meals-list .ai-plan-hero');
    if (hero) hero.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function selectAiPlanMealRelative(direction) {
    const week = _aiMealPlanCache?.weeks?.find(item => item.week_number === _aiMealPlanCurrentWeek);
    const day = week?.days?.find(item => item.day_of_week === _aiMealPlanCurrentDay);
    const mealCount = day?.meals?.length || 0;
    if (!mealCount) return;
    const heroIndex = Number(document.querySelector('#ai-plan-meals-list .ai-plan-hero')?.dataset.mealIndex);
    const currentIndex = Number.isInteger(heroIndex) ? heroIndex : 0;
    const nextIndex = (currentIndex + Number(direction || 0) + mealCount) % mealCount;
    selectAiPlanMeal(nextIndex);
}

function selectAiPlanFirstDay() {
    const firstDay = _aiMealPlanCache?.weeks
        ?.find(item => item.week_number === _aiMealPlanCurrentWeek)
        ?.days?.filter(day => day?.meals?.length)
        ?.sort((a, b) => a.day_of_week - b.day_of_week)?.[0];
    if (!firstDay) return false;
    const dayButtons = [...document.querySelectorAll('#ai-plan-day-tabs .sub-btn')];
    switchAiPlanDay(firstDay.day_of_week, dayButtons[firstDay.day_of_week] || null);
    return true;
}

window.selectAiPlanFirstDay = selectAiPlanFirstDay;

function toggleAiPlanMealDetails(button) {
    const hero = button?.closest('.ai-plan-hero');
    if (!hero) return;
    const isOpen = hero.classList.toggle('is-open');
    button.textContent = isOpen ? 'Hide recipe' : 'View recipe';
}

function openAiPlanMealLogger() {
    const trackerButton = document.querySelector('#meals-nav-pills .pill-btn[onclick*="calorie-tracker"]');
    if (typeof switchWeek === 'function') switchWeek('calorie-tracker', trackerButton);
}

function renderAiPlanFocusedDay(dayNum) {
    if (!_aiMealPlanCache || !_aiMealPlanCache.weeks) return;
    const week = _aiMealPlanCache.weeks.find(item => item.week_number === _aiMealPlanCurrentWeek);
    const day = week?.days?.find(item => item.day_of_week === dayNum);
    const container = document.getElementById('ai-plan-meals-list');
    if (!day?.meals || !container) return;

    loadAiMealPlanLoggedTypes(dayNum);

    const helper = window.BalanceMealPlanNext;
    const sortedMeals = helper?.sortMeals
        ? helper.sortMeals(day.meals).map(entry => entry.meal)
        : [...day.meals];
    const isToday = dayNum === getAiMealPlanTodayIndex();
    const loggedTypes = isToday ? _aiMealPlanLoggedTypes : [];
    const completion = helper?.completionState
        ? helper.completionState(sortedMeals, loggedTypes)
        : sortedMeals.map((meal, originalIndex) => ({ meal, originalIndex, complete: false }));
    const allComplete = completion.length > 0 && completion.every(entry => entry.complete);
    const firstIncompleteIndex = completion.findIndex(entry => !entry.complete);
    const nextIndex = allComplete ? Math.max(sortedMeals.length - 1, 0) : Math.max(firstIncompleteIndex, 0);
    const requestedIndex = Number.isInteger(_aiMealPlanMealSelection) ? _aiMealPlanMealSelection : nextIndex;
    const selectedIndex = Math.min(Math.max(requestedIndex, 0), Math.max(sortedMeals.length - 1, 0));
    const selected = sortedMeals[selectedIndex];
    if (!selected) return;

    let totalCal = 0, totalProtein = 0, totalCarbs = 0, totalFat = 0;
    sortedMeals.forEach(meal => {
        totalCal += Number(meal.calories) || 0;
        totalProtein += Number(meal.protein_g) || 0;
        totalCarbs += Number(meal.carbs_g) || 0;
        totalFat += Number(meal.fat_g) || 0;
    });
    const calEl = document.getElementById('ai-day-cal');
    const proteinEl = document.getElementById('ai-day-protein');
    const carbsEl = document.getElementById('ai-day-carbs');
    const fatEl = document.getElementById('ai-day-fat');
    if (calEl) calEl.textContent = `${Math.round(totalCal)} cal`;
    if (proteinEl) proteinEl.textContent = `${Math.round(totalProtein)}g protein`;
    if (carbsEl) carbsEl.textContent = `${Math.round(totalCarbs)}g carbs`;
    if (fatEl) fatEl.textContent = `${Math.round(totalFat)}g fat`;

    const slotLabels = { breakfast: 'Breakfast', am_snack: 'AM Snack', lunch: 'Lunch', pm_snack: 'PM Snack', dinner: 'Dinner' };
    const selectedSlot = slotLabels[selected.meal_slot] || selected.meal_slot || 'Meal';
    const rawImageUrl = resolveMealPlanPhotoUrl(selected);
    const imageUrl = /^(?:https:\/\/|images\/meals\/)[^"'<>]+$/i.test(rawImageUrl) ? rawImageUrl : '';
    const imageAlt = escapeAiPlanText(selected.name || selectedSlot);
    const ingredients = (selected.ingredients || []).map(ingredient => {
        if (typeof ingredient === 'string') return `<li>${escapeAiPlanText(ingredient)}</li>`;
        const amount = ingredient?.amount ? ` ${escapeAiPlanText(ingredient.amount)}` : '';
        return `<li>${escapeAiPlanText(ingredient?.name || '')}${amount}</li>`;
    }).join('');
    const tags = (selected.tags || []).slice(0, 3).map(tag => escapeAiPlanText(tag)).join(' · ')
        || escapeAiPlanText(selected.description || 'Planned for you');
    const focusLabel = allComplete && isToday
        ? 'Today complete'
        : selectedIndex === nextIndex && isToday
            ? 'Up next'
            : 'Selected meal';
    const completeCount = completion.filter(entry => entry.complete).length;
    const previews = sortedMeals.map((meal, index) => ({ meal, index, complete: !!completion[index]?.complete }))
        .filter(entry => entry.index !== selectedIndex);

    container.innerHTML = `
        <div class="ai-plan-focus-label">
            <strong>${focusLabel}</strong>
            <span>${escapeAiPlanText(selectedSlot)}${selected.meal_time ? ` · ${escapeAiPlanText(selected.meal_time)}` : ''}</span>
        </div>
        <article class="ai-plan-hero" data-next-meal="${selectedIndex === nextIndex ? 'true' : 'false'}" data-meal-index="${selectedIndex}" data-meal-carousel="true">
            <div class="ai-plan-hero__photo-stage">
                ${imageUrl ? `<img class="ai-plan-hero__photo" src="${imageUrl}" alt="${imageAlt}" loading="eager" data-meal-plan-photo="true" onerror="this.style.display='none'">` : ''}
                ${sortedMeals.length > 1 ? `
                    <button type="button" class="ai-plan-hero__carousel-button ai-plan-hero__carousel-button--previous" onclick="selectAiPlanMealRelative(-1)" aria-label="Previous meal">&#8249;</button>
                    <button type="button" class="ai-plan-hero__carousel-button ai-plan-hero__carousel-button--next" onclick="selectAiPlanMealRelative(1)" aria-label="Next meal">&#8250;</button>
                    <span class="ai-plan-hero__carousel-count">${selectedIndex + 1} of ${sortedMeals.length}</span>
                ` : ''}
            </div>
            <div class="ai-plan-hero__content">
                <div class="ai-plan-hero__meta"><span>${escapeAiPlanText(selectedSlot)}</span><span>${escapeAiPlanText(selected.meal_time || '')}</span></div>
                <h3 class="ai-plan-hero__title">${escapeAiPlanText(selected.name)}</h3>
                <div class="ai-plan-hero__tags">${tags}</div>
                <div class="ai-plan-hero__macros">
                    <span>${Math.round(selected.calories || 0)} cal</span>
                    <span>${Math.round(selected.protein_g || 0)}g protein</span>
                    <span>${Math.round(selected.carbs_g || 0)}g carbs</span>
                    <span>${Math.round(selected.fat_g || 0)}g fat</span>
                </div>
                <div class="ai-plan-hero__actions">
                    <button type="button" class="ai-plan-hero__button ai-plan-hero__button--primary" onclick="toggleAiPlanMealDetails(this)">View recipe</button>
                    <button type="button" class="ai-plan-hero__button" onclick="openAiPlanMealLogger()">Log meal</button>
                </div>
                <div class="ai-plan-hero__details">
                    ${selected.description ? `<p>${escapeAiPlanText(selected.description)}</p>` : ''}
                    ${ingredients ? `<h4>Ingredients</h4><ul>${ingredients}</ul>` : ''}
                    ${selected.preparation ? `<h4>Preparation</h4>${formatAiPlanPreparation(selected.preparation)}` : ''}
                </div>
            </div>
        </article>
        ${previews.length ? `
            <div class="ai-plan-preview-heading"><strong>${escapeAiPlanText(day.day_name || 'Day')} meals</strong><span>${isToday ? `${completeCount} of ${sortedMeals.length} logged` : 'Tap to preview'}</span></div>
            <div class="ai-plan-preview-row">
                ${previews.map(entry => {
                    const previewMeal = entry.meal;
                    const previewSlot = slotLabels[previewMeal.meal_slot] || previewMeal.meal_slot || 'Meal';
                    const previewRawUrl = resolveMealPlanPhotoUrl(previewMeal);
                    const previewUrl = /^(?:https:\/\/|images\/meals\/)[^"'<>]+$/i.test(previewRawUrl) ? previewRawUrl : '';
                    return `<button type="button" class="ai-plan-preview${entry.complete ? ' is-complete' : ''}" onclick="selectAiPlanMeal(${entry.index})">
                        ${previewUrl ? `<img src="${previewUrl}" alt="${escapeAiPlanText(previewMeal.name || previewSlot)}" loading="lazy" data-meal-plan-photo="true" onerror="this.style.display='none'">` : ''}
                        <span class="ai-plan-preview__copy"><small>${escapeAiPlanText(previewSlot)}</small><strong>${escapeAiPlanText(previewMeal.name)}</strong></span>
                    </button>`;
                }).join('')}
            </div>` : ''}
    `;
}

/**
 * Render the meals for a specific day
 */
function renderAiPlanDay(dayNum) {
    return renderAiPlanFocusedDay(dayNum);
    if (!_aiMealPlanCache || !_aiMealPlanCache.weeks) return;

    const week = _aiMealPlanCache.weeks.find(w => w.week_number === _aiMealPlanCurrentWeek);
    if (!week || !week.days) return;

    const day = week.days.find(d => d.day_of_week === dayNum);
    if (!day || !day.meals) return;

    // Calculate daily totals
    let totalCal = 0, totalProtein = 0, totalCarbs = 0, totalFat = 0;
    day.meals.forEach(m => {
        totalCal += m.calories || 0;
        totalProtein += parseFloat(m.protein_g) || 0;
        totalCarbs += parseFloat(m.carbs_g) || 0;
        totalFat += parseFloat(m.fat_g) || 0;
    });

    // Update nutrition summary pills
    const calEl = document.getElementById('ai-day-cal');
    const proteinEl = document.getElementById('ai-day-protein');
    const carbsEl = document.getElementById('ai-day-carbs');
    const fatEl = document.getElementById('ai-day-fat');
    if (calEl) calEl.textContent = `${Math.round(totalCal)} cal`;
    if (proteinEl) proteinEl.textContent = `${Math.round(totalProtein)}g protein`;
    if (carbsEl) carbsEl.textContent = `${Math.round(totalCarbs)}g carbs`;
    if (fatEl) fatEl.textContent = `${Math.round(totalFat)}g fat`;

    // Render meal cards
    const mealSlotOrder = ['breakfast', 'am_snack', 'lunch', 'pm_snack', 'dinner'];
    const mealSlotLabels = {
        breakfast: 'Breakfast',
        am_snack: 'AM Snack',
        lunch: 'Lunch',
        pm_snack: 'PM Snack',
        dinner: 'Dinner'
    };
    const mealSlotIcons = {
        breakfast: '🌅',
        am_snack: '🍎',
        lunch: '🥗',
        pm_snack: '🥜',
        dinner: '🍽️'
    };

    const sortedMeals = [...day.meals].sort((a, b) =>
        mealSlotOrder.indexOf(a.meal_slot) - mealSlotOrder.indexOf(b.meal_slot)
    );

    const container = document.getElementById('ai-plan-meals-list');
    if (!container) return;

    container.innerHTML = sortedMeals.map((meal, idx) => {
        const slotLabel = mealSlotLabels[meal.meal_slot] || meal.meal_slot;
        const slotIcon = mealSlotIcons[meal.meal_slot] || '🍽️';
        const time = meal.meal_time || '';
        const rawImageUrl = resolveMealPlanPhotoUrl(meal);
        const imageUrl = /^(?:https:\/\/|images\/meals\/)[^"'<>]+$/i.test(rawImageUrl) ? rawImageUrl : '';
        const imageAlt = String(meal.name || slotLabel).replace(/[&<>"']/g, character => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
        })[character]);

        // Build ingredients list
        const ingredientsList = (meal.ingredients || []).map(ing => {
            if (typeof ing === 'string') return `<li>${ing}</li>`;
            return `<li>${ing.name}${ing.amount ? ' ' + ing.amount : ''}</li>`;
        }).join('');

        // Build tags
        const tagsHtml = (meal.tags || []).map(tag =>
            `<span style="display: inline-block; background: rgba(123,168,131,0.12); color: var(--primary); padding: 2px 8px; border-radius: 10px; font-size: 0.7rem; font-weight: 500;">${tag}</span>`
        ).join(' ');

        return `
        <div class="card" style="margin-bottom: 10px;">
            ${imageUrl ? `<img src="${imageUrl}" alt="${imageAlt}" loading="lazy" data-meal-plan-photo="true" style="display:block;width:100%;height:172px;object-fit:cover;background:#f5efe4;border-radius:12px 12px 0 0;" onerror="this.style.display='none'">` : ''}
            <div class="card-header" onclick="toggleCard(this)">
                <div style="display: flex; align-items: center;">
                    <div class="meal-icon">${slotIcon}</div>
                    <div>
                        <div class="meta">${slotLabel}${time ? '  ' + time : ''}</div>
                        <div class="meal-title">${meal.name}</div>
                    </div>
                </div>
                <div style="display: flex; align-items: center; gap: 10px;">
                    <div style="text-align: right;">
                        <div style="font-size: 0.85rem; font-weight: 700; color: var(--text-main);">${meal.calories || '?'} cal</div>
                        <div style="font-size: 0.7rem; color: var(--text-muted);">P: ${Math.round(meal.protein_g || 0)}g</div>
                    </div>
                    <div class="expand-icon">+</div>
                </div>
            </div>
            <div class="card-body">
                ${meal.description ? `<p style="color: var(--text-muted); font-size: 0.9rem; margin-bottom: 15px; font-style: italic;">${meal.description}</p>` : ''}
                ${tagsHtml ? `<div style="display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 15px;">${tagsHtml}</div>` : ''}
                <div style="display: flex; gap: 12px; margin-bottom: 15px; flex-wrap: wrap;">
                    <div style="background: #f1f5f9; padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; text-align: center; min-width: 60px;">
                        <div style="font-weight: 700; color: var(--text-main);">${meal.calories || '?'}</div>
                        <div style="color: var(--text-muted); font-size: 0.7rem;">cal</div>
                    </div>
                    <div style="background: rgba(59,130,246,0.08); padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; text-align: center; min-width: 60px;">
                        <div style="font-weight: 700; color: #3b82f6;">${Math.round(meal.protein_g || 0)}g</div>
                        <div style="color: var(--text-muted); font-size: 0.7rem;">protein</div>
                    </div>
                    <div style="background: rgba(245,158,11,0.08); padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; text-align: center; min-width: 60px;">
                        <div style="font-weight: 700; color: #f59e0b;">${Math.round(meal.carbs_g || 0)}g</div>
                        <div style="color: var(--text-muted); font-size: 0.7rem;">carbs</div>
                    </div>
                    <div style="background: rgba(239,68,68,0.08); padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; text-align: center; min-width: 60px;">
                        <div style="font-weight: 700; color: #ef4444;">${Math.round(meal.fat_g || 0)}g</div>
                        <div style="color: var(--text-muted); font-size: 0.7rem;">fat</div>
                    </div>
                    ${meal.fiber_g ? `<div style="background: rgba(34,197,94,0.08); padding: 8px 12px; border-radius: 8px; font-size: 0.8rem; text-align: center; min-width: 60px;">
                        <div style="font-weight: 700; color: #22c55e;">${Math.round(meal.fiber_g)}g</div>
                        <div style="color: var(--text-muted); font-size: 0.7rem;">fiber</div>
                    </div>` : ''}
                </div>
                ${ingredientsList ? `<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;"><h4 style="margin: 0; border: none; padding: 0;">Ingredients</h4></div><ul>${ingredientsList}</ul>` : ''}
                ${meal.preparation ? `<h4>Preparation</h4><p>${meal.preparation}</p>` : ''}
                ${meal.prep_time_mins || meal.cook_time_mins ? `<div style="display: flex; gap: 15px; margin-top: 10px; padding-top: 10px; border-top: 1px solid #f1f5f9; color: var(--text-muted); font-size: 0.8rem;">
                    ${meal.prep_time_mins ? `<span>Prep: ${meal.prep_time_mins} min</span>` : ''}
                    ${meal.cook_time_mins ? `<span>Cook: ${meal.cook_time_mins} min</span>` : ''}
                </div>` : ''}
            </div>
        </div>`;
    }).join('');
}

/**
 * Fetch a single day from the meal-plan edge function with a per-attempt timeout
 * and one automatic retry. Without this, a single hung Gemini call would freeze
 * the entire generation loop on "Tailoring Day 1 — Monday...".
 */
async function fetchMealPlanDay(payload, { timeoutMs = 35000, maxAttempts = 3 } = {}) {
    let lastErr;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), timeoutMs);
        try {
            const response = await fetch('/.netlify/functions/generate-meal-plan', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload),
                signal: controller.signal
            });
            if (!response.ok) {
                const errText = await response.text().catch(() => '');
                throw new Error(`HTTP ${response.status}: ${errText.slice(0, 200)}`);
            }
            const dayResult = await response.json();
            if (!dayResult.success || !dayResult.day) {
                throw new Error(dayResult.error || 'Invalid response from meal plan service');
            }
            return dayResult;
        } catch (err) {
            lastErr = err;
            const isTimeout = err?.name === 'AbortError';
            console.warn(`Meal plan day fetch attempt ${attempt}/${maxAttempts} failed${isTimeout ? ' (timeout)' : ''}:`, err);
            if (attempt === maxAttempts) break;
            // Small backoff gives the upstream (Gemini) a chance to recover from rate-limit / 503.
            await new Promise(r => setTimeout(r, 800 * attempt));
        } finally {
            clearTimeout(timer);
        }
    }
    throw lastErr || new Error('Meal plan day fetch failed');
}

/**
 * Fire-and-forget push when a meal plan week finishes generating. Skipped
 * while the app is foregrounded so the user isn't pinged for something they
 * can already see on screen.
 */
function notifyMealPlanReady(userId, weekNumber) {
    try {
        if (!userId) return;
        if (typeof document !== 'undefined' && document.visibilityState === 'visible') return;
        fetch('/.netlify/functions/send-meal-plan-ready', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ userId, weekNumber })
        }).catch(err => console.warn('Meal plan push notify failed:', err));
    } catch (e) {
        console.warn('notifyMealPlanReady error:', e);
    }
}

/**
 * Request AI meal plan generation (called from the CTA button)
 */
async function requestAiMealPlan() {
    _aiMealPlanGenerationInProgress = true;
    showAiPlanGenerating();

    try {
        // Navigate to the meal plan store tab if not already there
        const storeSection = document.getElementById('meal-plan-store');
        if (storeSection && !storeSection.classList.contains('active')) {
            switchWeek('meal-plan-store', document.getElementById('browse-plans-pill'));
        }

        await generateAiMealPlan();
    } finally {
        _aiMealPlanGenerationInProgress = false;
    }
}

/**
 * Regenerate the meal plan
 */
async function regenerateAiMealPlan() {
    if (!confirm('Generate a new meal plan? This will replace your current one.')) return;

    _aiMealPlanCache = null;

    // Archive existing plan in Supabase
    const user = window.currentUser;
    if (user) {
        try {
            await window.supabaseClient
                .from('ai_generated_meal_plans')
                .update({ status: 'archived' })
                .eq('user_id', user.id)
                .eq('status', 'active');
        } catch (e) {
            console.warn('Could not archive old plan:', e);
        }
    }

    showAiPlanGenerating();
    await generateAiMealPlan();
}

/**
 * Core meal plan generation — populates a curated 4-week plant-based plan
 * scaled to the user's calorie/macro targets. Photos and recipes come from
 * data/vegan-challenge-meal-plan.js; the populator lives in
 * lib/meal-plan-populator.js.
 */
async function generateAiMealPlan() {
    const statusEl = document.getElementById('ai-plan-gen-status');
    const progressEl = document.getElementById('ai-plan-gen-progress');
    const user = window.currentUser || await waitForCurrentUser();
    if (!user) {
        alert('Please log in to generate a meal plan.');
        showAiPlanEmpty();
        return;
    }

    const wasMealPlanGenerationInProgress = _aiMealPlanGenerationInProgress;
    _aiMealPlanGenerationInProgress = true;

    if (!areMealPlanDependenciesReady()) {
        updateAiPlanGeneratingStatus('Loading the meal plan engine...', '20%');
        await waitForMealPlanDependencies();
    }

    if (!areMealPlanDependenciesReady()) {
        console.error('Meal plan populator not loaded');
        if (!wasMealPlanGenerationInProgress) _aiMealPlanGenerationInProgress = false;
        if (statusEl) statusEl.textContent = 'Meal plan engine not loaded — please refresh the app.';
        return;
    }

    try {
        if (statusEl) statusEl.textContent = 'Pulling your nutrition targets...';
        if (progressEl) progressEl.style.width = '15%';

        const [targets, foodPreferences] = await Promise.all([
            window.getUserNutritionTargets(window.supabaseClient, user.id),
            loadWeeklyEvolutionPreferences(user.id)
        ]);

        if (mealPlanNeedsPreferenceReview(foodPreferences)) {
            window._onboardingMealPlanReviewRequired = true;
            if (statusEl) statusEl.textContent = 'Your food preferences need a quick check before we build this plan.';
            if (progressEl) progressEl.style.width = '0%';
            console.warn('[meal-plan] held for preference review instead of generating an unsafe template');
            if (!wasMealPlanGenerationInProgress) _aiMealPlanGenerationInProgress = false;
            return;
        }

        if (statusEl) statusEl.textContent = 'Plating up your 4-week plan...';
        if (progressEl) progressEl.style.width = '45%';

        // Archive any existing active plans first so the new one is the active one.
        try {
            await window.supabaseClient
                .from('ai_generated_meal_plans')
                .update({ status: 'archived' })
                .eq('user_id', user.id)
                .eq('status', 'active');
        } catch (e) {
            console.warn('Could not archive old plans:', e);
        }

        const result = await window.populatePreparedMealPlan(
            window.supabaseClient,
            user.id,
            targets,
            foodPreferences
        );

        if (progressEl) progressEl.style.width = '95%';
        if (statusEl) statusEl.textContent = 'Your 4-week meal plan is ready! 🎉';

        const mealPlan = result.plan;
        _aiMealPlanCache = mealPlan;
        _aiMealPlanCurrentWeek = 1;
        _aiMealPlanCurrentDay = 0;

        try { localStorage.setItem('ai_meal_plan', JSON.stringify(mealPlan)); } catch (e) {}

        if (progressEl) progressEl.style.width = '100%';
        setTimeout(() => showAiPlanLoaded(mealPlan), 400);

        try { notifyMealPlanReady(user.id, 1); } catch (e) {}
    } catch (err) {
        console.error('Meal plan generation error:', err);
        if (statusEl) statusEl.textContent = 'Something went wrong building your plan. Please try again.';
        if (progressEl) progressEl.style.width = '0%';
        setTimeout(() => showAiPlanEmpty(), 3000);
    }

    if (!wasMealPlanGenerationInProgress) _aiMealPlanGenerationInProgress = false;
}

function mealPlanNeedsPreferenceReview(preferences = {}) {
    const safeVeganRequirements = new Set([
        'vegan', 'plant_based', 'vegetarian', 'omnivore', 'gluten_free',
        'dairy_free', 'nut_free', 'soy_free', 'low_fodmap', 'egg_free',
        'shellfish_free', 'halal', 'kosher'
    ]);
    const requirements = Array.isArray(preferences.dietary_requirements)
        ? preferences.dietary_requirements.map(value => String(value || '').trim().toLowerCase()).filter(Boolean)
        : [];
    const allergies = Array.isArray(preferences.allergies)
        ? preferences.allergies.map(value => String(value || '').trim().toLowerCase()).filter(Boolean)
        : [];
    const dislikes = Array.isArray(preferences.dislikes)
        ? preferences.dislikes.map(value => String(value || '').trim()).filter(Boolean)
        : [];
    const veganSafeAllergies = new Set([
        'gluten', 'dairy', 'nuts', 'nut', 'soy', 'fodmap',
        'egg', 'eggs', 'shellfish', 'fish', 'meat'
    ]);

    return requirements.some(value => !safeVeganRequirements.has(value))
        || allergies.some(value => !veganSafeAllergies.has(value))
        || dislikes.length > 0;
}

function readMetaPreviewMealInputs() {
    let profile = {};
    let foodPreferences = {};
    try {
        profile = Object.assign(
            {},
            JSON.parse(localStorage.getItem('userProfile') || '{}'),
            JSON.parse(sessionStorage.getItem('userProfile') || '{}')
        );
    } catch (e) {}
    try { foodPreferences = JSON.parse(localStorage.getItem('user_food_preferences') || '{}') || {}; } catch (e) {}
    if (!Array.isArray(foodPreferences.dietary_requirements) || !foodPreferences.dietary_requirements.length) {
        const requirements = Array.isArray(profile.dietary_requirements) ? profile.dietary_requirements : [];
        foodPreferences.dietary_requirements = requirements.length ? requirements : [profile.dietary_preference || 'omnivore'];
    }
    foodPreferences.diet_type = foodPreferences.diet_type || profile.dietary_preference || 'omnivore';
    return { profile, foodPreferences };
}

function metaPreviewMealPlanSignature(profile, foodPreferences) {
    const list = value => Array.isArray(value) ? value.map(item => String(item || '').trim().toLowerCase()).filter(Boolean).sort() : [];
    return JSON.stringify({
        calorie_goal: Math.round(Number(profile.calorie_goal || profile.calorieGoal || profile.daily_calorie_target || 2000)),
        protein_goal_g: Math.round(Number(profile.protein_goal_g || profile.proteinGoal || 0)),
        carbs_goal_g: Math.round(Number(profile.carbs_goal_g || profile.carbsGoal || 0)),
        fat_goal_g: Math.round(Number(profile.fat_goal_g || profile.fatGoal || 0)),
        diet_type: String(foodPreferences.diet_type || 'omnivore').toLowerCase(),
        dietary_requirements: list(foodPreferences.dietary_requirements),
        allergies: list(foodPreferences.allergies),
        cuisines: list(foodPreferences.cuisine_preferences),
        favorites: list(foodPreferences.favorites),
        dislikes: list(foodPreferences.dislikes),
        prep_time: String(foodPreferences.prep_time_preference || 'moderate').toLowerCase()
    });
}

function setMetaPreviewMealPlanBuildStatus(message, progress, status = 'building') {
    _metaPreviewMealPlanBuildState = { message: String(message || ''), progress: Math.max(0, Math.min(100, Number(progress) || 0)), status };
    const card = document.getElementById('wizard-meal-plan-build-card');
    const title = document.getElementById('wizard-meal-plan-build-title');
    const detail = document.getElementById('wizard-meal-plan-build-detail');
    const bar = document.getElementById('wizard-meal-plan-build-progress');
    if (card) card.dataset.state = status;
    if (title) title.textContent = status === 'ready' ? 'Your meal plan is ready' : status === 'error' ? 'Meal plan needs another try' : 'Building your meal plan';
    if (detail) detail.textContent = _metaPreviewMealPlanBuildState.message || 'Using the food choices you just made.';
    if (bar) bar.style.width = `${_metaPreviewMealPlanBuildState.progress}%`;
    setWizardPersonalisingStage('meal', _metaPreviewMealPlanBuildState.message, Math.max(30, Math.min(86, _metaPreviewMealPlanBuildState.progress)), status);
}
window.setMetaPreviewMealPlanBuildStatus = setMetaPreviewMealPlanBuildStatus;

function setWizardPersonalisingStage(stage, detail, progress, status = 'building') {
    const screen = document.getElementById('wizard-personalising-screen');
    if (!screen || screen.hidden) return;
    const order = ['workout', 'meal', 'app'];
    const activeIndex = Math.max(0, order.indexOf(stage));
    screen.classList.toggle('is-error', status === 'error');
    screen.querySelectorAll('[data-personalising-stage]').forEach(element => {
        const index = order.indexOf(element.dataset.personalisingStage);
        element.classList.toggle('is-complete', status === 'ready' || index < activeIndex);
        element.classList.toggle('is-active', status !== 'ready' && index === activeIndex);
        const marker = element.querySelector('span');
        if (marker) marker.textContent = (status === 'ready' || index < activeIndex) ? '✓' : (status === 'error' && index === activeIndex ? '!' : '');
    });
    const detailElement = document.getElementById('wizard-personalising-detail');
    const progressElement = document.getElementById('wizard-personalising-progress');
    if (detailElement) detailElement.textContent = detail || 'Preparing your first week.';
    if (progressElement) progressElement.style.width = `${Math.max(8, Math.min(100, Number(progress) || 0))}%`;
}

function showWizardPersonalisingScreen() {
    const screen = document.getElementById('wizard-personalising-screen');
    const retry = document.getElementById('wizard-personalising-retry');
    if (!screen) return;
    screen.hidden = false;
    screen.classList.remove('is-error');
    if (retry) retry.hidden = true;
    setWizardPersonalisingStage('meal', 'Tailoring meals around the choices you just made.', 38);
}

function showWizardPersonalisingError(message) {
    const retry = document.getElementById('wizard-personalising-retry');
    setWizardPersonalisingStage('meal', message || 'Your meal plan needs another try.', 38, 'error');
    if (retry) retry.hidden = false;
}

function onboardingPromiseWithTimeout(promise, timeoutMs) {
    return Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error('Setup took too long. Please try again.')), timeoutMs))
    ]);
}

async function retryWizardPersonalisation() {
    const retry = document.getElementById('wizard-personalising-retry');
    if (retry) retry.hidden = true;
    const finishButton = document.getElementById('wizard-next');
    if (finishButton) delete finishButton.dataset.mealPlanFinishing;
    setWizardPersonalisingStage('meal', 'Trying your personalised meal plan again.', 38);
    await finishOnboarding();
}
window.retryWizardPersonalisation = retryWizardPersonalisation;

async function switchPaidPreviewAccount() {
    const keys = [
        'onboardingComplete', 'plantbased_onboarding_complete', 'featureTourComplete',
        'userProfile', 'user_food_preferences', 'ai_meal_plan',
        'pbb_meta_preview_meal_signature', 'pbb_onboarding_owner_user_id'
    ];
    keys.forEach(key => { try { localStorage.removeItem(key); } catch (_) {} });
    try { sessionStorage.clear(); } catch (_) {}
    try {
        const signOut = window.authHelpers?.signOut
            ? window.authHelpers.signOut()
            : window.supabaseClient?.auth?.signOut?.();
        if (signOut) await onboardingPromiseWithTimeout(Promise.resolve(signOut), 6000);
    } catch (error) {
        console.warn('[onboarding] Account switch sign-out will continue at login:', error);
    }
    const params = new URLSearchParams({
        action: 'signup', switch_account: '1', fresh_preview: '1', account_first: '1',
        meta_trial: 'facebook_5m_foundations_v3', utm_source: 'facebook',
        utm_medium: 'paid_social', utm_campaign: 'onboarding_test'
    });
    window.location.replace('/login.html?' + params.toString());
}
window.switchPaidPreviewAccount = switchPaidPreviewAccount;

async function completeRemainingMetaPreviewDaysInBackground({ user, plan, planId, profileForGenerator, foodPreferences, firstDayNumber, dayNames }) {
    const remainingDayNumbers = [0,1,2,3,4,5,6].filter(dayNumber => dayNumber !== firstDayNumber);
    const addedDays = [];
    for (let batchStart = 0; batchStart < remainingDayNumbers.length; batchStart += 3) {
        const batch = remainingDayNumbers.slice(batchStart, batchStart + 3);
        const previousDays = plan.weeks[0].days.concat(addedDays).map(day => ({
            day_name: day.day_name,
            mealNames: (day.meals || []).map(meal => meal.name)
        }));
        const results = await Promise.all(batch.map(async dayNumber => {
            const result = await fetchMealPlanDay({
                userData: { profile: profileForGenerator, quizResults: profileForGenerator, facts: {}, foodPreferences },
                weekNumber: 1,
                dayNumber,
                previousDays,
                previousWeeks: []
            }, { timeoutMs: 30000, maxAttempts: 2 });
            return { ...result.day, day_of_week: dayNumber, day_name: result.day.day_name || dayNames[dayNumber] };
        }));
        addedDays.push(...results);
    }

    const mealRows = [];
    addedDays.forEach(day => (day.meals || []).forEach(meal => mealRows.push({
        plan_id: planId, week_number: 1, day_of_week: day.day_of_week, day_name: day.day_name,
        meal_slot: meal.meal_slot, meal_time: meal.meal_time, name: meal.name,
        description: meal.description, calories: meal.calories, protein_g: meal.protein_g,
        carbs_g: meal.carbs_g, fat_g: meal.fat_g, fiber_g: meal.fiber_g,
        ingredients: meal.ingredients || [], preparation: meal.preparation,
        prep_time_mins: meal.prep_time_mins, cook_time_mins: meal.cook_time_mins,
        tags: meal.tags || [], cuisine: meal.cuisine, image_url: ''
    })));
    if (!mealRows.length) return;
    const insert = await window.supabaseClient.from('ai_generated_meals').insert(mealRows).select('id,week_number,day_of_week,meal_slot');
    if (insert.error) throw insert.error;
    const ids = new Map((insert.data || []).map(row => [`${row.day_of_week}:${row.meal_slot}`, row.id]));
    addedDays.forEach(day => (day.meals || []).forEach(meal => {
        meal.id = ids.get(`${day.day_of_week}:${meal.meal_slot}`) || meal.id;
        meal.image_url = '';
    }));
    plan.weeks[0].days.push(...addedDays);
    plan.weeks[0].days.sort((a, b) => a.day_of_week - b.day_of_week);
    await window.supabaseClient.from('ai_generated_meal_plans').update({
        total_meals: plan.weeks[0].days.reduce((total, day) => total + (day.meals || []).length, 0)
    }).eq('id', planId).eq('user_id', user.id);
    _aiMealPlanCache = plan;
    try { localStorage.setItem('ai_meal_plan', JSON.stringify(plan)); } catch (_) {}
    ensureExactMealPlanPhotos(plan, user.id, { meals: addedDays.flatMap(day => day.meals || []) })
        .catch(error => console.warn('[meta-ad-trial] Remaining meal photos will retry later:', error));
}

async function buildFreshMetaPreviewMealPlan(profile, foodPreferences, signature) {
    return buildPreparedMetaPreviewMealPlan(profile, foodPreferences, signature);
    /* Legacy generated-plan implementation retained temporarily for rollback.
       The customer flow above never enters it. */
    const user = window.currentUser || await waitForCurrentUser();
    if (!user || !window.supabaseClient) throw new Error('Your preview account is still connecting. Please try again.');
    const dayNames = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
    const generatedDays = [];
    let newPlanId = null;
    const calorieGoal = Number(profile.calorie_goal || profile.calorieGoal || profile.daily_calorie_target || 2000);
    const targets = {
        calorie_goal: Number.isFinite(calorieGoal) && calorieGoal >= 1200 ? calorieGoal : 2000,
        protein_goal_g: Number(profile.protein_goal_g || profile.proteinGoal || 0) || null,
        carbs_goal_g: Number(profile.carbs_goal_g || profile.carbsGoal || 0) || null,
        fat_goal_g: Number(profile.fat_goal_g || profile.fatGoal || 0) || null
    };
    const profileForGenerator = { ...profile, ...targets };

    try {
        const firstDayNumber = getAiMealPlanTodayIndex();
        const generateDay = async (dayNumber, previousDays) => {
            const result = await fetchMealPlanDay({
                userData: { profile: profileForGenerator, quizResults: profileForGenerator, facts: {}, foodPreferences },
                weekNumber: 1,
                dayNumber,
                previousDays,
                previousWeeks: []
            }, { timeoutMs: 30000, maxAttempts: 2 });
            return { ...result.day, day_of_week: dayNumber, day_name: result.day.day_name || dayNames[dayNumber] };
        };

        setMetaPreviewMealPlanBuildStatus(`Creating ${dayNames[firstDayNumber]} first so your tour has something real to show.`, 8);
        generatedDays.push(await generateDay(firstDayNumber, []));
        setMetaPreviewMealPlanBuildStatus('Saving your first personalised day.', 68);
        const parent = await window.supabaseClient.from('ai_generated_meal_plans').insert({
            user_id: user.id,
            plan_name: 'Your Personalised First Week',
            plan_description: 'Created fresh from the food choices in your Balance setup.',
            status: 'generating',
            ...targets,
            diet_type: foodPreferences.diet_type || 'omnivore',
            total_meals: generatedDays.reduce((sum, day) => sum + (day.meals || []).length, 0),
            current_week: 1
        }).select('id,generated_at').single();
        if (parent.error) throw parent.error;
        newPlanId = parent.data.id;

        const weekInsert = await window.supabaseClient.from('ai_meal_plan_weeks').insert({
            plan_id: newPlanId,
            week_number: 1,
            theme: 'Your personalised first week',
            theme_description: 'Meals chosen around the food style and restrictions you selected during setup.'
        });
        if (weekInsert.error) throw weekInsert.error;

        const mealRows = [];
        generatedDays.forEach(day => (day.meals || []).forEach(meal => mealRows.push({
            plan_id: newPlanId, week_number: 1, day_of_week: day.day_of_week, day_name: day.day_name,
            meal_slot: meal.meal_slot, meal_time: meal.meal_time, name: meal.name,
            description: meal.description, calories: meal.calories, protein_g: meal.protein_g,
            carbs_g: meal.carbs_g, fat_g: meal.fat_g, fiber_g: meal.fiber_g,
            ingredients: meal.ingredients || [], preparation: meal.preparation,
            prep_time_mins: meal.prep_time_mins, cook_time_mins: meal.cook_time_mins,
            tags: meal.tags || [], cuisine: meal.cuisine, image_url: ''
        })));
        const mealsInsert = await window.supabaseClient.from('ai_generated_meals').insert(mealRows).select('id,week_number,day_of_week,meal_slot');
        if (mealsInsert.error) throw mealsInsert.error;
        const insertedByPosition = new Map((mealsInsert.data || []).map(row => [`${row.week_number}:${row.day_of_week}:${row.meal_slot}`, row.id]));
        generatedDays.forEach(day => (day.meals || []).forEach(meal => {
            meal.id = insertedByPosition.get(`1:${day.day_of_week}:${meal.meal_slot}`) || meal.id;
            meal.image_url = '';
        }));

        const plan = {
            id: newPlanId,
            plan_name: 'Your Personalised First Week',
            plan_description: 'Created fresh from the food choices in your Balance setup.',
            generated_at: parent.data.generated_at,
            meta_preview_signature: signature,
            meta_preview_owner_id: user.id,
            diet_type: foodPreferences.diet_type || 'omnivore',
            dietary_requirements: [...(foodPreferences.dietary_requirements || [])],
            ...targets,
            weeks: [{ week_number: 1, theme: 'Your personalised first week', theme_description: 'Meals chosen around your setup answers.', days: generatedDays }]
        };
        _aiMealPlanCache = plan;
        _aiMealPlanCurrentWeek = 1;
        _aiMealPlanCurrentDay = 0;
        showAiPlanLoaded(plan);

        const firstDayMeals = generatedDays.find(day => day.day_of_week === firstDayNumber)?.meals || [];
        setMetaPreviewMealPlanBuildStatus('Creating photos that match your first meals.', 76);
        const firstDayPhotoResult = await ensureExactMealPlanPhotos(plan, user.id, {
            meals: firstDayMeals,
            onProgress: (done, total) => setMetaPreviewMealPlanBuildStatus(`Creating meal photos ${done} of ${total}.`, 76 + Math.round((done / Math.max(total, 1)) * 18))
        });
        const firstDayWithoutPhotos = firstDayMeals.filter(meal => window.resolveMealPlanPhotoDetails?.(meal)?.source === 'missing');
        if (firstDayWithoutPhotos.length) throw new Error(`The first-day meal photos are not ready yet [${firstDayPhotoResult.failureStage || 'photo_service'}]`);

        const activate = await window.supabaseClient.from('ai_generated_meal_plans').update({ status: 'active' }).eq('id', newPlanId).eq('user_id', user.id);
        if (activate.error) throw activate.error;
        const archive = await window.supabaseClient.from('ai_generated_meal_plans').update({ status: 'archived' }).eq('user_id', user.id).eq('status', 'active').neq('id', newPlanId);
        if (archive.error) console.warn('[meta-ad-trial] Could not archive the previous meal plan:', archive.error);
        try {
            localStorage.setItem('ai_meal_plan', JSON.stringify(plan));
            localStorage.setItem('pbb_meta_preview_meal_signature', signature);
            localStorage.setItem(`pbb_meta_preview_plan_id_${user.id}`, newPlanId);
        } catch (e) {}
        setMetaPreviewMealPlanBuildStatus('Your first meals are ready. Finishing the rest of your week in the background.', 100, 'ready');
        try { window.trackBalanceActivity('meta_preview_meal_plan_generation_ready', { meal_count: mealRows.length, dietary_tag_count: (foodPreferences.dietary_requirements || []).length }); } catch (e) {}
        completeRemainingMetaPreviewDaysInBackground({
            user, plan, planId: newPlanId, profileForGenerator, foodPreferences, firstDayNumber, dayNames
        }).catch(error => console.warn('[meta-ad-trial] Remaining meal-plan days will retry later:', error));
        return plan;
    } catch (error) {
        if (newPlanId) {
            try { await window.supabaseClient.from('ai_generated_meal_plans').delete().eq('id', newPlanId).eq('user_id', user.id); } catch (cleanupError) {}
        }
        if (_aiMealPlanCache?.id === newPlanId) _aiMealPlanCache = null;
        try {
            localStorage.removeItem('ai_meal_plan');
            localStorage.removeItem('pbb_meta_preview_meal_signature');
            localStorage.removeItem(`pbb_meta_preview_plan_id_${user.id}`);
        } catch (cleanupError) {}
        setMetaPreviewMealPlanBuildStatus('We could not finish it yet. Tap Choose my meal plan to try again.', 0, 'error');
        try { window.trackBalanceActivity('meta_preview_meal_plan_generation_failed', { stage: newPlanId ? 'save_or_photos' : 'generation' }); } catch (e) {}
        throw error;
    }
}

async function buildPreparedMetaPreviewMealPlan(profile, foodPreferences, signature) {
    const user = window.currentUser || await waitForCurrentUser();
    if (!user || !window.supabaseClient) throw new Error('Your preview account is still connecting. Please try again.');
    const calorieGoal = Number(profile.calorie_goal || profile.calorieGoal || profile.daily_calorie_target || 2000);
    const targets = {
        calorie_goal: Number.isFinite(calorieGoal) && calorieGoal >= 1200 ? calorieGoal : 2000,
        protein_goal_g: Number(profile.protein_goal_g || profile.proteinGoal || 0) || null,
        carbs_goal_g: Number(profile.carbs_goal_g || profile.carbsGoal || 0) || null,
        fat_goal_g: Number(profile.fat_goal_g || profile.fatGoal || 0) || null
    };
    let result = null;
    try {
        setMetaPreviewMealPlanBuildStatus('Selecting your prepared meal plan.', 45);
        await window.supabaseClient.from('ai_generated_meal_plans')
            .update({ status: 'archived' }).eq('user_id', user.id).eq('status', 'active');
        result = await window.populatePreparedMealPlan(window.supabaseClient, user.id, targets, foodPreferences);
        const plan = result.plan;
        plan.meta_preview_signature = signature;
        plan.meta_preview_owner_id = user.id;
        _aiMealPlanCache = plan;
        _aiMealPlanCurrentWeek = 1;
        _aiMealPlanCurrentDay = 0;
        localStorage.setItem('ai_meal_plan', JSON.stringify(plan));
        localStorage.setItem('pbb_meta_preview_meal_signature', signature);
        localStorage.setItem(`pbb_meta_preview_plan_id_${user.id}`, result.plan_id);
        showAiPlanLoaded(plan);
        setMetaPreviewMealPlanBuildStatus('Your prepared meal plan is ready.', 100, 'ready');
        try {
            window.trackBalanceActivity('meta_preview_meal_plan_generation_ready', {
                source: 'prepared_library', template_id: plan.template_id,
                meal_count: 35, dietary_tag_count: (foodPreferences.dietary_requirements || []).length
            });
        } catch (_) {}
        return plan;
    } catch (error) {
        if (result?.plan_id) {
            try { await window.supabaseClient.from('ai_generated_meal_plans').delete().eq('id', result.plan_id).eq('user_id', user.id); } catch (_) {}
        }
        setMetaPreviewMealPlanBuildStatus('We could not select it yet. Tap Choose my meal plan to try again.', 0, 'error');
        throw error;
    }
}

function startFreshMetaPreviewMealPlan() {
    if (window.metaAdTrialMode !== true) return Promise.resolve(null);
    const { profile, foodPreferences } = readMetaPreviewMealInputs();
    const signature = metaPreviewMealPlanSignature(profile, foodPreferences);
    if (_metaPreviewMealPlanBuildPromise && _metaPreviewMealPlanBuildSignature === signature) return _metaPreviewMealPlanBuildPromise;

    _metaPreviewMealPlanBuildSignature = signature;
    _aiMealPlanCache = null;
    try {
        localStorage.removeItem('ai_meal_plan');
        localStorage.removeItem('pbb_meta_preview_meal_signature');
        const userId = window.currentUser?.id || window.currentUser?.user_id;
        if (userId) localStorage.removeItem(`pbb_meta_preview_plan_id_${userId}`);
    } catch (e) {}
    setMetaPreviewMealPlanBuildStatus('Using the food choices you just made.', 3);
    try { window.trackBalanceActivity('meta_preview_meal_plan_generation_started', { dietary_tag_count: (foodPreferences.dietary_requirements || []).length }); } catch (e) {}
    _metaPreviewMealPlanBuildPromise = buildFreshMetaPreviewMealPlan(profile, foodPreferences, signature)
        .finally(() => { _metaPreviewMealPlanBuildPromise = null; });
    return _metaPreviewMealPlanBuildPromise;
}
window.startFreshMetaPreviewMealPlan = startFreshMetaPreviewMealPlan;

async function ensureMetaPreviewMealPlan() {
    if (window.metaAdTrialMode !== true) return null;
    const user = window.currentUser || await waitForCurrentUser();
    if (!user) return null;
    const { profile, foodPreferences } = readMetaPreviewMealInputs();
    const signature = metaPreviewMealPlanSignature(profile, foodPreferences);
    if (_metaPreviewMealPlanBuildPromise && _metaPreviewMealPlanBuildSignature === signature) return _metaPreviewMealPlanBuildPromise;
    if (_aiMealPlanCache?.meta_preview_signature === signature && _aiMealPlanCache?.meta_preview_owner_id === user.id && Array.isArray(_aiMealPlanCache.weeks)) {
        showAiPlanLoaded(_aiMealPlanCache);
        return _aiMealPlanCache;
    }
    let savedPlan = null;
    try { savedPlan = JSON.parse(localStorage.getItem('ai_meal_plan') || 'null'); } catch (e) {}
    if (savedPlan?.meta_preview_signature === signature && savedPlan?.meta_preview_owner_id === user.id && Array.isArray(savedPlan.weeks)) {
        _aiMealPlanCache = savedPlan;
        showAiPlanLoaded(savedPlan);
        return savedPlan;
    }
    return startFreshMetaPreviewMealPlan();
}
window.ensureMetaPreviewMealPlan = ensureMetaPreviewMealPlan;

async function claimMetaPreviewWorkoutCalendar(userId) {
    const calendar = getStoredOnboardingWorkoutCalendar(window.userProfile || {});
    if (!calendar) throw new Error('Preview workout calendar is missing');

    const existingFacts = await dbHelpers.userFacts.get(userId).catch(() => ({}));
    const currentDetails = existingFacts?.personal_details || {};
    const calendarJson = JSON.stringify(calendar);
    let calendarTimes = {};
    try { calendarTimes = JSON.parse(localStorage.getItem('workoutCalendarTimes') || '{}'); } catch (e) {}
    await dbHelpers.userFacts.upsert(userId, {
        personal_details: {
            ...currentDetails,
            workout_calendar: calendarJson,
            workout_calendar_times: calendarTimes
        }
    });

    const savedFacts = await dbHelpers.userFacts.get(userId);
    const savedCalendar = parseStoredWorkoutCalendar(savedFacts?.personal_details?.workout_calendar);
    const calendarMatches = savedCalendar && PBB_ONBOARDING_DAY_KEYS.every(day => savedCalendar[day] === calendar[day]);
    if (!calendarMatches) {
        throw new Error('Preview workout calendar was not confirmed in the account');
    }
    window.userProfile = { ...(window.userProfile || {}), workout_calendar: calendarJson };
    return savedCalendar;
}

async function claimMetaPreviewMealPlan(userId) {
    let previewPlan = null;
    try { previewPlan = JSON.parse(localStorage.getItem('ai_meal_plan') || 'null'); } catch (e) {}
    if (!previewPlan || !Array.isArray(previewPlan.weeks) || previewPlan.weeks.length === 0) {
        throw new Error('Preview meal plan is missing');
    }
    const claimPlanKey = `pbb_meta_preview_plan_id_${userId}`;
    if (previewPlan.id) {
        const generatedPlan = await window.supabaseClient
            .from('ai_generated_meal_plans')
            .select('id')
            .eq('id', previewPlan.id)
            .eq('user_id', userId)
            .eq('status', 'active')
            .maybeSingle();
        if (generatedPlan.error) throw generatedPlan.error;
        if (generatedPlan.data?.id) {
            localStorage.setItem(claimPlanKey, generatedPlan.data.id);
            return previewPlan;
        }
    }
    const previouslySavedPlanId = localStorage.getItem(claimPlanKey);
    if (previouslySavedPlanId) {
        const existing = await window.supabaseClient
            .from('ai_generated_meal_plans')
            .select('id')
            .eq('id', previouslySavedPlanId)
            .eq('user_id', userId)
            .eq('status', 'active')
            .maybeSingle();
        if (existing.error) throw existing.error;
        if (existing.data?.id) {
            const accountPlan = { ...previewPlan, id: existing.data.id };
            _aiMealPlanCache = accountPlan;
            localStorage.setItem('ai_meal_plan', JSON.stringify(accountPlan));
            return accountPlan;
        }
        localStorage.removeItem(claimPlanKey);
    }

    if (typeof window.persistBuiltMealPlan !== 'function') {
        throw new Error('Meal plan persistence is not ready');
    }
    const result = await window.persistBuiltMealPlan(window.supabaseClient, userId, previewPlan);
    if (!result?.success || !result?.plan_id) {
        throw new Error('Preview meal plan was not confirmed in the account');
    }
    const accountPlan = { ...previewPlan, id: result.plan_id };
    _aiMealPlanCache = accountPlan;
    localStorage.setItem(claimPlanKey, result.plan_id);
    localStorage.setItem('ai_meal_plan', JSON.stringify(accountPlan));
    return accountPlan;
}

async function ensureInitialOnboardingMealPlan() {
    if (window.metaAdTrialMode === true) {
        const previewPlan = await ensureMetaPreviewMealPlan();
        return { status: previewPlan ? 'preview_ready' : 'preview_unavailable' };
    }
    const user = window.currentUser || await waitForCurrentUser();
    if (!user || !window.supabaseClient) return { status: 'no_user' };

    try {
        const existing = await window.supabaseClient
            .from('ai_generated_meal_plans')
            .select('id,plan_name,status')
            .eq('user_id', user.id)
            .eq('status', 'active')
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();
        if (existing.error) throw existing.error;
        if (existing.data?.id) return { status: 'ready', planId: existing.data.id };

        await generateAiMealPlan();

        const generated = await window.supabaseClient
            .from('ai_generated_meal_plans')
            .select('id,plan_name,status')
            .eq('user_id', user.id)
            .eq('status', 'active')
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();
        if (generated.error) throw generated.error;
        if (generated.data?.id) return { status: 'generated', planId: generated.data.id };
        return { status: 'not_ready' };
    } catch (error) {
        console.warn('[onboarding] initial meal plan preparation failed:', error);
        return { status: 'failed', error: error?.message || String(error) };
    }
}

// Image generation functionality removed

function weeklyEvolutionDateString(date) {
    const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
    return local.toISOString().slice(0, 10);
}

async function loadWeeklyEvolutionHistory(userId) {
    const end = new Date();
    const start = new Date(end);
    start.setDate(start.getDate() - 6);
    const { data, error } = await window.supabaseClient
        .from('meal_logs')
        .select('meal_date,meal_time,meal_type,meal_description,notes,food_items,calories,protein_g,carbs_g,fat_g,fiber_g,micronutrients,photo_url')
        .eq('user_id', userId)
        .neq('meal_type', 'water')
        .gte('meal_date', weeklyEvolutionDateString(start))
        .lte('meal_date', weeklyEvolutionDateString(end))
        .order('meal_date', { ascending: true })
        .order('meal_time', { ascending: true });
    if (error) throw error;
    return { meals: data || [], start: weeklyEvolutionDateString(start), end: weeklyEvolutionDateString(end) };
}

async function loadWeeklyEvolutionPreferences(userId) {
    try {
        const { data } = await window.supabaseClient
            .from('user_food_preferences').select('*').eq('user_id', userId).maybeSingle();
        if (data) return data;
    } catch (e) {}
    try { return JSON.parse(localStorage.getItem('user_food_preferences') || '{}'); } catch (e) { return {}; }
}

let _weeklyEvolutionHomeRefreshPromise = null;
let _weeklyEvolutionHomeBuildInProgress = false;

function weeklyEvolutionHomeCard() {
    return document.getElementById('weekly-meal-evolution-home-card');
}

function hideWeeklyMealEvolutionHomeCard() {
    const card = weeklyEvolutionHomeCard();
    if (!card) return;
    card.style.display = 'none';
    card.innerHTML = '';
    card.removeAttribute('data-state');
}

function openWeeklyMealEvolutionPlan() {
    const mealsButton = document.querySelector('.bottom-nav .nav-item[onclick*="meals"]');
    if (typeof switchAppTab === 'function') switchAppTab('meals', mealsButton);
    setTimeout(() => {
        const pill = document.getElementById('browse-plans-pill');
        if (typeof switchWeek === 'function') switchWeek('meal-plan-store', pill);
    }, 120);
}

function renderWeeklyMealEvolutionHomeCard(state) {
    const card = weeklyEvolutionHomeCard();
    if (!card) return;
    const copy = {
        ready: {
            icon: '✓', eyebrow: 'Meal tracking complete', title: 'Your next week is ready to tailor',
            body: 'You tracked enough meals for Balance to shape next week around what you actually eat, with small adjustments toward your targets and two fresh variations.',
            action: 'Tailor next week'
        },
        generating: {
            icon: '✦', eyebrow: 'Tailoring next week', title: 'Turning your logs into your plan',
            body: 'Balance is keeping your familiar favourites, adjusting the details around your targets, and adding two fresh variations.',
            action: 'Building your plan...'
        },
        tailored: {
            icon: '✓', eyebrow: 'Next week is ready', title: 'Your meals, tailored to you',
            body: 'Because you tracked your meals this week, Balance has tailored next week around what you actually eat. You will keep familiar favourites, get small adjustments to help you hit your targets, and meet two fresh variations along the way.',
            action: 'View next week'
        },
        retry: {
            icon: '↻', eyebrow: 'Your logs are ready', title: 'Let’s try tailoring next week again',
            body: 'Your current meal plan is still safe. Tap below and Balance will use this week’s meals to try again.',
            action: 'Try again'
        }
    }[state];
    if (!copy) return hideWeeklyMealEvolutionHomeCard();

    card.dataset.state = state;
    card.style.display = 'block';
    card.onclick = null;
    card.onkeydown = null;
    card.removeAttribute('role');
    card.removeAttribute('tabindex');
    card.removeAttribute('aria-label');
    card.removeAttribute('data-interactive');
    card.innerHTML = `<div class="weekly-meal-evolution-home-card__inner">
        <div class="weekly-meal-evolution-home-card__row">
            <div class="weekly-meal-evolution-home-card__icon" aria-hidden="true">${copy.icon}</div>
            <div class="weekly-meal-evolution-home-card__content">
                <div class="weekly-meal-evolution-home-card__eyebrow">${copy.eyebrow}</div>
                <h3 class="weekly-meal-evolution-home-card__title">${copy.title}</h3>
                <p class="weekly-meal-evolution-home-card__body">${copy.body}</p>
            </div>
        </div>
        <div class="weekly-meal-evolution-home-card__action" ${state === 'generating' ? 'aria-busy="true"' : ''}>${copy.action}</div>
    </div>`;

    const activate = state === 'tailored'
        ? openWeeklyMealEvolutionPlan
        : (state === 'ready' || state === 'retry') ? runWeeklyEvolutionBuildFromHome : null;
    if (activate) {
        card.dataset.interactive = 'true';
        card.setAttribute('role', 'button');
        card.setAttribute('tabindex', '0');
        card.setAttribute('aria-label', copy.action);
        card.onclick = activate;
        card.onkeydown = event => {
            if (event.key !== 'Enter' && event.key !== ' ') return;
            event.preventDefault();
            activate();
        };
    }
}

function weeklyEvolutionPlanIsRecent(plan, nowValue) {
    if (!window.weeklyMealEvolution?.isEvolvingPlan(plan)) return false;
    const generated = new Date(plan?.generated_at || plan?.created_at || 0);
    const now = new Date(nowValue || Date.now());
    return Number.isFinite(generated.getTime()) && now >= generated && now - generated < 6.5 * 86400000;
}

async function loadActiveWeeklyEvolutionPlan(userId) {
    if (_aiMealPlanCache?.id) return _aiMealPlanCache;
    const { data, error } = await window.supabaseClient
        .from('ai_generated_meal_plans')
        .select('id,plan_name,plan_description,generated_at,created_at,status')
        .eq('user_id', userId)
        .eq('status', 'active')
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
    if (error) throw error;
    return data || null;
}

async function runWeeklyEvolutionBuildFromHome() {
    if (_weeklyEvolutionHomeBuildInProgress || _aiMealPlanGenerationInProgress) return false;
    const engine = window.weeklyMealEvolution;
    if (!engine) return false;
    const cycle = engine.weeklyCycle(new Date());
    const attemptKey = `pbb_weekly_meal_evolution_attempt_v2_${cycle.key}`;
    try { localStorage.setItem(attemptKey, new Date().toISOString()); } catch (e) {}
    _weeklyEvolutionHomeBuildInProgress = true;
    renderWeeklyMealEvolutionHomeCard('generating');
    try {
        const success = await buildNextWeekFromMealHistory({ automatic: true, source: 'home_card' });
        if (success) {
            renderWeeklyMealEvolutionHomeCard('tailored');
            return true;
        }
        renderWeeklyMealEvolutionHomeCard('retry');
        return false;
    } finally {
        _weeklyEvolutionHomeBuildInProgress = false;
    }
}

async function refreshWeeklyMealEvolutionHomeCard(options = {}) {
    if (_weeklyEvolutionHomeRefreshPromise) return _weeklyEvolutionHomeRefreshPromise;
    _weeklyEvolutionHomeRefreshPromise = (async () => {
        const card = weeklyEvolutionHomeCard();
        const engine = window.weeklyMealEvolution;
        if (!card || !engine || !window.supabaseClient) return false;
        const user = window.currentUser || await waitForCurrentUser();
        if (!user) return false;
        try {
            const access = typeof checkMealPlanAccess === 'function' ? checkMealPlanAccess() : { hasAccess: true };
            if (!access?.hasAccess) {
                hideWeeklyMealEvolutionHomeCard();
                return false;
            }

            const now = new Date();
            const plan = options.plan || await loadActiveWeeklyEvolutionPlan(user.id);
            if (engine.isPlanFreshForCycle(plan, now) || weeklyEvolutionPlanIsRecent(plan, now)) {
                renderWeeklyMealEvolutionHomeCard('tailored');
                return true;
            }

            const history = await loadWeeklyEvolutionHistory(user.id);
            const coverage = engine.assessHistory(history.meals);
            const cycle = engine.weeklyCycle(now);
            if (!cycle.isBuildWindow || !coverage.eligible) {
                hideWeeklyMealEvolutionHomeCard();
                return false;
            }

            renderWeeklyMealEvolutionHomeCard('ready');
            const attemptKey = `pbb_weekly_meal_evolution_attempt_v2_${cycle.key}`;
            let lastAttemptAt = '';
            try { lastAttemptAt = localStorage.getItem(attemptKey) || ''; } catch (e) {}
            const allowAuto = options.allowAuto !== false;
            if (allowAuto && engine.shouldAutoBuild({ now, plan, coverage, lastAttemptAt })) {
                await runWeeklyEvolutionBuildFromHome();
            }
            return true;
        } catch (error) {
            console.warn('Weekly meal Home card could not refresh:', error);
            hideWeeklyMealEvolutionHomeCard();
            return false;
        }
    })();
    try {
        return await _weeklyEvolutionHomeRefreshPromise;
    } finally {
        _weeklyEvolutionHomeRefreshPromise = null;
    }
}

async function buildNextWeekFromMealHistory(options) {
    const automatic = !!options?.automatic;
    const user = window.currentUser || await waitForCurrentUser();
    const engine = window.weeklyMealEvolution;
    if (!user) {
        if (!automatic) alert('Please log in to build next week.');
        return false;
    }
    if (!engine) {
        if (!automatic) alert('The weekly meal planner is still loading. Please try again in a moment.');
        return false;
    }
    if (_aiMealPlanGenerationInProgress) return false;
    if (!automatic && !confirm("Build next week's plan from the meals you logged? Your current plan will stay in place until the new one is ready.")) return false;

    const previousPlan = _aiMealPlanCache;
    _aiMealPlanGenerationInProgress = true;
    showAiPlanGenerating();
    updateAiPlanGeneratingStatus('Reviewing the meals you logged this week...', '8%');
    let newPlanId = null;

    try {
        const history = await loadWeeklyEvolutionHistory(user.id);
        const coverage = engine.assessHistory(history.meals);
        if (!coverage.eligible) {
            if (!automatic) alert(`Balance needs a little more food history first. Please ${coverage.reasons.join(', ')}.`);
            if (previousPlan) showAiPlanLoaded(previousPlan); else showAiPlanEmpty();
            return false;
        }

        const quizPromise = window.dbHelpers?.quizResults?.getLatest
            ? window.dbHelpers.quizResults.getLatest(user.id).catch(() => ({}))
            : Promise.resolve({});
        const factsPromise = window.dbHelpers?.userFacts?.get
            ? window.dbHelpers.userFacts.get(user.id).catch(() => ({}))
            : Promise.resolve({});
        const [targets, foodPreferences, quizResult, factsResult] = await Promise.all([
            window.getUserNutritionTargets(window.supabaseClient, user.id),
            loadWeeklyEvolutionPreferences(user.id),
            quizPromise,
            factsPromise
        ]);
        const blueprint = engine.buildBlueprint(history.meals);
        const dietType = foodPreferences?.diet_type || foodPreferences?.dietary_requirements?.[0] || 'vegan';
        const nutritionFocus = engine.buildNutritionFocus(history.meals, targets || {}, dietType);
        const guidance = engine.guidanceText(nutritionFocus, coverage.mealCount);
        const profile = { name: user.user_metadata?.name || user.email?.split('@')[0] || 'User' };
        const generatedDays = [];

        for (let dayNumber = 0; dayNumber < 7; dayNumber++) {
            updateAiPlanGeneratingStatus(`Building ${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][dayNumber]} from your usual meals...`, `${12 + Math.round(dayNumber * 9)}%`);
            const dayBlueprint = blueprint.filter(item => item.day_of_week === dayNumber);
            const result = await fetchMealPlanDay({
                userData: { profile, quizResults: { ...(quizResult || {}), ...(targets || {}) }, facts: factsResult || {}, foodPreferences },
                weekNumber: 1,
                dayNumber,
                previousDays: generatedDays.map(day => ({ day_name: day.day_name, mealNames: day.meals.map(meal => meal.name) })),
                previousWeeks: [],
                adaptiveWeek: {
                    sourceStart: history.start,
                    sourceEnd: history.end,
                    loggedMealCount: coverage.mealCount,
                    variationLimit: 2,
                    nutritionFocus,
                    meals: dayBlueprint
                }
            });
            const mealsBySlot = new Map((result.day?.meals || []).map(meal => [meal.meal_slot, meal]));
            const finalMeals = dayBlueprint.map(item => {
                const generated = mealsBySlot.get(item.meal_slot);
                if (!generated) throw new Error(`Missing ${item.meal_slot} for day ${dayNumber + 1}`);
                return {
                    ...generated,
                    name: item.variation ? generated.name : item.base_meal.name,
                    tags: [...new Set([...(generated.tags || []), item.variation ? 'New variation' : 'Familiar favourite'])],
                    image_url: resolveMealPlanPhotoUrl({
                        ...generated,
                        name: item.variation ? generated.name : item.base_meal.name,
                        image_url: item.variation ? '' : item.base_meal.image_url
                    })
                };
            });
            generatedDays.push({ ...result.day, day_of_week: dayNumber, meals: finalMeals });
        }

        updateAiPlanGeneratingStatus('Saving your next week...', '82%');
        const parent = await window.supabaseClient.from('ai_generated_meal_plans').insert({
            user_id: user.id,
            plan_name: 'Your Evolving Weekly Plan',
            plan_description: 'Your usual meals, gently adjusted for this week.',
            status: 'generating',
            calorie_goal: targets?.calorie_goal || null,
            protein_goal_g: targets?.protein_goal_g || null,
            carbs_goal_g: targets?.carbs_goal_g || null,
            fat_goal_g: targets?.fat_goal_g || null,
            diet_type: dietType,
            total_meals: 35,
            current_week: 1
        }).select('id,generated_at').single();
        if (parent.error) throw parent.error;
        newPlanId = parent.data.id;

        const weekInsert = await window.supabaseClient.from('ai_meal_plan_weeks').insert({
            plan_id: newPlanId,
            week_number: 1,
            theme: 'Familiar favourites with two fresh twists',
            theme_description: guidance
        });
        if (weekInsert.error) throw weekInsert.error;

        const mealRows = [];
        generatedDays.forEach(day => day.meals.forEach(meal => mealRows.push({
            plan_id: newPlanId, week_number: 1, day_of_week: day.day_of_week, day_name: day.day_name,
            meal_slot: meal.meal_slot, meal_time: meal.meal_time, name: meal.name,
            description: meal.description, calories: meal.calories, protein_g: meal.protein_g,
            carbs_g: meal.carbs_g, fat_g: meal.fat_g, fiber_g: meal.fiber_g,
            ingredients: meal.ingredients || [], preparation: meal.preparation,
            prep_time_mins: meal.prep_time_mins, cook_time_mins: meal.cook_time_mins,
            tags: meal.tags || [], cuisine: meal.cuisine, image_url: resolveMealPlanPhotoUrl(meal)
        })));
        const mealsInsert = await window.supabaseClient
            .from('ai_generated_meals')
            .insert(mealRows)
            .select('id,week_number,day_of_week,meal_slot');
        if (mealsInsert.error) throw mealsInsert.error;

        const insertedByPosition = new Map((mealsInsert.data || []).map(row => [
            `${row.week_number}:${row.day_of_week}:${row.meal_slot}`,
            row.id
        ]));
        generatedDays.forEach(day => day.meals.forEach(meal => {
            meal.id = insertedByPosition.get(`1:${day.day_of_week}:${meal.meal_slot}`) || meal.id;
        }));

        updateAiPlanGeneratingStatus('Creating photos that match each meal...', '88%');
        const photoPlan = {
            id: newPlanId,
            weeks: [{ week_number: 1, days: generatedDays }]
        };
        await ensureExactMealPlanPhotos(photoPlan, user.id, {
            onProgress: (done, total) => updateAiPlanGeneratingStatus(
                `Creating meal photos ${done} of ${total}...`,
                `${88 + Math.round((done / Math.max(total, 1)) * 9)}%`
            )
        });

        const activate = await window.supabaseClient.from('ai_generated_meal_plans').update({ status: 'active' }).eq('id', newPlanId);
        if (activate.error) throw activate.error;
        const archive = await window.supabaseClient.from('ai_generated_meal_plans').update({ status: 'archived' }).eq('user_id', user.id).eq('status', 'active').neq('id', newPlanId);
        if (archive.error) console.warn('Could not archive the previous meal plan:', archive.error);

        const plan = {
            id: newPlanId, plan_name: 'Your Evolving Weekly Plan',
            plan_description: 'Your usual meals, gently adjusted for this week.',
            generated_at: parent.data.generated_at,
            weeks: [{ week_number: 1, theme: 'Familiar favourites with two fresh twists', theme_description: guidance, days: generatedDays }]
        };
        _aiMealPlanCache = plan;
        _aiMealPlanCurrentWeek = 1;
        _aiMealPlanCurrentDay = 0;
        try { localStorage.setItem('ai_meal_plan', JSON.stringify(plan)); } catch (e) {}
        updateAiPlanGeneratingStatus('Your next week is ready!', '100%');
        setTimeout(() => showAiPlanLoaded(plan), 350);
        notifyMealPlanReady(user.id, 1);
        return true;
    } catch (error) {
        console.error('Weekly meal evolution failed:', error);
        if (newPlanId) {
            try { await window.supabaseClient.from('ai_generated_meal_plans').delete().eq('id', newPlanId); } catch (cleanupError) {}
        }
        if (!automatic) alert('Balance could not build next week right now. Your current plan has not been changed.');
        if (previousPlan) showAiPlanLoaded(previousPlan); else showAiPlanEmpty();
        return false;
    } finally {
        _aiMealPlanGenerationInProgress = false;
    }
}

function maybeBuildWeeklyPlanAtWeekEnd(plan) {
    if (_aiMealPlanGenerationInProgress) return;
    refreshWeeklyMealEvolutionHomeCard({ allowAuto: true, plan }).catch(error => {
        console.warn('Weekly meal evolution check failed:', error);
    });
}

window.buildNextWeekFromMealHistory = buildNextWeekFromMealHistory;
window.refreshWeeklyMealEvolutionHomeCard = refreshWeeklyMealEvolutionHomeCard;
window.openWeeklyMealEvolutionPlan = openWeeklyMealEvolutionPlan;
window.addEventListener('pbbWeeklyMealEvolutionReady', () => {
    setTimeout(() => refreshWeeklyMealEvolutionHomeCard(), 150);
});

/**
 * Generate the next week of the meal plan.
 * Appends a new week to the existing plan.
 */
async function generateNextWeek() {
    const user = window.currentUser;
    if (!user || !_aiMealPlanCache) return;

    const currentWeeks = _aiMealPlanCache.weeks || [];
    const nextWeekNum = currentWeeks.length + 1;
    if (nextWeekNum > 4) {
        alert('You already have 4 weeks generated!');
        return;
    }

    showAiPlanGenerating();
    const statusEl = document.getElementById('ai-plan-gen-status');
    const progressEl = document.getElementById('ai-plan-gen-progress');

    try {
        if (statusEl) statusEl.textContent = `Week ${nextWeekNum} — Tailoring Day 1 — Monday...`;
        if (progressEl) progressEl.style.width = '10%';

        // Gather user data
        const db = window.dbHelpers;
        const [quizResult, factsResult, prefsResult] = await Promise.allSettled([
            db.quizResults.getLatest(user.id),
            db.userFacts.get(user.id),
            (async () => {
                try {
                    const { data } = await window.supabaseClient
                        .from('user_food_preferences').select('*').eq('user_id', user.id).maybeSingle();
                    if (data) return data;
                } catch (e) {}
                try { return JSON.parse(localStorage.getItem('user_food_preferences') || '{}'); } catch (e) { return {}; }
            })()
        ]);

        // Build previous weeks context
        const previousWeeks = currentWeeks.map(w => {
            const mealNames = [];
            (w.days || []).forEach(d => (d.meals || []).forEach(m => mealNames.push(m.name)));
            return { weekNumber: w.week_number, theme: w.theme, mealNames };
        });

        const nwUserPayload = {
            profile: { name: user.user_metadata?.name || user.email?.split('@')[0] || 'User' },
            quizResults: quizResult.status === 'fulfilled' ? (quizResult.value || {}) : {},
            facts: factsResult.status === 'fulfilled' ? (factsResult.value || {}) : {},
            foodPreferences: prefsResult.status === 'fulfilled' ? (prefsResult.value || {}) : {}
        };

        // Generate day-by-day for the new week
        const nwDayLabels = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
        const nwVerbs = ['Tailoring', 'Cooking up', 'Preparing', 'Crafting', 'Plating', 'Seasoning', 'Finishing'];
        const nwGeneratedDays = [];
        let nwWeekMeta = null;

        for (let d = 0; d < 7; d++) {
            const pct = 5 + Math.round((d / 7) * 65);
            if (statusEl) statusEl.textContent = `Week ${nextWeekNum} — ${nwVerbs[d]} Day ${d + 1} — ${nwDayLabels[d]}...`;
            if (progressEl) progressEl.style.width = `${pct}%`;

            const nwPreviousDays = nwGeneratedDays.map(day => ({
                day_name: day.day_name,
                mealNames: (day.meals || []).map(m => m.name)
            }));

            const dayResult = await fetchMealPlanDay({
                userData: nwUserPayload,
                weekNumber: nextWeekNum,
                dayNumber: d,
                previousDays: nwPreviousDays,
                previousWeeks
            });

            dayResult.day.meals = (dayResult.day.meals || []).map(meal => ({
                ...meal,
                image_url: resolveMealPlanPhotoUrl(meal)
            }));
            nwGeneratedDays.push(dayResult.day);

            if (d === 0 && dayResult.weekMeta) {
                nwWeekMeta = dayResult.weekMeta;
            }

            const donePct = 5 + Math.round(((d + 1) / 7) * 65);
            if (statusEl) statusEl.textContent = `Week ${nextWeekNum} — Day ${d + 1} — ${nwDayLabels[d]} complete ✓`;
            if (progressEl) progressEl.style.width = `${donePct}%`;
        }

        // Assemble the week from individual days
        const newWeekData = {
            week_number: nextWeekNum,
            theme: nwWeekMeta?.theme || `Week ${nextWeekNum}`,
            theme_description: nwWeekMeta?.theme_description || '',
            days: nwGeneratedDays
        };

        // Add the new week to the cache
        _aiMealPlanCache.weeks.push(newWeekData);

        if (statusEl) statusEl.textContent = `Week ${nextWeekNum} — All 7 days ready! Saving...`;
        if (progressEl) progressEl.style.width = '75%';

        // Save to Supabase
        const planId = _aiMealPlanCache.id;
        if (planId) {
            try {
                // Insert week theme
                await window.supabaseClient.from('ai_meal_plan_weeks').insert({
                    plan_id: planId,
                    week_number: newWeekData.week_number,
                    theme: newWeekData.theme || `Week ${nextWeekNum}`,
                    theme_description: newWeekData.theme_description || ''
                });

                // Insert meals
                const newMeals = [];
                (newWeekData.days || []).forEach(day => {
                    (day.meals || []).forEach(meal => {
                        newMeals.push({
                            plan_id: planId,
                            week_number: newWeekData.week_number,
                            day_of_week: day.day_of_week,
                            day_name: day.day_name || ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][day.day_of_week],
                            meal_slot: meal.meal_slot, meal_time: meal.meal_time,
                            name: meal.name, description: meal.description,
                            calories: meal.calories, protein_g: meal.protein_g,
                            carbs_g: meal.carbs_g, fat_g: meal.fat_g, fiber_g: meal.fiber_g,
                            ingredients: meal.ingredients || [], preparation: meal.preparation,
                            prep_time_mins: meal.prep_time_mins, cook_time_mins: meal.cook_time_mins,
                            tags: meal.tags || [], cuisine: meal.cuisine, image_url: resolveMealPlanPhotoUrl(meal)
                        });
                    });
                });

                const { data: inserted } = await window.supabaseClient
                    .from('ai_generated_meals').insert(newMeals)
                    .select('id, name, description, meal_slot, week_number, day_of_week');

                const insertedByPosition = new Map((inserted || []).map(row => [
                    `${row.week_number}:${row.day_of_week}:${row.meal_slot}`,
                    row.id
                ]));
                newWeekData.days.forEach(day => day.meals.forEach(meal => {
                    meal.id = insertedByPosition.get(`${newWeekData.week_number}:${day.day_of_week}:${meal.meal_slot}`) || meal.id;
                }));

                if (statusEl) statusEl.textContent = `Week ${nextWeekNum} â€” Creating photos that match each meal...`;
                await ensureExactMealPlanPhotos({ id: planId, weeks: [newWeekData] }, user.id, {
                    onProgress: (done, total) => {
                        if (statusEl) statusEl.textContent = `Week ${nextWeekNum} â€” Creating meal photos ${done} of ${total}...`;
                        if (progressEl) progressEl.style.width = `${75 + Math.round((done / Math.max(total, 1)) * 23)}%`;
                    }
                });
            } catch (e) {
                console.warn('Could not save new week to Supabase:', e);
            }
        }

        // Update localStorage
        localStorage.setItem('ai_meal_plan', JSON.stringify(_aiMealPlanCache));

        if (progressEl) progressEl.style.width = '100%';
        if (statusEl) statusEl.textContent = `Week ${nextWeekNum} is ready!`;

        // Switch to the new week
        _aiMealPlanCurrentWeek = nextWeekNum;
        _aiMealPlanCurrentDay = 0;
        setTimeout(() => showAiPlanLoaded(_aiMealPlanCache), 500);

        notifyMealPlanReady(user.id, nextWeekNum);

    } catch (err) {
        console.error('Next week generation error:', err);
        if (statusEl) statusEl.textContent = 'Something went wrong. Please try again.';
        setTimeout(() => showAiPlanLoaded(_aiMealPlanCache), 2000);
    }
}

// Initialize meal plan view when meals tab is opened
// This is called from switchAppTab when 'meals' is selected

// Add stars to cycle sync meals in static week views
function markCycleSyncMeals() {
    if (!window.cycleSyncMealTitle) return;

    // Find all meal titles in the currently active week view
    const activeSection = document.querySelector('#meals-content-container .view-section.active');
    if (!activeSection) return;

    // Skip Today view (it handles stars in renderTodayMeals)
    if (activeSection.id === 'today' || activeSection.id === 'calorie-tracker') return;

    const mealTitles = activeSection.querySelectorAll('.meal-title');
    mealTitles.forEach(titleEl => {
        const originalText = titleEl.textContent.replace('⭐ ', '').trim();
        if (originalText === window.cycleSyncMealTitle && !titleEl.textContent.startsWith('⭐')) {
            titleEl.textContent = '⭐ ' + originalText;
        }
    });
}

async function renderTodayMeals() {
    const container = document.getElementById('today-meals-content');
    if (!container) return;

    // 1. Calculate Day
    let startDate = localStorage.getItem('pbb_start_date');
    if (!startDate) {
        // Initialize program date if not set
        await initProgramDate();
        startDate = localStorage.getItem('pbb_start_date');
        if (!startDate) {
            container.innerHTML = `<div style="text-align:center; padding:40px; color:var(--text-muted);">
                <p>Unable to determine your program start date. Please try refreshing the page.</p>
            </div>`;
            return;
        }
    }

    const start = new Date(startDate);
    const now = new Date();
    const diffTime = Math.abs(now - start);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    let currentDayNum = diffDays || 1;
    if (currentDayNum > 28) currentDayNum = 28; // Cap at 28

    const weekNum = Math.ceil(currentDayNum / 7);
    const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const dayIndex = (currentDayNum - 1) % 7; // Calculate which day in the program cycle (0-6)
    const dayName = days[dayIndex];
    
    const targetDayId = `week${weekNum}-${dayName}`;
    const sourceSection = document.getElementById(targetDayId);

    if (!sourceSection) {
        container.innerHTML = `<div style="text-align:center; padding:40px; color:var(--text-muted);">
            <p>Your meal plan for ${dayName} (Week ${weekNum}) couldn't be found. Please check the full plan.</p>
        </div>`;
        return;
    }

    // 2. Clone and Clean Cards
    container.innerHTML = ''; // Clear loading state
    
    // Add Header
    const header = document.createElement('div');
    header.className = 'today-menu-header';
    header.innerHTML = `<h2>Today's Menu</h2>
                       <p>DAY ${currentDayNum}</p>`;
    container.appendChild(header);

    // 1.5 Personalized Meal Recommendation Banner REMOVED per user request
    // The green bar was appearing empty or unwanted.

    const cards = sourceSection.querySelectorAll('.card');

    cards.forEach(card => {
        if (card.classList.contains('reflection-card')) return;

        const clone = card.cloneNode(true);

        // Check if this meal matches the Cycle Sync meal
        if (window.cycleSyncMealTitle) {
            const mealTitleElement = clone.querySelector('.meal-title');
            if (mealTitleElement && mealTitleElement.textContent.trim() === window.cycleSyncMealTitle) {
                mealTitleElement.textContent = '⭐ ' + mealTitleElement.textContent;
            }
        }

        // Ensure images open the modal
        clone.querySelectorAll('img').forEach(img => {
            img.onclick = function() {
                // Check if openImageModal or similar exists
                if (typeof openImageModal === 'function') {
                    openImageModal(this.src);
                } else {
                    // Fallback to simple alert or nothing if not found
                    console.log("Image modal function not found");
                }
            };
        });
        container.appendChild(clone);
    });

    // 3. Add Reflection at the bottom
    const reflection = sourceSection.querySelector('.reflection-card');
    if (reflection) {
        const rfClone = reflection.cloneNode(true);
        const textarea = rfClone.querySelector('textarea');
        if (textarea) {
            const originalId = textarea.id; // e.g., ref-week1-Monday
            
            // Ensure the clone's save button works correctly
            const btn = rfClone.querySelector('button');
            const idParts = originalId.split('-');
            if (idParts.length >= 3) {
                const weekDayId = idParts[1] + '-' + idParts[2];
                if (btn) {
                    btn.onclick = function() {
                        saveDayReflection(weekDayId);
                    };
                }
            }
            
            // Mirror textarea value
            textarea.id = 'today-' + originalId;
            textarea.oninput = function() {
                const originalTextarea = document.getElementById(originalId);
                if (originalTextarea) originalTextarea.value = this.value;
            };
        }

        container.appendChild(rfClone);
    }
}

function switchDay(weekId, dayId) {
    const context = document.getElementById(weekId);
    if(!context) return;
    
    context.querySelectorAll('.day-view').forEach(el => el.classList.remove('active'));
    context.querySelectorAll('.sub-nav .sub-btn').forEach(el => el.classList.remove('active'));
    
    // Activating
    const targetId = weekId + '-' + dayId;
    const targetEl = document.getElementById(targetId);
    if(targetEl) targetEl.classList.add('active');
    
    // Highlight sub btn
    const btns = context.querySelectorAll('.sub-nav .sub-btn');
    for(let b of btns) {
        const btnText = b.innerText.toLowerCase();
        const dId = dayId.toLowerCase();
        
        if (btnText === dId || 
           (dId === 'overview' && btnText === 'overview') || 
           (dId !== 'overview' && btnText.startsWith(dId.substring(0,3)))) {
            b.classList.add('active');
        }
    }
    
    // Re-apply badges if available
    if (window.applyMealBadges) window.applyMealBadges();
}

// Backward compatibility if internal links use switchView
function switchView(id) {
    switchWeek(id);
}

// --- NATIVE PERMISSIONS REQUEST FLOW ---
// On first login in a native app (iOS/Android), request Notifications first
// (drives re-engagement via coach DMs, meal reminders, FitGotchi pings), then
// Camera, Microphone, and Health Data via native OS dialogs. Location is NOT
// asked upfront — features that need it (weather etc.) ask lazily when opened.

function isNativeApp() {
    return !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
}

/**
 * Request all native permissions sequentially via native OS dialogs.
 * Only runs on first install (guarded by localStorage flag).
 */
let balancePermissionContinue = null;

function setBalancePermissionStatus(id, text, state) {
    const el = document.getElementById('balance-permission-' + id);
    if (!el) return;
    el.textContent = text;
    el.dataset.state = state || '';
}

function balancePermissionStorageKey(name) {
    const userId = window.currentUser && window.currentUser.id ? window.currentUser.id : 'signed-in-user';
    return name + ':' + userId;
}

async function showNativePermissionsModal(options) {
    if (window.guestMode) return false;
    const opts = options && typeof options === 'object' ? options : {};
    if (typeof opts.onComplete === 'function') balancePermissionContinue = opts.onComplete;
    const requestedKey = balancePermissionStorageKey('native_permissions_requested');
    if (localStorage.getItem(requestedKey) === 'true') {
        const next = balancePermissionContinue;
        balancePermissionContinue = null;
        if (typeof next === 'function') next();
        return false;
    }
    await requestBalanceEssentialPermissions();
    return true;
}

async function requestBalanceEssentialPermissions() {
    const primary = document.querySelector('#balance-permission-setup .balance-permission-primary');
    if (primary) { primary.disabled = true; primary.textContent = 'Opening phone settings...'; }

    setBalancePermissionStatus('notifications', 'Requesting...', 'pending');
    try {
        if (isNativeApp() && window.NativePush && typeof window.NativePush.requestPermission === 'function') {
            const result = await window.NativePush.requestPermission();
            if (typeof window.NativePush.init === 'function') window.NativePush.init();
            setBalancePermissionStatus('notifications', result === 'denied' ? 'Not enabled' : 'Enabled', result === 'denied' ? 'denied' : 'granted');
        } else if (typeof requestNotificationPermission === 'function') {
            await requestNotificationPermission();
            const granted = !('Notification' in window) || Notification.permission === 'granted';
            setBalancePermissionStatus('notifications', granted ? 'Enabled' : 'Not enabled', granted ? 'granted' : 'denied');
        } else {
            setBalancePermissionStatus('notifications', 'Not available here', 'denied');
        }
    } catch (_) { setBalancePermissionStatus('notifications', 'Not enabled', 'denied'); }

    setBalancePermissionStatus('camera', 'Requesting...', 'pending');
    try {
        if (window.NativePermissions && typeof window.NativePermissions.hasCameraPermission === 'function') {
            let granted = window.NativePermissions.hasCameraPermission();
            if (!granted && typeof window.NativePermissions.requestCameraPermission === 'function') {
                granted = await new Promise(resolve => {
                    let done = false;
                    window._onNativeCameraPermission = ok => { if (!done) { done = true; window._onNativeCameraPermission = null; resolve(!!ok); } };
                    window.NativePermissions.requestCameraPermission();
                    setTimeout(() => { if (!done) { done = true; resolve(false); } }, 30000);
                });
            }
            setBalancePermissionStatus('camera', granted ? 'Enabled' : 'Not enabled', granted ? 'granted' : 'denied');
        } else {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
            stream.getTracks().forEach(track => track.stop());
            setBalancePermissionStatus('camera', 'Enabled', 'granted');
        }
    } catch (_) { setBalancePermissionStatus('camera', 'Not enabled', 'denied'); }

    setBalancePermissionStatus('microphone', 'Requesting...', 'pending');
    try {
        if (window.NativePermissions && typeof window.NativePermissions.hasMicrophonePermission === 'function') {
            let granted = window.NativePermissions.hasMicrophonePermission();
            if (!granted && typeof window.NativePermissions.requestMicrophonePermission === 'function') {
                granted = await new Promise(resolve => {
                    let done = false;
                    window._onNativeMicrophonePermission = ok => { if (!done) { done = true; window._onNativeMicrophonePermission = null; resolve(!!ok); } };
                    window.NativePermissions.requestMicrophonePermission();
                    setTimeout(() => { if (!done) { done = true; resolve(false); } }, 30000);
                });
            }
            setBalancePermissionStatus('microphone', granted ? 'Enabled' : 'Not enabled', granted ? 'granted' : 'denied');
        } else {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
            stream.getTracks().forEach(track => track.stop());
            setBalancePermissionStatus('microphone', 'Enabled', 'granted');
        }
    } catch (_) { setBalancePermissionStatus('microphone', 'Not enabled', 'denied'); }

    localStorage.setItem(balancePermissionStorageKey('native_permissions_requested'), 'true');
    localStorage.setItem(balancePermissionStorageKey('native_permissions_requested_at'), String(Date.now()));
    setTimeout(() => finishBalancePermissionSetup(true), 500);
}

function finishBalancePermissionSetup(requested) {
    localStorage.setItem(balancePermissionStorageKey('balance_permission_setup_seen'), 'true');
    const next = balancePermissionContinue;
    balancePermissionContinue = null;
    if (typeof next === 'function') setTimeout(next, 180);
}

/**
 * Open the device's notification settings so the user can enable/disable
 * push notifications for this app at any time.
 */
// Ask each signed-in account once. Permission state is account-scoped so a
// second client on the same test phone/browser never inherits another
// client's completed prompt sequence.
window.addEventListener('pbbInitComplete', function requestPermissionsAfterLogin() {
    let attempts = 0;
    const requestWhenReady = function () {
        if (window.currentUser && window.currentUser.id) {
            showNativePermissionsModal();
            return;
        }
        attempts += 1;
        if (attempts < 30) setTimeout(requestWhenReady, 250);
    };
    setTimeout(requestWhenReady, 700);
}, { once: true });

async function openAppNotificationSettings() {
    let openedNativeSettings = false;
    if (window.NativePermissions && typeof window.NativePermissions.openNotificationSettings === 'function') {
        await Promise.resolve(window.NativePermissions.openNotificationSettings()).catch(() => {});
        openedNativeSettings = true;
    } else if (window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) {
        let AppPlugin = window.Capacitor.Plugins && window.Capacitor.Plugins.App;
        if (!AppPlugin && typeof window.Capacitor.registerPlugin === 'function') {
            try { AppPlugin = window.Capacitor.registerPlugin('App'); } catch (e) {}
        }
        if (AppPlugin && typeof AppPlugin.openUrl === 'function') {
            await AppPlugin.openUrl({ url: 'app-settings:' }).catch(() => {});
            openedNativeSettings = true;
        }
    }

    if (!openedNativeSettings && 'Notification' in window) {
        if (Notification.permission === 'default') {
            const permission = await Notification.requestPermission();
            if (typeof showToast === 'function') {
                showToast(permission === 'granted' ? 'Notifications enabled' : 'Notifications were not enabled', permission === 'granted' ? 'success' : 'info');
            }
        } else if (Notification.permission === 'granted') {
            if (typeof showToast === 'function') showToast('Notifications are enabled', 'success');
        } else if (typeof showToast === 'function') {
            showToast('Notifications are blocked in your browser settings.', 'error');
        } else {
            alert('Notifications are blocked. Open this site in your browser settings to enable them.');
        }
    } else if (!openedNativeSettings) {
        if (typeof showToast === 'function') showToast('Notifications are not available in this browser.', 'info');
    }
    // After returning from settings, refresh the status display
    setTimeout(updatePushNotifSettingsUI, openedNativeSettings ? 1500 : 100);
}

/**
 * Force a fresh FCM token fetch + re-save to Supabase. The on-launch token
 * registration retries 30 times over 60s and then gives up; reinstalling the
 * app combined with a slow login can leave the token unsaved until the next
 * app resume. This button gives users (and admins) a one-tap escape hatch.
 */
async function refreshPushRegistration() {
    const statusEl = document.getElementById('push-notif-refresh-status');
    const btn = document.getElementById('push-notif-refresh-btn');
    if (!btn) return;
    const setStatus = (msg, color) => {
        if (statusEl) {
            statusEl.textContent = msg;
            if (color) statusEl.style.color = color;
        }
    };

    if (!window.NativePush || typeof window.NativePush.forceRefreshAndRegister !== 'function') {
        setStatus('Push refresh unavailable in this build.', '#991b1b');
        return;
    }
    if (!window.NativePush.isNativeApp || !window.NativePush.isNativeApp()) {
        setStatus('Open the installed app to refresh push.', '#991b1b');
        return;
    }
    if (!window.currentUser) {
        setStatus('Sign in first, then tap Refresh.', '#991b1b');
        return;
    }

    btn.disabled = true;
    const originalLabel = btn.textContent;
    btn.textContent = 'Refreshing…';
    setStatus('Refreshing push token…', 'var(--text-muted)');
    try {
        const result = await window.NativePush.forceRefreshAndRegister();
        if (result && result.ok) {
            setStatus('Push notifications refreshed — you should now receive alerts.', '#166534');
        } else {
            const reason = (result && (result.reason || result.status)) || 'unknown';
            setStatus('Refresh failed: ' + reason + '. Tap Manage and confirm notifications are enabled.', '#991b1b');
        }
    } catch (err) {
        setStatus('Refresh error: ' + ((err && err.message) || err), '#991b1b');
    } finally {
        btn.disabled = false;
        btn.textContent = originalLabel;
    }
}

/**
 * Update the Push Notifications settings row to reflect current permission state.
 */
function updatePushNotifSettingsUI() {
    const statusEl = document.getElementById('push-notif-settings-status');
    const btn = document.getElementById('push-notif-settings-btn');
    if (!statusEl || !btn) return;

    const granted = window.NativePermissions && typeof window.NativePermissions.hasNotificationPermission === 'function'
        ? window.NativePermissions.hasNotificationPermission()
        : (window.Notification && Notification.permission === 'granted');

    statusEl.style.display = 'block';

    if (granted) {
        statusEl.textContent = 'Enabled: coach messages and reminders';
        statusEl.style.color = '#166534';
        btn.textContent = 'Manage';
        btn.style.background = 'var(--primary)';
    } else {
        statusEl.textContent = 'Disabled: tap Manage to enable in settings';
        statusEl.style.color = '#991b1b';
        btn.textContent = 'Enable';
        btn.style.background = '#dc2626';
    }
}

const PUSH_PERMISSION_REMINDER_DELAY_MS = 24 * 60 * 60 * 1000;
const PUSH_PERMISSION_REMINDER_SHORT_CADENCE_MS = 4 * 24 * 60 * 60 * 1000;
const PUSH_PERMISSION_REMINDER_LONG_CADENCE_MS = 14 * 24 * 60 * 60 * 1000;
const PUSH_PERMISSION_REMINDER_DISMISS_MS = 7 * 24 * 60 * 60 * 1000;

function isNativeMobileAppForPushReminder() {
    if (!(typeof isNativeApp === 'function' && isNativeApp())) return false;
    try {
        if (window.Capacitor && typeof window.Capacitor.getPlatform === 'function') {
            const platform = window.Capacitor.getPlatform();
            if (platform !== 'android' && platform !== 'ios') return false;
        }
    } catch (e) {}
    return !!(window.NativePush
        && typeof window.NativePush.checkPermission === 'function'
        && typeof window.NativePush.requestPermission === 'function');
}

function getPushPermissionReminderKey(name) {
    const userId = window.currentUser && window.currentUser.id ? window.currentUser.id : 'anon';
    return 'pbb_push_permission_reminder_' + name + ':' + userId;
}

function getPushPermissionReminderNumber(name) {
    try {
        const value = Number(localStorage.getItem(getPushPermissionReminderKey(name)) || '0');
        return Number.isFinite(value) ? value : 0;
    } catch (e) {
        return 0;
    }
}

function setPushPermissionReminderNumber(name, value) {
    try {
        localStorage.setItem(getPushPermissionReminderKey(name), String(value));
    } catch (e) {}
}

function clearPushPermissionReminderState() {
    ['lastShownAt', 'snoozedUntil', 'shownCount'].forEach(function(name) {
        try { localStorage.removeItem(getPushPermissionReminderKey(name)); } catch (e) {}
    });
}

function hidePushPermissionReminder() {
    const existing = document.getElementById('push-permission-reminder');
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
}

function dismissPushPermissionReminder(snoozeMs) {
    hidePushPermissionReminder();
    if (snoozeMs) {
        setPushPermissionReminderNumber('snoozedUntil', Date.now() + snoozeMs);
    }
}

function isPushPermissionReminderBlocked() {
    if (window.guestMode || !window.currentUser || window._onboardingWizardPending) return true;
    const blockingIds = ['onboarding-wizard', 'native-permissions-modal', 'guest-signup-modal', 'weekly-goals-modal', 'store-review-modal'];
    return blockingIds.some(function(id) {
        const el = document.getElementById(id);
        if (!el) return false;
        const style = window.getComputedStyle ? window.getComputedStyle(el) : null;
        return style && style.display !== 'none' && style.visibility !== 'hidden' && Number(style.opacity || '1') !== 0;
    });
}

async function getCurrentPushPermissionStatus() {
    try {
        if (window.NativePush && typeof window.NativePush.checkPermission === 'function') {
            return await window.NativePush.checkPermission();
        }
        if (window.NativePermissions && typeof window.NativePermissions.hasNotificationPermission === 'function') {
            return window.NativePermissions.hasNotificationPermission() ? 'granted' : 'denied';
        }
        if (window.Notification) return Notification.permission;
    } catch (e) {
        console.warn('[PushReminder] Could not check notification permission:', e);
    }
    return 'error';
}

function showPushPermissionReminder() {
    hidePushPermissionReminder();

    const now = Date.now();
    const shownCount = getPushPermissionReminderNumber('shownCount');
    setPushPermissionReminderNumber('lastShownAt', now);
    setPushPermissionReminderNumber('shownCount', shownCount + 1);

    const banner = document.createElement('div');
    banner.id = 'push-permission-reminder';
    banner.setAttribute('role', 'status');
    banner.style.cssText = 'position:fixed;left:12px;right:12px;bottom:calc(78px + env(safe-area-inset-bottom, 0px));z-index:12020;max-width:520px;margin:0 auto;background:#ffffff;color:#172033;border:1px solid #cfe7d4;border-radius:8px;box-shadow:0 10px 30px rgba(15,23,42,0.14);padding:12px;display:flex;gap:12px;align-items:flex-start;box-sizing:border-box;';
    banner.innerHTML = ''
        + '<div aria-hidden="true" style="flex:0 0 32px;width:32px;height:32px;border-radius:8px;background:#edf7ef;color:#2f7d46;display:flex;align-items:center;justify-content:center;">'
        + '<svg viewBox="0 0 24 24" style="width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"></path><path d="M13.73 21a2 2 0 0 1-3.46 0"></path></svg>'
        + '</div>'
        + '<div style="flex:1;min-width:0;">'
        + '<div style="font-size:0.95rem;font-weight:800;line-height:1.2;margin:0 0 3px;color:#172033;">Turn on Balance notifications</div>'
        + '<div style="font-size:0.82rem;line-height:1.35;color:#475569;margin:0 0 10px;">Coach replies, reminders and streak nudges can reach you when the app is closed.</div>'
        + '<div style="display:flex;gap:8px;justify-content:flex-end;align-items:center;">'
        + '<button type="button" data-pbb-push-later style="border:1px solid #dbe5dd;background:#ffffff;color:#475569;border-radius:8px;padding:8px 10px;font-size:0.82rem;font-weight:700;">Later</button>'
        + '<button type="button" data-pbb-push-enable style="border:none;background:var(--primary, #7ba883);color:#ffffff;border-radius:8px;padding:8px 12px;font-size:0.82rem;font-weight:800;">Turn on</button>'
        + '</div>'
        + '</div>';

    const laterBtn = banner.querySelector('[data-pbb-push-later]');
    const enableBtn = banner.querySelector('[data-pbb-push-enable]');

    if (laterBtn) {
        laterBtn.addEventListener('click', function() {
            dismissPushPermissionReminder(PUSH_PERMISSION_REMINDER_DISMISS_MS);
        });
    }

    if (enableBtn) {
        enableBtn.addEventListener('click', async function() {
            enableBtn.disabled = true;
            enableBtn.textContent = 'Opening';
            setPushPermissionReminderNumber('snoozedUntil', Date.now() + PUSH_PERMISSION_REMINDER_DISMISS_MS);

            try {
                const needsSettings = window.NativePermissions
                    && typeof window.NativePermissions.isNotificationPermPermanentlyDenied === 'function'
                    && window.NativePermissions.isNotificationPermPermanentlyDenied();
                let result = needsSettings ? 'denied' : 'error';

                if (!needsSettings && window.NativePush && typeof window.NativePush.requestPermission === 'function') {
                    result = await window.NativePush.requestPermission();
                }

                if (result === 'granted') {
                    clearPushPermissionReminderState();
                    hidePushPermissionReminder();
                    updatePushNotifSettingsUI();
                    if (window.NativePush && typeof window.NativePush.init === 'function') {
                        try { window.NativePush.init(); } catch (e) {}
                    }
                    if (typeof showToast === 'function') showToast('Notifications are on', 'success');
                    return;
                }

                if (typeof openAppNotificationSettings === 'function') {
                    openAppNotificationSettings();
                }
            } catch (e) {
                console.warn('[PushReminder] Enable action failed:', e);
                if (typeof openAppNotificationSettings === 'function') {
                    openAppNotificationSettings();
                }
            } finally {
                setTimeout(function() {
                    if (enableBtn && document.body.contains(enableBtn)) {
                        enableBtn.disabled = false;
                        enableBtn.textContent = 'Turn on';
                    }
                }, 1200);
            }
        });
    }

    if (document.body) document.body.appendChild(banner);
}

async function maybeShowPushPermissionReminder() {
    if (window._pushPermissionReminderChecking) return;
    if (!isNativeMobileAppForPushReminder()) return;
    if (isPushPermissionReminderBlocked()) return;
    if (!localStorage.getItem('native_permissions_requested')) return;

    const requestedAt = Number(localStorage.getItem('native_permissions_requested_at') || '0');
    const now = Date.now();
    if (requestedAt && now - requestedAt < PUSH_PERMISSION_REMINDER_DELAY_MS) return;

    window._pushPermissionReminderChecking = true;
    try {
        const status = await getCurrentPushPermissionStatus();
        if (status === 'granted') {
            clearPushPermissionReminderState();
            hidePushPermissionReminder();
            return;
        }
        if (status === 'unsupported' || status === 'error') return;

        const snoozedUntil = getPushPermissionReminderNumber('snoozedUntil');
        if (snoozedUntil && now < snoozedUntil) return;

        const shownCount = getPushPermissionReminderNumber('shownCount');
        const cadence = shownCount >= 3 ? PUSH_PERMISSION_REMINDER_LONG_CADENCE_MS : PUSH_PERMISSION_REMINDER_SHORT_CADENCE_MS;
        const lastShownAt = getPushPermissionReminderNumber('lastShownAt');
        if (lastShownAt && now - lastShownAt < cadence) return;

        showPushPermissionReminder();
    } finally {
        window._pushPermissionReminderChecking = false;
    }
}

function initPushPermissionReminder() {
    if (window._pushPermissionReminderInitialized) return;
    window._pushPermissionReminderInitialized = true;

    const previousPermissionRecheck = typeof window._onPermissionRecheck === 'function'
        ? window._onPermissionRecheck
        : null;
    window._onPermissionRecheck = function(granted) {
        if (previousPermissionRecheck) {
            try { previousPermissionRecheck(granted); } catch (e) {}
        }
        updatePushNotifSettingsUI();
        if (granted) {
            clearPushPermissionReminderState();
            hidePushPermissionReminder();
            if (window.NativePush && typeof window.NativePush.init === 'function') {
                try { window.NativePush.init(); } catch (e) {}
            }
        } else {
            setTimeout(maybeShowPushPermissionReminder, 1500);
        }
    };

    setTimeout(maybeShowPushPermissionReminder, 9000);
    window.addEventListener('pbbInitComplete', function() {
        setTimeout(maybeShowPushPermissionReminder, 3500);
    });
    document.addEventListener('visibilitychange', function() {
        if (document.visibilityState === 'visible') {
            setTimeout(function() {
                updatePushNotifSettingsUI();
                maybeShowPushPermissionReminder();
            }, 1200);
        }
    });
}

window.maybeShowPushPermissionReminder = maybeShowPushPermissionReminder;
_onDomReady(initPushPermissionReminder);

