function setOnboardingScrollLock(locked) {
    try {
        document.documentElement.classList.toggle('pbb-onboarding-locked', !!locked);
        document.body.classList.toggle('pbb-onboarding-locked', !!locked);
    } catch (e) {}
}

function closeOnboardingBlockingSurfaces() {
    [
        'health-connect-modal',
        'native-permissions-modal',
        'guest-signup-modal',
        'weekly-goals-modal',
        'store-review-modal'
    ].forEach(function(id) {
        const el = document.getElementById(id);
        if (!el) return;
        el.style.display = 'none';
        el.classList.remove('active', 'visible', 'show');
    });
}

function isTransferredWizardClient() {
    const profile = window.currentUserProfile || window.userProfile || window.profileData || {};
    return !!(profile.is_transferred_client || window.__pbbTransferredSetupPending);
}

function isWizardSlideSkipped(step) {
    // Cycle alignment is relevant only when the member explicitly chose "For her".
    // Keep this rule here so forward, back, and resumed onboarding paths all agree.
    if (step === 3 && normalizeGenderValue(selectedGender) !== 'female') return true;
    if (step === 4 && isTransferredWizardClient()) return true;
    if (wizardAssignedProgram && [4, 5, 6].includes(step)) return true;
    if (step === 17 && window._wizardCustomizeOnlyMode) return false;
    if (skippedWizardSlides.includes(step)) return true;
    return step === 17 && !window._wizardCustomizeOnlyMode &&
        typeof window.isFitGotchiHidden === 'function' && window.isFitGotchiHidden();
}

function normalizeWizardStep() {
    while (isWizardSlideSkipped(currentWizardStep) && currentWizardStep < finalWizardStep) {
        currentWizardStep++;
    }
    if (isWizardSlideSkipped(currentWizardStep)) {
        currentWizardStep = finalWizardStep;
    }
}

// Wizard-specific validation/info message (renders above the z-index:12000 wizard overlay)
function wizardAlert(message, type = 'error') {
    const existing = document.getElementById('wizard-validation-toast');
    if (existing) existing.remove();

    const colors = { error: '#ef4444', success: '#22c55e', info: '#3b82f6' };
    const bg = colors[type] || colors.error;

    const toast = document.createElement('div');
    toast.id = 'wizard-validation-toast';
    toast.style.cssText = 'position:fixed; top:20px; left:50%; transform:translateX(-50%); padding:12px 24px; background:' + bg + '; color:white; border-radius:12px; font-weight:600; font-size:0.9rem; box-shadow:0 4px 20px rgba(0,0,0,0.3); z-index:14000; text-align:center; max-width:90vw; animation:fadeInUp 0.3s ease-out;';
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(() => {
        if (toast.parentNode) {
            toast.style.opacity = '0';
            toast.style.transition = 'opacity 0.3s';
            setTimeout(() => toast.remove(), 300);
        }
    }, 3000);
}

function wizardValidationError(message, fieldId) {
    wizardAlert(message);
    if (fieldId) focusWizardField(document.getElementById(fieldId));
}

function isFocusableWizardField(field) {
    if (!field || field.disabled) return false;
    if (field.type === 'hidden' || field.type === 'file') return false;
    if (field.offsetParent === null) return false;
    return true;
}

function focusWizardField(field) {
    if (!isFocusableWizardField(field) || typeof field.focus !== 'function') return false;

    const focusNow = () => {
        try {
            field.focus({ preventScroll: true });
        } catch (e) {
            try { field.focus(); } catch (_) {}
        }
        if (typeof field.setSelectionRange === 'function') {
            const end = String(field.value || '').length;
            try { field.setSelectionRange(end, end); } catch (e) {}
        }
    };

    focusNow();
    requestAnimationFrame(focusNow);
    setTimeout(focusNow, 80);
    return true;
}

function getCurrentWizardSlide() {
    return document.querySelector('#onboarding-wizard .wizard-slide.slide-active');
}

function getVisibleWizardFields(slide) {
    return Array.from((slide || getCurrentWizardSlide())?.querySelectorAll('input.wizard-input, textarea.wizard-input, select.wizard-input') || [])
        .filter(field => isFocusableWizardField(field) && field.type !== 'date');
}

function getVisibleWizardTextFields(slide) {
    return getVisibleWizardFields(slide).filter(field => field.matches('input.wizard-input, textarea.wizard-input'));
}

function focusNextWizardField(currentField) {
    const fields = getVisibleWizardFields();
    const index = fields.indexOf(currentField);
    const nextField = index >= 0 ? fields[index + 1] : fields[0];
    return focusWizardField(nextField);
}

function initWizardKeyboardFlow() {
    const wizard = document.getElementById('onboarding-wizard');
    if (!wizard || wizard.dataset.keyboardFlowReady === 'true') return;
    wizard.dataset.keyboardFlowReady = 'true';

    wizard.querySelectorAll('input.wizard-input, textarea.wizard-input').forEach(field => {
        if (field.type !== 'date') field.setAttribute('enterkeyhint', 'next');
    });

    wizard.addEventListener('keydown', event => {
        const field = event.target;
        if (event.key !== 'Enter' || !field || !field.matches('input.wizard-input, textarea.wizard-input')) return;
        if (field.tagName === 'TEXTAREA' && event.shiftKey) return;
        if (field.type === 'date') return;

        event.preventDefault();
        if (focusNextWizardField(field)) return;
        const stepBefore = currentWizardStep;
        wizardNext();
        setTimeout(() => {
            if (currentWizardStep !== stepBefore) {
                focusWizardField(getVisibleWizardTextFields()[0]);
            }
        }, 90);
    });
}

