function deriveWizardGoalBodyType(goalIntentIds) {
    const ids = Array.isArray(goalIntentIds) ? goalIntentIds : [];
    const primary = ids[0] || '';
    if (primary === 'lose_weight') return 'Flat';
    if (primary === 'build_strength' || primary === 'hit_protein') return 'Body Builder';
    if (ids.includes('lose_weight')) return 'Flat';
    if (ids.includes('build_strength') || ids.includes('hit_protein')) return 'Body Builder';
    return 'Athletic';
}

function inferWizardStarterPlan(answers = {}) {
    const outcome = normalizeWizardChatText(answers.why_now || '');
    const blocker = normalizeWizardChatText(answers.main_blocker || '');
    const combined = `${outcome} ${blocker}`.trim();
    const containsAny = words => words.some(word => combined.includes(normalizeWizardChatText(word)));
    const goalIntentIds = ['consistent_workouts'];

    if (containsAny(['lose weight', 'weight loss', 'lose fat', 'body fat', 'fat loss', 'drop fat', 'lean', 'drop weight', 'smaller'])) {
        goalIntentIds.unshift('lose_weight');
    } else if (containsAny(['strong', 'strength', 'muscle', 'tone', 'toned', 'build'])) {
        goalIntentIds.unshift('build_strength');
    } else if (containsAny(['food', 'nutrition', 'eat better', 'meal', 'protein'])) {
        goalIntentIds.unshift('improve_nutrition');
    } else if (answers.energy_level === 'low' || containsAny(['energy', 'tired', 'sleep', 'exhausted'])) {
        goalIntentIds.unshift('more_energy');
    }

    const weeklyGoalFocusIds = ['complete_workouts'];
    if (isTransferredWizardClient()) {
        weeklyGoalFocusIds.push('meal_log_days', 'sleep_7h_nights');
    } else {
        weeklyGoalFocusIds.push('protein_days');
        if (goalIntentIds.includes('lose_weight') || goalIntentIds.includes('improve_nutrition')) {
            weeklyGoalFocusIds.push('meal_log_days');
        } else if (goalIntentIds.includes('more_energy') || answers.energy_level === 'low') {
            weeklyGoalFocusIds.push('sleep_7h_nights');
        } else {
            weeklyGoalFocusIds.push('water_goal_days');
        }
    }

    const learningInterestIds = ['behavior_change_science', 'workout_motivation', 'plant_based_cooking'];
    if (goalIntentIds.includes('lose_weight')) learningInterestIds.push('fat_loss_basics');
    else if (goalIntentIds.includes('build_strength')) learningInterestIds.push('muscle_gain_basics');
    else if (goalIntentIds.includes('improve_nutrition')) learningInterestIds.push('protein_science');
    else if (goalIntentIds.includes('more_energy')) learningInterestIds.push('recovery_sleep_energy');

    let starterSessionMinutes = answers.energy_level === 'low' ? 20 : 30;

    return {
        goalIntentIds: Array.from(new Set(goalIntentIds)).slice(0, 2),
        weeklyGoalFocusIds,
        learningInterestIds: Array.from(new Set(learningInterestIds)),
        goalBodyType: deriveWizardGoalBodyType(goalIntentIds),
        starterSessionMinutes
    };
}

function wizardPrefersImperialUnits() {
    try {
        return localStorage.getItem('weightUnitPreference') === 'lbs';
    } catch (e) {
        return false;
    }
}

function roundWizardMetric(value, decimals = 1) {
    const factor = Math.pow(10, decimals);
    return Math.round(Number(value) * factor) / factor;
}

function formatWizardNumber(value, decimals = 1) {
    const rounded = roundWizardMetric(value, decimals);
    return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(decimals);
}

function getWizardHeightQuestion() {
    return wizardPrefersImperialUnits()
        ? 'What is your height? You can use ft/in or cm.'
        : 'What is your height? You can use cm or ft/in.';
}

function getWizardHeightPlaceholder() {
    return wizardPrefersImperialUnits() ? 'e.g. 5 ft 8 or 173 cm' : 'e.g. 170 cm or 5 ft 7';
}

function getWizardWeightQuestion() {
    return wizardPrefersImperialUnits()
        ? 'What is your current weight? You can use lbs or kg.'
        : 'What is your current weight? You can use kg or lbs.';
}

function getWizardWeightPlaceholder() {
    return wizardPrefersImperialUnits() ? 'e.g. 150 lbs or 68 kg' : 'e.g. 72 kg or 159 lbs';
}

function getWizardGoalWeightQuestion() {
    const goalIntents = Array.isArray(wizardChatAnswers?.goal_intents) ? wizardChatAnswers.goal_intents : [];
    const wantsWeightLoss = goalIntents.includes('lose_weight');
    const base = wantsWeightLoss
        ? 'What target weight would feel like a realistic first marker?'
        : 'If weight loss is part of the goal, what target weight should Shannon keep in mind?';
    return wizardPrefersImperialUnits()
        ? `${base} You can use lbs or kg, or leave it blank.`
        : `${base} You can use kg or lbs, or leave it blank.`;
}

function getWizardGoalWeightPlaceholder() {
    return wizardPrefersImperialUnits() ? 'Optional: e.g. 140 lbs or 64 kg' : 'Optional: e.g. 67 kg or 148 lbs';
}

function parseWizardFeetInches(raw) {
    const text = String(raw || '').toLowerCase().replace(/[’′]/g, "'");
    const feetInches = text.match(/(\d+(?:\.\d+)?)\s*(?:'|ft|feet|foot)\s*(\d+(?:\.\d+)?)?\s*(?:"|in|inch|inches)?/);
    if (!feetInches) return null;
    const feet = Number(feetInches[1]);
    const inches = feetInches[2] == null ? 0 : Number(feetInches[2]);
    if (!Number.isFinite(feet) || !Number.isFinite(inches)) return null;
    return (feet * 12) + inches;
}

function parseWizardBareFeet(value, raw) {
    const number = Number(value);
    if (!Number.isFinite(number) || number <= 0 || number >= 9) return null;
    const text = String(raw || '').trim();
    if (text.includes('.')) {
        const parts = text.split('.');
        const feet = Number(parts[0]);
        const inches = Number(parts[1]);
        if (Number.isFinite(feet) && Number.isFinite(inches) && inches < 12) {
            return (feet * 12) + inches;
        }
    }
    return number * 12;
}

function parseWizardHeightInput(raw) {
    const text = String(raw || '').trim().toLowerCase();
    if (!text) return null;
    const explicitFeetInches = parseWizardFeetInches(text);
    if (explicitFeetInches != null) {
        const cm = explicitFeetInches * 2.54;
        return { value: roundWizardMetric(cm, 1), display: `${Math.floor(explicitFeetInches / 12)}' ${formatWizardNumber(explicitFeetInches % 12, 0)}"` };
    }

    const match = text.replace(/,/g, '.').match(/\d+(\.\d+)?/);
    if (!match) return null;
    const number = Number(match[0]);
    if (!Number.isFinite(number)) return null;

    const hasCm = /\bcm|centimet/.test(text);
    const hasInches = /\bin|inch|inches|"/.test(text);
    let cm;
    let display;

    if (hasCm || (!hasInches && !wizardPrefersImperialUnits() && number >= 100)) {
        cm = number;
        display = `${formatWizardNumber(number, 1)} cm`;
    } else if (hasInches || (number >= 48 && number <= 96)) {
        cm = number * 2.54;
        display = `${formatWizardNumber(number, 0)} in`;
    } else {
        const bareFeetInches = parseWizardBareFeet(number, text);
        if (bareFeetInches != null) {
            cm = bareFeetInches * 2.54;
            display = `${Math.floor(bareFeetInches / 12)}' ${formatWizardNumber(bareFeetInches % 12, 0)}"`;
        } else {
            cm = number;
            display = `${formatWizardNumber(number, 1)} cm`;
        }
    }

    if (!Number.isFinite(cm) || cm < 100 || cm > 250) return null;
    return { value: roundWizardMetric(cm, 1), display };
}

function parseWizardWeightInput(raw) {
    const text = String(raw || '').trim().toLowerCase();
    if (!text) return null;
    const match = text.replace(/,/g, '.').match(/\d+(\.\d+)?/);
    if (!match) return null;
    const number = Number(match[0]);
    if (!Number.isFinite(number)) return null;

    const hasKg = /\bkg|kilo|kilogram/.test(text);
    const hasLbs = /\blb|lbs|pound/.test(text);
    const useLbs = hasLbs || (!hasKg && wizardPrefersImperialUnits());
    const kg = useLbs ? number * 0.453592 : number;
    if (!Number.isFinite(kg) || kg < 30 || kg > 300) return null;
    return {
        value: roundWizardMetric(kg, 1),
        display: useLbs ? `${formatWizardNumber(number, 1)} lbs` : `${formatWizardNumber(kg, 1)} kg`
    };
}

function parseWizardMeasurementInput(step, raw) {
    if (step?.measurement === 'height') return parseWizardHeightInput(raw);
    if (step?.measurement === 'weight') return parseWizardWeightInput(raw);
    return null;
}

