function getWizardSelectedEquipment() {
    const legacySelectValue = document.getElementById('wizard-equipment')?.value;
    if (legacySelectValue) return legacySelectValue;

    try {
        const sessionProfile = JSON.parse(sessionStorage.getItem('userProfile') || '{}');
        if (sessionProfile.equipment_access) return sessionProfile.equipment_access;
    } catch (e) {}

    try {
        const localProfile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        if (localProfile.equipment_access) return localProfile.equipment_access;
    } catch (e) {}

    if (wizardChatAnswers && wizardChatAnswers.equipment_access) {
        return wizardChatAnswers.equipment_access;
    }

    return 'none';
}

// Get workout options based on wizard equipment selection
function getWizardWorkoutOptions(day) {
    if (wizardAssignedProgram) return getWizardAssignedWorkoutOptions(day);
    const equipment = getWizardSelectedEquipment();
    const options = [];

    // Base options available to everyone
    options.push({ category: 'YOGA', items: [
        { id: 'yoga-flow', name: 'Power Yoga', icon: '🧘' },
        { id: 'yoga-restorative', name: 'Restorative Yoga', icon: '🧘' },
        { id: 'yoga-mobility', name: 'Mobility Yoga', icon: '🧘' }
    ]});

    options.push({ category: 'RECOVERY', items: [
        { id: 'recovery-stretch', name: 'Stretching', icon: '🔄' },
        { id: 'recovery-foam', name: 'Foam Rolling', icon: '🔄' }
    ]});

    options.push({ category: 'REST', items: [
        { id: 'rest', name: 'Rest Day', icon: '⏸️' }
    ]});

    // The editor uses the same equipment-scoped prebuilt definitions as the
    // automatic plan. A bands-only member cannot accidentally choose dumbbells.
    const strengthItems = window.PBBOnboardingWorkoutPlans?.getEquipmentOptions(equipment, wizardTrainingFrequency, window.WORKOUT_LIBRARY) || [];
    if (strengthItems.length) {
        const categoryLabels = { gym: 'FULL GYM', dumbbells: 'DUMBBELLS', bands: 'BANDS', none: 'BODYWEIGHT ONLY' };
        const normalizedEquipment = window.PBBOnboardingWorkoutPlans.normalizeEquipment(equipment);
        options.unshift({ category: categoryLabels[normalizedEquipment] || 'STRENGTH', items: strengthItems });
    }

    return options;
}

