function showWorkoutOverview(id) {
    const program = WORKOUT_DB[id];
    const startDate = localStorage.getItem('pbb_start_date');
    let dayIndex = 0;
    if (startDate) {
        const start = new Date(startDate);
        const dayDiff = Math.ceil(Math.abs(new Date() - start) / (1000 * 60 * 60 * 24));
        dayIndex = (dayDiff || 1) - 1;
    }
    const workout = program.schedule[dayIndex % program.schedule.length];

    document.getElementById('overview-title').innerText = workout.title;
    document.getElementById('overview-header-title').innerText = program.name;
    document.getElementById('overview-meta').innerText = `${program.estimatedTime} mins  ${workout.exercises.length} Exercises`;
    document.getElementById('overview-instructions').innerText = program.description || '';
    
    // Equipment
    const eqCont = document.getElementById('overview-equipment');
    eqCont.innerHTML = '';
    program.equipment.forEach(e => {
        eqCont.innerHTML += `<span style="background:#f1f5f9; padding:8px 15px; border-radius:50px; font-size:0.85rem; font-weight:600; color:var(--text-main);">${e}</span>`;
    });

    // Exercises
    const exList = document.getElementById('overview-exercise-list');
    exList.innerHTML = '';
    workout.exercises.forEach(ex => {
        exList.innerHTML += `
            <div style="display:flex; align-items:center; gap:15px; margin-bottom:20px;">
                <div style="width:70px; height:70px; border-radius:12px; background:#f1f5f9; flex-shrink:0; overflow:hidden;">
                    <img src="https://placehold.co/100x100/png?text=Preview" style="width:100%; height:100%; object-fit:cover;">
                </div>
                <div style="flex:1;">
                    <div style="font-weight:700; font-size:1.05rem;">${ex.name}</div>
                    <div style="color:var(--text-muted); font-size:0.85rem;">${ex.sets} sets x ${ex.reps}</div>
                </div>
            </div>
        `;
    });

    document.getElementById('btn-start-now').onclick = () => startActiveWorkout(id);

    // Show View
    hideAllAppViews();
    document.getElementById('view-workout-overview').style.display = 'block';
    document.querySelector('.bottom-nav').style.display = 'none';

    // Push navigation state for Android back button
    pushNavigationState('view-workout-overview', () => switchAppTab('movement-tab'));
}

function hideAllAppViews() {
    const views = ['view-dashboard', 'view-ask-balance', 'view-meals', 'movement-tab', 'group', 'view-friends', 'sleep', 'view-workout-success', 'view-profile', 'view-workout-overview', 'view-active-workout', 'view-coach-dashboard', 'view-workout-builder', 'view-program-builder', 'view-calendar', 'view-cycle', 'view-workout-list', 'view-workout-library', 'view-workout-subcategories', 'view-prebuilt-programs', 'view-progress', 'view-your-workouts', 'view-learning', 'view-log-activity', 'view-activity-success', 'view-user-profile', 'view-week-workouts', 'view-week-session', 'view-workout-journal-detail'];
    views.forEach(v => {
        const el = document.getElementById(v);
        if(el) {
            el.style.display = 'none';
            el.classList.remove('active');
        }
    });
}

async function startActiveWorkout(id, forcedDayIndex = null) {
    const program = WORKOUT_DB[id];

    // Clear custom workout tracking (this is a program workout, not custom)
    window.currentCustomWorkoutId = null;

    // Get correct day schedule & Preload History
    const user = window.currentUser;
    let dayIndex = 0;
    let customizations = null;

    if (forcedDayIndex !== null) {
        dayIndex = forcedDayIndex;
    } else if (user) {
        const profile = await window.getUserProfile();
        const startDate = profile?.program_start_date;
        if (startDate) {
            const start = new Date(startDate);
            const dayDiff = Math.ceil(Math.abs(new Date() - start) / (1000 * 60 * 60 * 24));
            dayIndex = (dayDiff || 1) - 1;
        }
    }

    const actualDayIndex = dayIndex % program.schedule.length;
    const workout = program.schedule[actualDayIndex];

    // Store current workout key for customizations
    window.currentWorkoutKey = `${id}/${actualDayIndex}`;

    // Load workout customizations if user is logged in
    if (user) {
        try {
            customizations = await dbHelpers.workoutCustomizations.get(user.id, window.currentWorkoutKey);
            window.currentWorkoutCustomizations = customizations;
        } catch(e) {
            console.error("Failed to load customizations", e);
        }
    }

    // Build exercise list with customizations applied
    let exercises = workout.exercises.map(ex => ({...ex}));

    if (customizations) {
        // Filter out removed exercises
        const removedExercises = customizations.removed_exercises || [];
        exercises = exercises.filter(ex => !removedExercises.includes(ex.name));

        // Add user-added exercises at the end
        const addedExercises = customizations.added_exercises || [];
        exercises = exercises.concat(addedExercises.map(ex => ({
            ...ex,
            isUserAdded: true
        })));
    }

    if (user) {
        await preloadWorkoutHistoryForExercises(user.id, exercises.map(ex => ex.name));
    }

    // Preload personal bests and exercise notes for all exercises in this workout
    if (user) {
        const exerciseNames = exercises.map(ex => ex.name);
        try {
            window.personalBestsCache = await dbHelpers.personalBests.getForExercises(user.id, exerciseNames);
        } catch(e) { console.error("Failed to load personal bests", e); window.personalBestsCache = {}; }
        await preloadExerciseNotes(exerciseNames);
    }

    document.getElementById('workout-player-title').innerText = workout.title;
    window.currentWorkoutName = workout.title;
    const exerciseCount = exercises.length;
    document.getElementById('workout-player-goal').innerText = `${program.description} · ${exerciseCount} Exercise${exerciseCount !== 1 ? 's' : ''}`;

    const list = document.getElementById('workout-exercises-list');
    list.innerHTML = '';

    exercises.forEach((ex, idx) => {
        const card = document.createElement('div');
        card.className = 'exercise-logger-card';
        card.setAttribute('data-exercise-name', ex.name);
        card.setAttribute('data-is-user-added', ex.isUserAdded || false);
        card.style.cssText = "background:white; border-radius:24px; box-shadow:0 10px 30px rgba(0,0,0,0.05); margin-bottom:25px; overflow:hidden; border:1px solid #f1f5f9;";

        const isTimeBased = isTimeBasedExercise(ex);
        const previousSummary = getPreviousWorkoutSummary(ex.name);
        // Use previous session's set count if available, otherwise use prescribed sets
        const prescribedSets = ex.sets || 3;
        const numSets = previousSummary && previousSummary.setCount > 0 ? previousSummary.setCount : prescribedSets;
        let setsHtml = '';
        for(let s=1; s<=numSets; s++) {
            // Get prefill data from previous session for this set number
            const prevSet = previousSummary && previousSummary.sets[s - 1] ? previousSummary.sets[s - 1] : null;
            setsHtml += getSetRowHtml(ex.name, s, isTimeBased, prevSet);
        }

        const videoUrl = findVideoMatch(ex.name);
        const previousSummaryHtml = formatPreviousWorkoutSummary(ex.name);
        const isUserAdded = ex.isUserAdded || false;
        const escapedName = ex.name.replace(/'/g, "\\'");

        card.innerHTML = `
            <div style="padding:15px; background:#f8fafc; border-bottom:1px solid #e2e8f0;">
                <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                    <div style="flex: 1;">
                        <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 4px; min-width: 0; flex-wrap: wrap;">
                            <h3 style="margin:0; font-size:1.05rem; font-weight:700; color:var(--text-main); line-height:1.2; flex:1; min-width:0;">${ex.name}</h3>
                            ${isUserAdded ? '<span style="background: var(--primary); color: white; font-size: 0.65rem; padding: 2px 6px; border-radius: 4px; font-weight: 600;">ADDED</span>' : ''}
                            ${previousSummaryHtml}
                        </div>
                        <p style="margin:0; font-size:0.85rem; color:var(--text-muted); line-height:1.3;">${ex.desc || ''}</p>
                    </div>
                    <button onclick="deleteExerciseFromWorkout('${escapedName}', ${isUserAdded})" style="background: none; border: none; color: #ef4444; cursor: pointer; padding: 5px; font-size: 0.8rem; font-weight: 600;">
                        <svg viewBox="0 0 24 24" style="width: 18px; height: 18px; fill: currentColor;">
                            <path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/>
                        </svg>
                    </button>
                </div>
            </div>

            ${getExerciseNotesHtml(ex.name)}

            ${videoUrl ? createExerciseVideoBlockHtml(videoUrl, ex.name, ex.thumbnail_url || ex.thumbnailUrl || '') : ''}

            <!-- Volume Tracker -->
            <div class="volume-display" style="display: flex; justify-content: space-between; align-items: center; padding: 10px 15px; background: linear-gradient(135deg, #fefce8 0%, #fef9c3 100%); border-bottom: 1px solid #fef08a;">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <svg viewBox="0 0 24 24" style="width: 18px; height: 18px; fill: #ca8a04;"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z"/></svg>
                    <span style="font-size: 0.75rem; font-weight: 700; color: #a16207; text-transform: uppercase;">Volume</span>
                </div>
                <div style="text-align: right;">
                    <div class="volume-value" style="font-size: 1rem; font-weight: 800; color: #854d0e;">0 kg</div>
                    <div class="volume-comparison" style="font-size: 0.7rem; font-weight: 600;">${previousSummary && previousSummary.totalVolume > 0 ? `<span style="color: #94a3b8;">Last: ${previousSummary.totalVolume.toLocaleString()} kg — beat it!</span>` : '<span style="color: #94a3b8;">Enter weight & reps</span>'}</div>
                </div>
                <div class="volume-progress-container" style="display: ${previousSummary && previousSummary.totalVolume > 0 ? 'block' : 'none'}; margin-top: 8px;">
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                        <span class="volume-target-label" style="font-size: 0.65rem; font-weight: 600; color: #a16207;">Target: ${previousSummary && previousSummary.totalVolume > 0 ? previousSummary.totalVolume.toLocaleString() + ' kg' : '—'}</span>
                        <span class="volume-percentage" style="font-size: 0.65rem; font-weight: 700; color: #a16207;">0%</span>
                    </div>
                    <div style="height: 6px; background: #fef08a; border-radius: 3px; overflow: hidden;">
                        <div class="volume-progress-bar" style="height: 100%; width: 0%; background: #ca8a04; border-radius: 3px; transition: width 0.3s ease, background 0.3s ease;"></div>
                    </div>
                </div>
            </div>

            <div style="display:grid; grid-template-columns:40px 1fr 1fr 1fr 32px 32px; gap:8px; padding:10px 15px 0 15px; font-size:0.7rem; color:#94a3b8; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; text-align:center;">
                <div>Set</div><div>Time</div><div>Reps</div><div>Kg</div><div></div><div></div>
            </div>

            <div class="sets-list-container">
                ${setsHtml}
            </div>

            <div style="padding:15px; border-top:1px solid #f8fafc;">
                <button onclick="addWorkoutSet(this, '${escapedName}', ${isTimeBased})" style="width:100%; background:transparent; border:2px dashed #e2e8f0; color:#94a3b8; font-weight:700; font-size:0.8rem; padding:12px; border-radius:12px; cursor:pointer;">+ ADD SET</button>
            </div>
        `;
        list.appendChild(card);

        // Setup volume tracking for this card
        setupVolumeTracking(card);
    });
    queueWorkoutExerciseVideosForOffline(exercises);

    hideAllAppViews();
    document.getElementById('view-active-workout').style.display = 'block';
    ensureWorkoutAddExerciseVideoButton();
    startWorkoutTimer();

    // Push navigation state for Android back button
    pushNavigationState('view-active-workout', () => quitWorkout());

    // Show total volume popup and tracker
    showLastVolumePopup();

}

// Normalize history records from DB format to local format
// DB returns: exercise_name, workout_date, weight_kg, set_number, time_duration
// Local code expects: exercise, date, kg, set, time, reps
function normalizeHistoryCache(historyData) {
    if (!historyData || !Array.isArray(historyData)) return [];
    return historyData.map(h => {
        // If already in local format, return as-is
        if (h.exercise) return h;
        // Map DB column names to local format
        return {
            exercise: h.exercise_name || '',
            date: h.workout_date || '',
            kg: h.weight_kg || '',
            set: h.set_number || 0,
            time: h.time_duration || '',
            reps: h.reps || '',
            isDropSet: h.is_drop_set || false,
            dropSetWeights: h.drop_set_weights || '',
            dropSetReps: h.drop_set_reps || '',
            workoutName: h.template_name || h.workout_name || '',
            templateName: h.template_name || '',
            // Keep original fields too for compatibility
            exercise_name: h.exercise_name,
            workout_date: h.workout_date,
            weight_kg: h.weight_kg,
            set_number: h.set_number,
            time_duration: h.time_duration,
            template_name: h.template_name
        };
    });
}

function normalizeWorkoutExerciseHistoryKey(name) {
    return String(name || '').trim().replace(/\s+/g, ' ').toLocaleLowerCase();
}

async function preloadWorkoutHistoryForExercises(userId, exerciseNames) {
    if (!userId || !Array.isArray(exerciseNames) || exerciseNames.length === 0) {
        window.workoutHistoryCache = [];
        return [];
    }

    try {
        const rawHistory = await dbHelpers.workouts.getLatestHistoryForExercises(userId, exerciseNames);
        const normalized = normalizeHistoryCache(rawHistory);
        const previous = normalizeHistoryCache(window.workoutHistoryCache || []);
        const requestedKeys = new Set(exerciseNames.map(normalizeWorkoutExerciseHistoryKey));
        const loadedKeys = new Set(normalized.map(row => normalizeWorkoutExerciseHistoryKey(row.exercise)));
        const preserved = previous.filter(row => {
            const key = normalizeWorkoutExerciseHistoryKey(row.exercise);
            return !requestedKeys.has(key) || !loadedKeys.has(key);
        });
        window.workoutHistoryCache = [...preserved, ...normalized];
        return window.workoutHistoryCache;
    } catch (error) {
        console.error('Failed to load previous exercise sessions', error);
        return window.workoutHistoryCache || [];
    }
}
window.preloadWorkoutHistoryForExercises = preloadWorkoutHistoryForExercises;

function getPreviousStats(name, set) {
    // Use cached history from DB
    const history = window.workoutHistoryCache || [];

    // Filter history for this specific exercise
    const exerciseKey = normalizeWorkoutExerciseHistoryKey(name);
    const exerciseHistory = history.filter(h => normalizeWorkoutExerciseHistoryKey(h.exercise) === exerciseKey);

    if (exerciseHistory.length === 0) return 'New';

    // Reverse iterate to find most recent
    for (let i = exerciseHistory.length - 1; i >= 0; i--) {
        const h = exerciseHistory[i];
        if (h.set == set) {
             const val = h.reps || h.time;
             if (h.kg && h.kg !== '0' && h.kg !== '') return `${h.kg}kg x ${val}`;
             return `${val}`;
        }
    }
    return '-';
}

function findPreviousSetData(name) {
    // Use cached history from DB to find most recent data for this exercise
    const history = window.workoutHistoryCache || [];
    const exerciseKey = normalizeWorkoutExerciseHistoryKey(name);
    const exerciseHistory = history.filter(h => normalizeWorkoutExerciseHistoryKey(h.exercise) === exerciseKey);

    if (exerciseHistory.length === 0) return null;

    // Get most recent entry
    const recent = exerciseHistory[exerciseHistory.length - 1];
    const val = recent.reps || recent.time;
    if (recent.kg && recent.kg !== '0' && recent.kg !== '') {
        return `${recent.kg}kg x ${val}`;
    }
    return val ? `${val}` : null;
}

// Get full previous workout summary for an exercise (all sets from last session)
function getPreviousWorkoutSummary(exerciseName) {
    const history = window.workoutHistoryCache || [];
    const exerciseKey = normalizeWorkoutExerciseHistoryKey(exerciseName);
    const exerciseHistory = history.filter(h => normalizeWorkoutExerciseHistoryKey(h.exercise) === exerciseKey);

    if (exerciseHistory.length === 0) return null;

    // Group by date to find the most recent workout date for this exercise
    const dateGroups = {};
    exerciseHistory.forEach(h => {
        const date = h.date || h.workout_date;
        if (!dateGroups[date]) dateGroups[date] = [];
        dateGroups[date].push(h);
    });

    // Get the most recent date
    const dates = Object.keys(dateGroups).sort((a, b) => new Date(b) - new Date(a));
    if (dates.length === 0) return null;

    const lastDate = dates[0];
    const lastWorkoutSets = dateGroups[lastDate].sort((a, b) => (a.set || 0) - (b.set || 0));

    // Deduplicate by set number - keep only one entry per set
    const seenSets = {};
    const uniqueSets = lastWorkoutSets.filter(s => {
        const setNum = s.set || 0;
        if (seenSets[setNum]) return false;
        seenSets[setNum] = true;
        return true;
    });

    // Calculate total volume from last workout
    let totalVolume = 0;
    const sets = uniqueSets.map(s => {
        const weight = parseFloat(s.kg) || 0;
        const reps = parseFloat(s.reps) || 0;
        const setVolume = weight * reps;
        totalVolume += setVolume;
        return {
            set: s.set,
            reps: s.reps,
            kg: s.kg,
            time: s.time,
            volume: setVolume
        };
    });

    return {
        date: lastDate,
        sets: sets,
        totalVolume: totalVolume,
        setCount: sets.length
    };
}

// Get all-time max weight for an exercise
// Prefers personal_bests table (via cache), falls back to history cache
function getExerciseMaxWeight(exerciseName) {
    // Check personal bests cache first (authoritative source)
    const pbCache = window.personalBestsCache || {};
    const pb = pbCache[exerciseName];
    if (pb && pb.best_weight_kg > 0) {
        return {
            weight: parseFloat(pb.best_weight_kg),
            reps: parseInt(pb.best_weight_reps) || 0,
            date: pb.best_weight_date,
            bestReps: parseInt(pb.best_reps) || 0,
            bestRepsWeight: parseFloat(pb.best_reps_weight_kg) || 0,
            bestRepsDate: pb.best_reps_date
        };
    }

    // Fallback to history cache
    const history = window.workoutHistoryCache || [];
    const exerciseKey = normalizeWorkoutExerciseHistoryKey(exerciseName);
    const exerciseHistory = history.filter(h => normalizeWorkoutExerciseHistoryKey(h.exercise) === exerciseKey);

    if (exerciseHistory.length === 0) return null;

    let maxWeight = 0;
    let maxWeightReps = 0;
    let maxWeightDate = null;

    exerciseHistory.forEach(h => {
        const weight = parseFloat(h.kg) || 0;
        if (weight > maxWeight) {
            maxWeight = weight;
            maxWeightReps = parseInt(h.reps) || 0;
            maxWeightDate = h.date || h.workout_date;
        }
    });

    if (maxWeight === 0) return null;

    return {
        weight: maxWeight,
        reps: maxWeightReps,
        date: maxWeightDate
    };
}

// Calculate total volume for an exercise card
function calculateExerciseVolume(card) {
    if (!card) return 0;

    const setWrappers = card.querySelectorAll('.set-wrapper');
    let totalVolume = 0;

    setWrappers.forEach(wrapper => {
        // Skip prefilled rows the user hasn't touched yet
        if (wrapper.getAttribute('data-prefilled') === 'true') return;

        const kgInput = wrapper.querySelector('.input-kg');
        const repsInput = wrapper.querySelector('.input-reps');

        const kg = parseFloat(kgInput?.value) || 0;
        const reps = parseFloat(repsInput?.value) || 0;

        totalVolume += kg * reps;

        // Also count drop sets
        const dropContainer = wrapper.querySelector('.drop-set-container');
        if (dropContainer && dropContainer.classList.contains('visible')) {
            const dropRows = dropContainer.querySelectorAll('.drop-set-row');
            dropRows.forEach(row => {
                const dropKg = parseFloat(row.querySelector('.drop-kg')?.value) || 0;
                const dropReps = parseFloat(row.querySelector('.drop-reps')?.value) || 0;
                totalVolume += dropKg * dropReps;
            });
        }
    });

    return totalVolume;
}

// Update volume display for an exercise card
function updateVolumeDisplay(card) {
    if (!card) return;

    const volumeDisplay = card.querySelector('.volume-display');
    if (!volumeDisplay) return;

    const totalVolume = calculateExerciseVolume(card);
    const volumeValue = volumeDisplay.querySelector('.volume-value');
    const volumeComparison = volumeDisplay.querySelector('.volume-comparison');
    const progressContainer = volumeDisplay.querySelector('.volume-progress-container');
    const progressBar = volumeDisplay.querySelector('.volume-progress-bar');
    const targetLabel = volumeDisplay.querySelector('.volume-target-label');
    const percentageLabel = volumeDisplay.querySelector('.volume-percentage');

    if (volumeValue) {
        volumeValue.textContent = totalVolume.toLocaleString() + ' kg';
    }

    // Compare to previous workout if available
    const exerciseName = card.getAttribute('data-exercise-name');
    const previousSummary = getPreviousWorkoutSummary(exerciseName);

    if (previousSummary && previousSummary.totalVolume > 0) {
        const targetVolume = previousSummary.totalVolume;
        const diff = totalVolume - targetVolume;
        const pct = totalVolume > 0 ? ((totalVolume / targetVolume) * 100).toFixed(0) : 0;

        // Update progress bar
        if (progressContainer) {
            progressContainer.style.display = 'block';
            if (targetLabel) targetLabel.textContent = 'Target: ' + targetVolume.toLocaleString() + ' kg';
            if (percentageLabel) {
                percentageLabel.textContent = totalVolume > 0 ? pct + '%' : '0%';
                percentageLabel.style.color = totalVolume >= targetVolume ? '#16a34a' : '#a16207';
            }
            if (progressBar) {
                const barWidth = Math.min(pct, 100);
                progressBar.style.width = barWidth + '%';
                progressBar.style.background = totalVolume >= targetVolume ? '#22c55e' : '#ca8a04';
            }
        }

        if (volumeComparison) {
            if (totalVolume === 0) {
                volumeComparison.innerHTML = '<span style="color: #94a3b8;">Last: ' + targetVolume.toLocaleString() + ' kg — beat it!</span>';
            } else if (diff > 0) {
                volumeComparison.innerHTML = '<span style="color: #22c55e; font-weight: 700;">+' + diff.toLocaleString() + ' kg — NEW VOLUME PR!</span>';
            } else if (diff < 0) {
                const remaining = Math.abs(diff);
                volumeComparison.innerHTML = '<span style="color: #f59e0b;">' + remaining.toLocaleString() + ' kg to beat last session</span>';
            } else {
                volumeComparison.innerHTML = '<span style="color: #22c55e;">Matched last session!</span>';
            }
        }
    } else if (volumeComparison) {
        volumeComparison.innerHTML = totalVolume > 0 ? '<span style="color: #94a3b8;">First time — setting your benchmark!</span>' : '<span style="color: #94a3b8;">Enter weight & reps</span>';
        if (progressContainer) progressContainer.style.display = 'none';
    }
}

// Setup volume tracking event listeners for a card
function setupVolumeTracking(card) {
    if (!card) return;

    const inputs = card.querySelectorAll('.input-kg, .input-reps, .drop-kg, .drop-reps');
    inputs.forEach(input => {
        input.addEventListener('input', () => {
            // Mark this set row as user-touched (no longer prefilled)
            const wrapper = input.closest('.set-wrapper');
            if (wrapper && wrapper.getAttribute('data-prefilled') === 'true') {
                wrapper.removeAttribute('data-prefilled');
            }
            updateVolumeDisplay(card);
            updateTotalWorkoutVolume();
        });
    });

    // Initial display update (will show 0 for prefilled rows)
    updateVolumeDisplay(card);
}

// Calculate total workout volume across ALL exercises
function calculateTotalWorkoutVolume() {
    let total = 0;
    const cards = document.querySelectorAll('#workout-exercises-list .exercise-logger-card');
    cards.forEach(card => {
        total += calculateExerciseVolume(card);
    });
    return total;
}

// Calculate total previous workout volume across all exercises
function calculateLastWorkoutTotalVolume() {
    let total = 0;
    const cards = document.querySelectorAll('#workout-exercises-list .exercise-logger-card');
    cards.forEach(card => {
        const name = card.getAttribute('data-exercise-name');
        if (name) {
            const prev = getPreviousWorkoutSummary(name);
            if (prev && prev.totalVolume > 0) {
                total += prev.totalVolume;
            }
        }
    });
    return total;
}

// Update the total workout volume bar display
function updateTotalWorkoutVolume() {
    const bar = document.getElementById('total-volume-bar');
    if (!bar) return;

    const currentTotal = calculateTotalWorkoutVolume();
    const lastTotal = window._lastWorkoutTotalVolume || 0;

    // Show the bar and dynamically position below header
    bar.style.display = 'block';
    const workoutView = document.getElementById('view-active-workout');
    if (workoutView) {
        const header = workoutView.firstElementChild;
        if (header && header.style.position === 'sticky') {
            bar.style.top = header.offsetHeight + 'px';
        }
    }

    // Update current volume value
    const valueEl = document.getElementById('total-volume-value');
    if (valueEl) valueEl.textContent = currentTotal.toLocaleString() + ' kg';

    // Update progress if we have a target
    const progressWrap = document.getElementById('total-volume-progress-wrap');
    const progressBar = document.getElementById('total-volume-progress-bar');
    const targetLabel = document.getElementById('total-volume-target-label');
    const diffEl = document.getElementById('total-volume-diff');

    if (lastTotal > 0) {
        if (progressWrap) progressWrap.style.display = 'block';
        if (targetLabel) targetLabel.textContent = 'Last: ' + lastTotal.toLocaleString() + ' kg';

        const pct = currentTotal > 0 ? ((currentTotal / lastTotal) * 100).toFixed(0) : 0;
        const barWidth = Math.min(pct, 100);

        if (progressBar) {
            progressBar.style.width = barWidth + '%';
            progressBar.style.background = currentTotal >= lastTotal ? '#22c55e' : '#facc15';
        }

        if (diffEl) {
            const diff = currentTotal - lastTotal;
            if (currentTotal === 0) {
                diffEl.textContent = '';
            } else if (diff > 0) {
                diffEl.textContent = '+' + diff.toLocaleString() + ' kg';
                diffEl.style.color = '#22c55e';
            } else if (diff < 0) {
                diffEl.textContent = Math.abs(diff).toLocaleString() + ' kg to go';
                diffEl.style.color = '#fbbf24';
            } else {
                diffEl.textContent = 'Matched!';
                diffEl.style.color = '#22c55e';
            }
        }
    } else {
        if (progressWrap) progressWrap.style.display = 'none';
    }
}

// Show the "last workout volume" popup
function showLastVolumePopup() {
    // Small delay to let DOM render first
    setTimeout(() => {
        const lastTotal = calculateLastWorkoutTotalVolume();
        window._lastWorkoutTotalVolume = lastTotal;

        // Always show the total volume bar
        updateTotalWorkoutVolume();

        // Only show popup if there was a previous workout with volume
        if (lastTotal > 0) {
            const popup = document.getElementById('last-volume-popup');
            const volumeEl = document.getElementById('popup-last-volume');
            if (popup && volumeEl) {
                volumeEl.textContent = lastTotal.toLocaleString() + ' kg';
                popup.style.display = 'flex';
                // Auto-dismiss after 4 seconds
                window._volumePopupTimer = setTimeout(dismissVolumePopup, 4000);
            }
        }
    }, 300);
}

// Dismiss the popup
function dismissVolumePopup() {
    const popup = document.getElementById('last-volume-popup');
    if (popup) popup.style.display = 'none';
    if (window._volumePopupTimer) {
        clearTimeout(window._volumePopupTimer);
        window._volumePopupTimer = null;
    }
}

// Format the exercise personal best as a compact header pill.
function formatPreviousWorkoutSummary(exerciseName) {
    const maxWeight = getExerciseMaxWeight(exerciseName);

    if (!maxWeight) return '';

    return '<span class="exercise-history-panel exercise-pb-pill" style="display:inline-flex; align-items:center; margin-left:auto; padding:2px 6px; border:1px solid #fbbf24; border-radius:999px; background:#fef3c7; color:#78350f; font-size:0.64rem; line-height:1.2; font-weight:800; white-space:nowrap; flex-shrink:0;">PB: ' + maxWeight.weight + 'kg &times; ' + maxWeight.reps + ' reps</span>';
}

// Generate volume display HTML with progress bar for an exercise
function getVolumeDisplayHtml(exerciseName) {
    const previousSummary = getPreviousWorkoutSummary(exerciseName);
    const targetVolume = previousSummary ? previousSummary.totalVolume : 0;
    const targetText = targetVolume > 0 ?
        '<span style="color: #94a3b8;">Last: ' + targetVolume.toLocaleString() + ' kg — beat it!</span>' :
        '<span style="color: #94a3b8;">Enter weight & reps</span>';

    let html = '<div class="volume-display" style="padding: 12px 15px; background: linear-gradient(135deg, #fefce8 0%, #fef9c3 100%); border-bottom: 1px solid #fef08a;">';
    html += '<div style="display: flex; justify-content: space-between; align-items: center;">';
    html += '<div style="display: flex; align-items: center; gap: 8px;">';
    html += '<svg viewBox="0 0 24 24" style="width: 18px; height: 18px; fill: #ca8a04;"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z"/></svg>';
    html += '<span style="font-size: 0.75rem; font-weight: 700; color: #a16207; text-transform: uppercase;">Volume</span>';
    html += '</div>';
    html += '<div style="text-align: right;">';
    html += '<div class="volume-value" style="font-size: 1rem; font-weight: 800; color: #854d0e;">0 kg</div>';
    html += '<div class="volume-comparison" style="font-size: 0.7rem; font-weight: 600;">' + targetText + '</div>';
    html += '</div></div>';

    // Progress bar
    html += '<div class="volume-progress-container" style="display: ' + (targetVolume > 0 ? 'block' : 'none') + '; margin-top: 8px;">';
    html += '<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">';
    html += '<span class="volume-target-label" style="font-size: 0.65rem; font-weight: 600; color: #a16207;">Target: ' + (targetVolume > 0 ? targetVolume.toLocaleString() + ' kg' : '—') + '</span>';
    html += '<span class="volume-percentage" style="font-size: 0.65rem; font-weight: 700; color: #a16207;">0%</span>';
    html += '</div>';
    html += '<div style="height: 6px; background: #fef08a; border-radius: 3px; overflow: hidden;">';
    html += '<div class="volume-progress-bar" style="height: 100%; width: 0%; background: #ca8a04; border-radius: 3px; transition: width 0.3s ease, background 0.3s ease;"></div>';
    html += '</div></div></div>';

    return html;
}

// ===========================================
// EXERCISE NOTES SYSTEM
// Per-exercise notes for users & coach tips
// ===========================================

// Caches populated by preloadExerciseNotes() before workout starts
window.exerciseNotesCache = {};  // { exerciseName: noteText }
window.coachNotesCache = {};     // { exerciseName: noteText }

// Preload notes for all exercises in a workout
async function preloadExerciseNotes(exerciseNames) {
    window.exerciseNotesCache = {};
    window.coachNotesCache = {};
    const user = window.currentUser;
    if (!user || !exerciseNames || exerciseNames.length === 0) return;

    try {
        const result = await dbHelpers.exerciseNotes.loadForExercises(user.id, exerciseNames);
        window.exerciseNotesCache = result.userNotes || {};
        window.coachNotesCache = result.coachNotes || {};
    } catch (e) {
        console.error('Failed to preload exercise notes:', e);
        // Fallback: try localStorage
        try {
            const stored = localStorage.getItem('pbb_exercise_notes');
            if (stored) window.exerciseNotesCache = JSON.parse(stored);
        } catch (le) { /* ignore */ }
    }
}

function normalizeExerciseTechniqueName(exerciseName) {
    return String(exerciseName || '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

function exerciseNameMatches(normalizedName, terms) {
    const words = normalizedName.split(' ').filter(Boolean);
    return terms.some(term => {
        if (term.indexOf(' ') !== -1) return normalizedName.indexOf(term) !== -1;
        return words.some(word => word === term || word.indexOf(term) === 0);
    });
}

function getExerciseTechniqueData(exerciseName) {
    if (window.PBBExerciseTechnique?.getExerciseTechniqueData) {
        return window.PBBExerciseTechnique.getExerciseTechniqueData(exerciseName);
    }
    const name = normalizeExerciseTechniqueName(exerciseName);
    const has = terms => exerciseNameMatches(name, terms);
    const baseForce = 'Your body is one connected unit: push into the floor, bench, handle, or bar, let the equal opposing force come back, then keep the core stiff enough to transfer it between hips, spine, and shoulders.';
    const baseReset = 'Between sets: pick one cue to own next set. Stop or reduce load if you feel sharp pain, numbness, dizziness, or form you cannot control.';

    const general = {
        family: 'Whole-body lift',
        force: baseForce,
        setup: [
            'Stack ribs over pelvis and brace 360 degrees before the rep starts.',
            'Keep pressure even through the support points: feet, hands, bench, or pad.',
            'Open the chest by widening the collarbones, not by arching through the low back.'
        ],
        move: [
            'Move the load with control and keep joints tracking in their natural line.',
            'Let the working joints move while the trunk stays quiet and strong.',
            'Own the end range, then reverse without bouncing or rushing.'
        ],
        reset: baseReset
    };

    if (has(['calf'])) {
        return {
            family: 'Ankle drive',
            force: baseForce,
            setup: [
                'Build a tripod foot and keep the big toe heavy.',
                'Stack hips over ankles so the calf drives straight through the foot.',
                'Brace lightly so the ribs do not flare as you rise.'
            ],
            move: [
                'Drive through the ball of the foot and lift the heel under control.',
                'Pause tall without rolling to the outside edge of the foot.',
                'Lower slowly until the ankle can move without the arch collapsing.'
            ],
            reset: baseReset
        };
    }

    if (has(['leg extension', 'quad extension'])) {
        return {
            family: 'Knee extension',
            force: baseForce,
            setup: [
                'Set hips and low back against the pad before the first rep.',
                'Line the knee up with the machine hinge as best as the seat allows.',
                'Brace the trunk so the quads extend the knee instead of the torso rocking.'
            ],
            move: [
                'Extend the knee smoothly and squeeze the quad at the top.',
                'Keep toes and kneecap pointing the same direction.',
                'Control the lower until the plates nearly settle, then repeat.'
            ],
            reset: baseReset
        };
    }

    if (has(['leg curl', 'hamstring curl', 'lap curl'])) {
        return {
            family: 'Knee flexion',
            force: baseForce,
            setup: [
                'Anchor hips to the pad and keep ribs down.',
                'Set the roller just above the heel if the machine allows it.',
                'Keep pelvis quiet so the hamstrings bend the knee without low-back help.'
            ],
            move: [
                'Pull the heel toward the glute without lifting the hips.',
                'Pause where hamstrings are shortest, then lower with control.',
                'Keep both knees tracking straight rather than rotating in or out.'
            ],
            reset: baseReset
        };
    }

    if (has(['squat', 'leg press', 'hack', 'goblet'])) {
        return {
            family: 'Squat pattern',
            force: 'Feet push the floor or platform away, the floor pushes back, and the trunk transfers that force through hips and knees into the load.',
            setup: [
                'Tripod foot: heel, big toe, and little toe stay heavy.',
                'Stack ribs over pelvis, brace 360 degrees, then unlock hips and knees together.',
                'Screw the feet out lightly to wake glute med and keep knees tracking over toes.'
            ],
            move: [
                'Sit between the hips while keeping the chest open and ribs controlled.',
                'Let knees travel in line with toes, not cave inward.',
                'Drive the floor away and finish tall through glutes, not by leaning back.'
            ],
            reset: baseReset
        };
    }

    if (has(['lunge', 'split', 'bulgarian', 'step up', 'step ups'])) {
        return {
            family: 'Single-leg strength',
            force: 'The front foot owns the ground. Your core keeps pelvis and ribs level so force travels from the planted leg into the load.',
            setup: [
                'Plant a tripod front foot and keep the knee pointing over the middle toes.',
                'Square hips forward and keep the pelvis level, glute med keeps the thigh from diving inward.',
                'Brace before descending so the torso stays tall rather than folding.'
            ],
            move: [
                'Lower with control and let the front hip and knee share the work.',
                'Drive through the whole front foot, not just the toes.',
                'Keep the back leg as a guide, not the main engine.'
            ],
            reset: baseReset
        };
    }

    if (has(['deadlift', 'rdl', 'romanian', 'hinge', 'good morning', 'swing', 'swings'])) {
        return {
            family: 'Hip hinge',
            force: 'The floor pushes back through your feet while the posterior chain turns that force into hip extension. The core transfers force without letting the spine bend under load.',
            setup: [
                'Root the whole foot and soften the knees.',
                'Brace ribs to pelvis, then push hips back like closing a car door.',
                'Set lats by gently pulling shoulders away from ears and keeping the bar or weights close.'
            ],
            move: [
                'Hips move back and forward; the spine stays long and quiet.',
                'Feel hamstrings load on the way down before driving hips through.',
                'Finish by standing tall with glutes, not by over-arching the low back.'
            ],
            reset: baseReset
        };
    }

    if (has(['hip thrust', 'thrust', 'glute bridge', 'bridge', 'clams', 'clam', 'abduction', 'kickback', 'kick back', 'banded hip'])) {
        return {
            family: 'Glute drive',
            force: 'Your feet or knees push into the floor, bench, or band, and the glutes use that opposing force to extend or stabilize the hip while the core holds the pelvis steady.',
            setup: [
                'Stack ribs down over pelvis before squeezing the glutes.',
                'Keep knees tracking over toes so glute med supports the outside hip.',
                'Use the bench, floor, or band as something to push against, not something to collapse into.'
            ],
            move: [
                'Drive from the hip and keep the low back quiet.',
                'Pause where glutes are strongest without flaring ribs.',
                'Lower slowly enough to feel the hip control the path.'
            ],
            reset: baseReset
        };
    }

    if (has(['fly', 'flys', 'flyes']) && !has(['rear delt'])) {
        return {
            family: 'Chest fly pattern',
            force: 'The bench or floor gives the trunk a base while the pecs move the arms around a stable rib cage.',
            setup: [
                'Open the chest by widening collarbones and keeping ribs stacked.',
                'Set shoulders low and broad without pinching the neck.',
                'Keep elbows softly bent and wrists stacked with the load.'
            ],
            move: [
                'Arc the arms wide until the chest stretches without shoulder pinch.',
                'Bring arms back by squeezing pecs around the rib cage.',
                'Keep the shoulder blade controlled, not jammed down.'
            ],
            reset: baseReset
        };
    }

    if (has(['bench', 'chest press', 'pushup', 'pushups', 'push up', 'dip', 'close grip chest'])) {
        return {
            family: 'Horizontal press',
            force: 'Hands push the bar, floor, or handles away, the surface pushes back, and the trunk links that force to a stable rib cage and pelvis.',
            setup: [
                'Stack wrist over elbow and keep forearms close to vertical.',
                'Open the chest without flaring ribs or shrugging.',
                'For bench, set shoulder blades into the bench. For push-ups, let shoulder blades glide around the ribs.'
            ],
            move: [
                'Lower with elbows tracking roughly 30 to 60 degrees from the body.',
                'Press the surface away while keeping the neck long.',
                'Finish strong without letting hips sag or ribs pop up.'
            ],
            reset: baseReset
        };
    }

    if (has(['shoulder press', 'overhead', 'military', 'arnold'])) {
        return {
            family: 'Vertical press',
            force: 'Feet push down, the core transfers that force up the trunk, and the shoulders press the load overhead without the spine turning into the mover.',
            setup: [
                'Squeeze glutes lightly and stack ribs over pelvis.',
                'Start with elbows just forward of the body, wrists stacked over elbows.',
                'Let shoulder blades upwardly rotate, do not pin them hard down.'
            ],
            move: [
                'Press up and slightly back until biceps finish near ears.',
                'Keep ribs down so the shoulder moves, not the low back.',
                'Lower under control to the start position you can own.'
            ],
            reset: baseReset
        };
    }

    if (has(['plank', 'hollow', 'dead bug', 'bird dog', 'pallof', 'woodchop', 'crunch', 'sit up', 'situp', 'leg raise', 'knee tuck', 'v hold', 'v sit', 'ab roller', 'mountain climber', 'oblique', 'core'])) {
        return {
            family: 'Core transfer',
            force: 'The core is a force-transfer system: it resists unwanted motion so the arms and legs can produce force without energy leaking through the spine.',
            setup: [
                'Stack ribs over pelvis and create 360 degree pressure around the waist.',
                'Keep neck long and jaw relaxed.',
                'Choose a range where the low back does not arch or flatten aggressively.'
            ],
            move: [
                'Move from hips, shoulders, or ribs while the pelvis stays controlled.',
                'Exhale through effort without losing the brace.',
                'Slow the rep down if momentum takes over.'
            ],
            reset: baseReset
        };
    }

    if (has(['row', 'pulldown', 'pull down', 'pullup', 'pull up', 'chin', 'face pull', 'rear delt', 'lat pull'])) {
        return {
            family: 'Pull and scapula',
            force: 'Hands connect to the handle or bar, the trunk stays braced, and the shoulder blade guides force from the arm into the rib cage.',
            setup: [
                'Brace ribs to pelvis before the pull starts.',
                'Set a long neck and open chest without over-arching.',
                'Let the shoulder blade move on the rib cage: reach at the stretch, glide back or down as you pull.'
            ],
            move: [
                'Lead with shoulder blade control, then drive the elbow.',
                'Keep wrists quiet and avoid yanking with the neck.',
                'Return slowly until the target muscle lengthens without losing posture.'
            ],
            reset: baseReset
        };
    }

    if (has(['lateral', 'front raise', 'shoulder raise', 'around the world', 'yes nos'])) {
        return {
            family: 'Shoulder raise',
            force: 'Feet and trunk create the platform while the shoulder moves the arm. The core prevents swinging so the delts do the work.',
            setup: [
                'Stand tall with glutes lightly on and ribs stacked.',
                'Keep shoulders wide and low, not shrugged.',
                'Use a slight elbow bend and keep wrists quiet.'
            ],
            move: [
                'Raise in the scapular plane, slightly forward of straight out to the side.',
                'Stop before the neck takes over.',
                'Lower slower than you lift to keep tension on the delt.'
            ],
            reset: baseReset
        };
    }

    if (has(['curl', 'bicep'])) {
        return {
            family: 'Arm curl',
            force: 'The arm bends the load, but the body still acts as one unit: feet, glutes, and core stop the torso from swinging.',
            setup: [
                'Stand or sit tall with ribs over pelvis.',
                'Keep shoulders open and upper arms close to still.',
                'Grip firmly without letting wrists bend back.'
            ],
            move: [
                'Curl by bending the elbow, not by leaning back.',
                'Squeeze at the top while shoulders stay away from ears.',
                'Lower slowly until the elbow opens under control.'
            ],
            reset: baseReset
        };
    }

    if (has(['tricep', 'skull crusher', 'pushdown', 'push down'])) {
        return {
            family: 'Triceps extension',
            force: 'The body anchors the load while the elbow extends. A quiet trunk lets the triceps create force instead of the shoulders or low back stealing it.',
            setup: [
                'Stack ribs and pelvis before extending the elbow.',
                'Keep shoulders set wide and neck relaxed.',
                'Line wrist, elbow, and cable or dumbbell path as cleanly as possible.'
            ],
            move: [
                'Extend from the elbow and finish with a full triceps squeeze.',
                'Keep upper arms controlled instead of swinging.',
                'Return slowly until the triceps lengthen without shoulder irritation.'
            ],
            reset: baseReset
        };
    }

    if (has(['jump', 'burpee', 'slam', 'smash', 'skier', 'skiier', 'power'])) {
        return {
            family: 'Power pattern',
            force: 'Power starts from the ground: load the floor, receive its opposing force, then transfer it quickly through hips, core, and arms.',
            setup: [
                'Land or load with feet under control and knees tracking over toes.',
                'Brace before the explosive part so force does not leak through the spine.',
                'Keep chest open and eyes steady.'
            ],
            move: [
                'Be fast on the way up, quiet and controlled on the way down.',
                'Absorb impact through hips, knees, and ankles together.',
                'Reset posture before the next rep instead of chasing speed.'
            ],
            reset: baseReset
        };
    }

    if (has(['yoga', 'stretch', 'pose', 'mobility'])) {
        return {
            family: 'Mobility and control',
            force: 'Even in slow work, the body is one unit: breath, brace, and joint position decide where tension goes.',
            setup: [
                'Find length through the spine before chasing range.',
                'Keep support points grounded and breathe into the rib cage.',
                'Use core tension to guide the pelvis instead of hanging on joints.'
            ],
            move: [
                'Move slowly into range and pause before intensity becomes joint pinch.',
                'Let shoulders and hips rotate naturally where the pose asks for it.',
                'Come out with the same control you used to enter.'
            ],
            reset: baseReset
        };
    }

    return general;
}

function getExerciseTechniqueHtml(exerciseName) {
    const technique = getExerciseTechniqueData(exerciseName);
    if (technique.hidePanel) return '';
    const listHtml = items => items.map(item => '<li>' + escapeHtml(item) + '</li>').join('');
    return `
        <details class="exercise-technique-panel">
            <summary>
                <span class="exercise-technique-main">
                    <span class="exercise-technique-kicker">Form science</span>
                    <span class="exercise-technique-title">Science &amp; form cues</span>
                </span>
                <span class="exercise-technique-family">${escapeHtml(technique.family)}</span>
                <span class="exercise-technique-chev">+</span>
            </summary>
            <div class="exercise-technique-body">
                <p class="exercise-technique-force">${escapeHtml(technique.force)}</p>
                <div class="exercise-technique-columns">
                    <div>
                        <div class="exercise-technique-subtitle">Set up</div>
                        <ul>${listHtml(technique.setup)}</ul>
                    </div>
                    <div>
                        <div class="exercise-technique-subtitle">Move</div>
                        <ul>${listHtml(technique.move)}</ul>
                    </div>
                </div>
                <div class="exercise-technique-reset">${escapeHtml(technique.reset)}</div>
            </div>
        </details>
    `;
}

// Generate the notes section HTML for an exercise card
function getExerciseNotesHtml(exerciseName) {
    const coachNote = window.coachNotesCache[exerciseName] || '';
    const userNote = window.exerciseNotesCache[exerciseName] || '';
    const escapedName = exerciseName.replace(/'/g, "\\'").replace(/"/g, '&quot;');
    const hasNote = userNote.length > 0;

    let html = '<div class="exercise-note-section">';

    html += getExerciseTechniqueHtml(exerciseName);

    // Coach note (always visible if exists)
    if (coachNote) {
        html += '<div class="coach-note-bubble">';
        html += '<div style="display:flex; align-items:center; gap:6px;">';
        html += '<span class="coach-note-badge"><svg viewBox="0 0 24 24" style="width:10px; height:10px; fill:currentColor;"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg> COACH</span>';
        html += '<span style="font-size:0.7rem; color:#7c3aed; font-weight:500;">Shannon\'s tip</span>';
        html += '</div>';
        html += '<p class="coach-note-text">"' + coachNote.replace(/</g, '&lt;').replace(/>/g, '&gt;') + '"</p>';
        html += '</div>';
    }

    // User note toggle + textarea
    html += '<div class="exercise-note-toggle' + (hasNote ? ' has-note' : '') + '" onclick="toggleExerciseNote(this)">';
    html += '<svg viewBox="0 0 24 24"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z"/></svg>';
    html += '<span>' + (hasNote ? 'My note' : 'Add a note...') + '</span>';
    html += '</div>';

    html += '<textarea class="exercise-note-input" data-exercise="' + escapedName + '" placeholder="Write a quick note about this exercise..." onblur="saveExerciseNote(this)">' + (userNote ? userNote.replace(/</g, '&lt;').replace(/>/g, '&gt;') : '') + '</textarea>';

    html += '</div>';
    return html;
}

// Toggle the note textarea visibility
function toggleExerciseNote(toggleEl) {
    const section = toggleEl.closest('.exercise-note-section');
    const textarea = section.querySelector('.exercise-note-input');
    if (!textarea) return;

    const isVisible = textarea.style.display === 'block';
    textarea.style.display = isVisible ? 'none' : 'block';
    if (!isVisible) {
        textarea.focus();
    }
}

// Save exercise note (called on blur)
async function saveExerciseNote(textarea) {
    const exerciseName = textarea.getAttribute('data-exercise');
    const noteText = textarea.value.trim();
    const user = window.currentUser;
    const section = textarea.closest('.exercise-note-section');
    const toggle = section.querySelector('.exercise-note-toggle');
    const toggleLabel = toggle ? toggle.querySelector('span') : null;

    // Update cache
    if (noteText) {
        window.exerciseNotesCache[exerciseName] = noteText;
    } else {
        delete window.exerciseNotesCache[exerciseName];
    }

    // Update toggle appearance
    if (toggle) {
        if (noteText) {
            toggle.classList.add('has-note');
            if (toggleLabel) toggleLabel.textContent = 'My note';
        } else {
            toggle.classList.remove('has-note');
            if (toggleLabel) toggleLabel.textContent = 'Add a note...';
        }
    }

    // Persist to localStorage as fallback
    try {
        localStorage.setItem('pbb_exercise_notes', JSON.stringify(window.exerciseNotesCache));
    } catch (e) { /* ignore */ }

    // Persist to database
    if (!user) return;

    // Check if the current user is the coach (Shannon)
    const isCoach = user.email === 'shannonbirch@cocospersonaltraining.com';

    try {
        if (noteText) {
            await dbHelpers.exerciseNotes.save(user.id, exerciseName, noteText, isCoach);
        } else {
            await dbHelpers.exerciseNotes.remove(user.id, exerciseName);
        }
    } catch (e) {
        console.error('Failed to save exercise note:', e);
    }
}

