// Score an exercise based on how well it matches the search query
function scoreExerciseMatch(exerciseName, searchTerms, fullQuery) {
    const nameLower = exerciseName.toLowerCase();
    const queryLower = fullQuery.toLowerCase().trim();
    let score = 0;

    // Exact match gets highest priority (1000 points)
    if (nameLower === queryLower) {
        score += 1000;
    }
    // Starts with the full query (500 points)
    else if (nameLower.startsWith(queryLower)) {
        score += 500;
    }
    // Starts with first search term (200 points)
    else if (searchTerms.length > 0 && nameLower.startsWith(searchTerms[0])) {
        score += 200;
    }

    // Shannon's filmed exercise bonus (150 points) — our own videos rank first
    if (SHANNON_FILMED_EXERCISES.has(exerciseName)) {
        score += 150;
    }

    // Popular/main exercise bonus (100 points)
    if (POPULAR_EXERCISES.has(exerciseName)) {
        score += 100;
    }

    // Word boundary matches are better than substring matches
    // Check if search terms appear as complete words (50 points each)
    const words = nameLower.split(/\s+/);
    for (const term of searchTerms) {
        if (words.some(word => word === term)) {
            score += 50; // Exact word match
        } else if (words.some(word => word.startsWith(term))) {
            score += 25; // Word starts with term
        }
    }

    // Shorter names are often more "primary" exercises (slight bonus)
    // Max 20 points for names under 20 characters
    score += Math.max(0, 20 - exerciseName.length);

    return score;
}

function escapeAddExerciseHtml(value) {
    return String(value ?? '').replace(/[&<>"']/g, ch => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#39;'
    }[ch]));
}

function escapeAddExerciseJsString(value) {
    return String(value ?? '')
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/\r?\n/g, ' ');
}

function parseAddExerciseHistoryDate(value) {
    if (!value) return null;
    const raw = String(value);
    const date = /^\d{4}-\d{2}-\d{2}$/.test(raw)
        ? new Date(raw + 'T12:00:00')
        : new Date(raw);
    return Number.isNaN(date.getTime()) ? null : date;
}

function getAddExerciseDateKey(value) {
    if (!value) return '';
    const raw = String(value);
    if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
    const date = parseAddExerciseHistoryDate(raw);
    return date ? date.toISOString().slice(0, 10) : raw;
}

function getAddExerciseDaysSince(date) {
    if (!date) return null;
    const dayMs = 24 * 60 * 60 * 1000;
    const today = new Date();
    const todayNoon = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 12);
    const dateNoon = new Date(date.getFullYear(), date.getMonth(), date.getDate(), 12);
    return Math.max(0, Math.floor((todayNoon - dateNoon) / dayMs));
}

function formatAddExerciseDaysSince(days) {
    if (days === null || Number.isNaN(days)) return '';
    if (days === 0) return 'today';
    if (days === 1) return 'yesterday';
    return days + ' days ago';
}

function formatAddExerciseShortDate(date) {
    if (!date) return '';
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function formatAddExerciseVolume(value) {
    const rounded = Math.round(Math.abs(value || 0));
    return rounded.toLocaleString() + ' kg';
}

function getAddExerciseExistingNames() {
    return new Set(Array.from(document.querySelectorAll('#workout-exercises-list .exercise-logger-card'))
        .map(card => (card.getAttribute('data-exercise-name') || '').trim().toLowerCase())
        .filter(Boolean));
}

function getAddExerciseCustomExerciseMap() {
    const customMap = new Map();
    (window._customExercisesCache || []).forEach(ex => {
        const name = (ex && ex.exercise_name ? String(ex.exercise_name).trim() : '');
        if (name) customMap.set(name.toLowerCase(), ex);
    });
    return customMap;
}

function getAddExerciseSessionStats(rows) {
    const sessionsByDate = {};

    rows.forEach(row => {
        const rawDate = row.date || row.workout_date || row.created_at;
        const dateKey = getAddExerciseDateKey(rawDate);
        if (!dateKey) return;
        if (!sessionsByDate[dateKey]) {
            sessionsByDate[dateKey] = {
                dateKey,
                date: parseAddExerciseHistoryDate(rawDate),
                setCount: 0,
                totalVolume: 0
            };
        }

        const weight = parseFloat(row.kg || row.weight_kg) || 0;
        const reps = parseFloat(row.reps) || 0;
        sessionsByDate[dateKey].setCount += 1;
        sessionsByDate[dateKey].totalVolume += weight * reps;
    });

    return Object.values(sessionsByDate)
        .filter(session => session.date)
        .sort((a, b) => b.date - a.date);
}

function getSuggestedExercisesForAdd(limit = 5) {
    const history = Array.isArray(window.workoutHistoryCache) ? window.workoutHistoryCache : [];
    const existingNames = getAddExerciseExistingNames();
    const customMap = getAddExerciseCustomExerciseMap();
    const libraryNames = typeof EXERCISE_VIDEOS !== 'undefined' ? new Set(Object.keys(EXERCISE_VIDEOS)) : new Set();
    const historyByExercise = {};

    history.forEach(row => {
        const name = (row.exercise || row.exercise_name || '').trim();
        if (!name || existingNames.has(name.toLowerCase())) return;
        if (!historyByExercise[name]) historyByExercise[name] = [];
        historyByExercise[name].push(row);
    });

    const suggestions = Object.keys(historyByExercise).map(name => {
        const sessions = getAddExerciseSessionStats(historyByExercise[name]);
        if (sessions.length === 0) return null;

        const lastSession = sessions[0];
        const previousSession = sessions[1] || null;
        const daysSince = getAddExerciseDaysSince(lastSession.date);
        const recentSessions = sessions.filter(session => {
            const sessionDaysSince = getAddExerciseDaysSince(session.date);
            return sessionDaysSince !== null && sessionDaysSince <= 60;
        }).length;
        const isCustom = customMap.has(name.toLowerCase());
        const isFilmed = typeof SHANNON_FILMED_EXERCISES !== 'undefined' && SHANNON_FILMED_EXERCISES.has(name);
        const isPopular = typeof POPULAR_EXERCISES !== 'undefined' && POPULAR_EXERCISES.has(name);
        const reasons = [];
        let score = 0;
        let hasProgressReason = false;

        if (previousSession && previousSession.totalVolume > 0 && lastSession.totalVolume > previousSession.totalVolume) {
            const volumeDelta = lastSession.totalVolume - previousSession.totalVolume;
            const progressPct = (volumeDelta / previousSession.totalVolume) * 100;
            if (progressPct >= 3) {
                score += 38 + Math.min(24, progressPct);
                hasProgressReason = true;
                reasons.push({
                    priority: daysSince !== null && daysSince >= 14 ? 55 : 95,
                    badge: 'Progressing',
                    detail: '+' + formatAddExerciseVolume(volumeDelta) + ' last time'
                });
            }
        }

        if (daysSince !== null && daysSince >= 14) {
            score += 22 + Math.min(35, daysSince);
            reasons.push({
                priority: 100 + Math.min(30, daysSince),
                badge: 'Due again',
                detail: 'Last done ' + formatAddExerciseDaysSince(daysSince)
            });
        } else if (daysSince !== null && daysSince >= 7) {
            score += 12;
            reasons.push({
                priority: 45,
                badge: 'Worth revisiting',
                detail: 'Last done ' + formatAddExerciseDaysSince(daysSince)
            });
        }

        if (recentSessions >= 3) {
            score += Math.min(24, recentSessions * 4);
            reasons.push({
                priority: 70,
                badge: 'Regular pick',
                detail: recentSessions + ' recent sessions'
            });
        } else {
            score += recentSessions * 3;
        }

        if (isCustom) score += 8;
        if (isFilmed) score += 6;
        if (isPopular) score += 5;
        if (libraryNames.has(name)) score += 3;
        if (daysSince !== null && daysSince <= 1) score -= hasProgressReason ? 8 : 30;

        reasons.sort((a, b) => b.priority - a.priority);
        const primaryReason = reasons[0] || {
            badge: isCustom ? 'Your exercise' : 'Suggested',
            detail: daysSince !== null ? 'Last done ' + formatAddExerciseDaysSince(daysSince) : 'From your library'
        };

        return {
            name,
            score,
            badge: primaryReason.badge,
            detail: primaryReason.detail,
            meta: [
                daysSince !== null ? 'Last done ' + formatAddExerciseDaysSince(daysSince) : '',
                lastSession.setCount ? lastSession.setCount + ' set' + (lastSession.setCount === 1 ? '' : 's') : '',
                lastSession.totalVolume > 0 ? formatAddExerciseVolume(lastSession.totalVolume) : '',
                formatAddExerciseShortDate(lastSession.date)
            ].filter(Boolean).join(' &middot; '),
            isCustom
        };
    }).filter(Boolean);

    const historyExerciseKeys = new Set(Object.keys(historyByExercise).map(name => name.toLowerCase()));

    customMap.forEach((ex, lowerName) => {
        const name = (ex.exercise_name || '').trim();
        if (!name || existingNames.has(lowerName) || historyExerciseKeys.has(lowerName)) return;
        suggestions.push({
            name,
            score: 9,
            badge: 'Your exercise',
            detail: ex.muscle_group ? String(ex.muscle_group).replace('_', ' ') : 'Saved in your library',
            meta: ex.video_url ? 'Has video' : '',
            isCustom: true
        });
    });

    return suggestions
        .filter(item => item.score > 0)
        .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
        .slice(0, limit);
}

function getAddExerciseSuggestionIconHtml(suggestion) {
    if (suggestion.badge === 'Progressing') {
        return '<svg viewBox="0 0 24 24" style="width:20px; height:20px; fill:currentColor;"><path d="M16 6l2.29 2.29-4.88 4.88-4-4L2 16.59 3.41 18l6-6 4 4 6.3-6.29L22 12V6h-6z"/></svg>';
    }
    if (suggestion.badge === 'Due again' || suggestion.badge === 'Worth revisiting') {
        return '<svg viewBox="0 0 24 24" style="width:20px; height:20px; fill:currentColor;"><path d="M12 6V3L8 7l4 4V8c2.76 0 5 2.24 5 5 0 1.57-.73 2.97-1.86 3.89l1.42 1.42A6.96 6.96 0 0019 13c0-3.86-3.14-7-7-7zm-5 5c0-1.57.73-2.97 1.86-3.89L7.44 5.69A6.96 6.96 0 005 11c0 3.86 3.14 7 7 7v3l4-4-4-4v3c-2.76 0-5-2.24-5-5z"/></svg>';
    }
    if (suggestion.isCustom) {
        return '<svg viewBox="0 0 24 24" style="width:20px; height:20px; fill:currentColor;"><path d="M17 10.5V7c0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h12c.55 0 1-.45 1-1v-3.5l4 4v-11l-4 4z"/></svg>';
    }
    return '<svg viewBox="0 0 24 24" style="width:20px; height:20px; fill:currentColor;"><path d="M20.57 14.86L22 13.43 20.57 12 17 15.57 8.43 7 12 3.43 10.57 2 9.14 3.43 7.71 2 5.57 4.14 4.14 2.71 2.71 4.14l1.43 1.43L2 7.71l1.43 1.43L2 10.57 3.43 12 7 8.43 15.57 17 12 20.57 13.43 22l1.43-1.43L16.29 22l2.14-2.14 1.43 1.43 1.43-1.43-1.43-1.43L22 16.29z"/></svg>';
}

function renderAddExerciseSuggestions(options = {}) {
    const resultsContainer = document.getElementById('add-exercise-results');
    if (!resultsContainer) return;

    const suggestions = getSuggestedExercisesForAdd(5);

    if (options.loading && suggestions.length === 0) {
        resultsContainer.innerHTML = `
            <div style="text-align: center; padding: 40px 20px; color: #94a3b8;">
                Finding suggestions from your recent workouts...
            </div>
        `;
        return;
    }

    if (suggestions.length === 0) {
        resultsContainer.innerHTML = `
            <div style="text-align: center; padding: 40px; color: #94a3b8;">
                Type to search for exercises from your library
            </div>
        `;
        return;
    }

    const suggestionHtml = suggestions.map(suggestion => {
        const escapedName = escapeAddExerciseJsString(suggestion.name);
        const safeName = escapeAddExerciseHtml(suggestion.name);
        const safeBadge = escapeAddExerciseHtml(suggestion.badge);
        const safeDetail = escapeAddExerciseHtml(suggestion.detail);
        const metaHtml = suggestion.meta ? `<div style="font-size:0.72rem; color:#94a3b8; margin-top:3px; line-height:1.35;">${suggestion.meta}</div>` : '';
        const badgeColor = suggestion.badge === 'Progressing'
            ? '#16a34a'
            : suggestion.badge === 'Due again'
                ? '#d97706'
                : 'var(--primary)';
        const badgeTextLight = suggestion.badge === 'Progressing'
            ? '#166534'
            : suggestion.badge === 'Due again'
                ? '#92400e'
                : '#7c5b18';
        const badgeTextDark = suggestion.badge === 'Progressing'
            ? '#86efac'
            : suggestion.badge === 'Due again'
                ? '#fbbf24'
                : '#f5d98a';

        return `
            <button type="button" onclick="selectExerciseToAdd('${escapedName}')" style="width:100%; border:1px solid #e2e8f0; background:white; border-radius:12px; padding:14px; margin-bottom:10px; cursor:pointer; display:flex; align-items:center; gap:12px; text-align:left; font-family:inherit; box-shadow:0 6px 16px rgba(15,23,42,0.04);">
                <div style="width:42px; height:42px; background:${badgeColor}; border-radius:10px; color:#120c18; display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                    ${getAddExerciseSuggestionIconHtml(suggestion)}
                </div>
                <div style="flex:1; min-width:0;">
                    <div style="display:flex; align-items:center; gap:8px; min-width:0; flex-wrap:wrap;">
                        <div style="font-weight:800; color:var(--text-main); font-size:0.95rem; line-height:1.2; min-width:0; overflow:hidden; text-overflow:ellipsis;">${safeName}</div>
                        <span data-add-exercise-suggestion-badge style="--add-exercise-badge-light:${badgeTextLight}; --add-exercise-badge-dark:${badgeTextDark};">${safeBadge}</span>
                    </div>
                    <div style="font-size:0.8rem; color:#64748b; font-weight:600; margin-top:4px; line-height:1.35;">${safeDetail}</div>
                    ${metaHtml}
                </div>
                <svg viewBox="0 0 24 24" style="width:22px; height:22px; fill:var(--primary); flex-shrink:0;">
                    <path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/>
                </svg>
            </button>
        `;
    }).join('');

    resultsContainer.innerHTML = `
        <div style="padding:0 2px 12px 2px;">
            <div style="font-size:0.75rem; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin:2px 0 10px 2px;">Suggested Exercises</div>
            ${suggestionHtml}
            <div style="text-align:center; color:#94a3b8; font-size:0.8rem; padding:8px 8px 0 8px;">Type to search the full library</div>
        </div>
    `;
}

// Keep natural exercise searches working when the library label omits an
// anatomical qualifier, such as "Machine Seated Abduction" for a user who
// searches "seated hip abduction".
function addExerciseSearchTermMatches(nameLower, term, terms) {
    if (nameLower.includes(term)) return true;

    if (term === 'hip' && terms.some(searchTerm => searchTerm.includes('abduct') || searchTerm.includes('adduct'))) {
        return nameLower.includes('abduct') || nameLower.includes('adduct');
    }

    return false;
}

// Search exercises for add modal
function searchExercisesForAdd(query) {
    const resultsContainer = document.getElementById('add-exercise-results');

    if (!query || query.length < 2) {
        renderAddExerciseSuggestions();
        return;
    }

    // Search in EXERCISE_VIDEOS library
    if (typeof EXERCISE_VIDEOS === 'undefined') {
        resultsContainer.innerHTML = `
            <div style="text-align: center; padding: 40px; color: #ef4444;">
                Exercise library not loaded
            </div>
        `;
        return;
    }

    const allExercises = Object.keys(EXERCISE_VIDEOS);
    const terms = query.toLowerCase().split(' ').filter(t => t);
    const filteredExercises = allExercises.filter(name => {
        const nameLower = name.toLowerCase();
        return terms.every(term => addExerciseSearchTermMatches(nameLower, term, terms));
    });

    // Also search user's custom exercises
    const customMatches = (window._customExercisesCache || []).filter(ex => {
        const nameLower = ex.exercise_name.toLowerCase();
        return terms.every(term => nameLower.includes(term));
    });

    // Build custom exercises HTML (shown first)
    let customHtml = '';
    if (customMatches.length > 0) {
        customHtml = `<div style="padding: 10px 15px 5px 15px; font-size: 0.75rem; font-weight: 700; color: var(--primary); text-transform: uppercase; letter-spacing: 0.5px;">Your Custom Exercises</div>`;
        customHtml += customMatches.map(ex => {
            const escapedName = ex.exercise_name.replace(/'/g, "\\'");
            const hasVideo = ex.video_url ? true : false;
            return `
                <div onclick="selectExerciseToAdd('${escapedName}')" style="padding: 15px; border-bottom: 1px solid #f1f5f9; cursor: pointer; display: flex; align-items: center; gap: 12px; transition: background 0.2s; background: #f0fdf4;" onmouseover="this.style.background='#dcfce7'" onmouseout="this.style.background='#f0fdf4'">
                    <div style="width: 40px; height: 40px; background: linear-gradient(135deg, var(--primary), #4ade80); border-radius: 8px; color:#120c18; display: flex; align-items: center; justify-content: center;">
                        ${hasVideo
                            ? '<svg viewBox="0 0 24 24" style="width: 20px; height: 20px; fill: currentColor;"><path d="M8 5v14l11-7z"/></svg>'
                            : '<svg viewBox="0 0 24 24" style="width: 20px; height: 20px; fill: currentColor;"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>'
                        }
                    </div>
                    <div style="flex: 1;">
                        <div style="font-weight: 600; color: var(--text-main); display: flex; align-items: center; gap: 6px;">
                            ${ex.exercise_name}
                            <span data-add-exercise-solid-badge>YOURS</span>
                        </div>
                        <div style="font-size: 0.8rem; color: var(--text-muted);">${ex.muscle_group ? ex.muscle_group.replace('_', ' ') : ''} ${hasVideo ? '· Has video' : ''}</div>
                    </div>
                    <svg viewBox="0 0 24 24" style="width: 24px; height: 24px; fill: var(--primary);">
                        <path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/>
                    </svg>
                </div>
            `;
        }).join('');
    }

    if (filteredExercises.length === 0 && customMatches.length === 0) {
        resultsContainer.innerHTML = `
            <div style="text-align: center; padding: 30px; color: #94a3b8;">
                No exercises found matching "${query}"
            </div>
            <div onclick="closeAddExerciseModal(); openCreateCustomExerciseModal('workout');" style="margin: 0 15px; padding: 16px; background: linear-gradient(135deg, #f0fdf4, #dcfce7); border: 2px dashed var(--primary); border-radius: 12px; cursor: pointer; text-align: center;">
                <div style="font-weight: 700; color: var(--primary); font-size: 0.95rem; margin-bottom: 4px;">Create "${query}" as custom exercise</div>
                <div style="font-size: 0.8rem; color: var(--text-muted);">Record a video and save it to your library</div>
            </div>
        `;
        return;
    }

    // Sort library exercises by relevance score (highest first)
    filteredExercises.sort((a, b) => {
        const scoreA = scoreExerciseMatch(a, terms, query);
        const scoreB = scoreExerciseMatch(b, terms, query);
        return scoreB - scoreA;
    });

    // Limit to first 50 results
    const displayExercises = filteredExercises.slice(0, 50);

    // Build library results header (only if we also have custom matches)
    let libraryHeader = '';
    if (customMatches.length > 0 && displayExercises.length > 0) {
        libraryHeader = `<div style="padding: 10px 15px 5px 15px; font-size: 0.75rem; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px; border-top: 2px solid #e2e8f0; margin-top: 5px;">Exercise Library</div>`;
    }

    const libraryHtml = displayExercises.map(name => {
        const escapedName = name.replace(/'/g, "\\'");
        return `
            <div onclick="selectExerciseToAdd('${escapedName}')" style="padding: 15px; border-bottom: 1px solid #f1f5f9; cursor: pointer; display: flex; align-items: center; gap: 12px; transition: background 0.2s;" onmouseover="this.style.background='#f8fafc'" onmouseout="this.style.background='white'">
                <div style="width: 40px; height: 40px; background: #f1f5f9; border-radius: 8px; display: flex; align-items: center; justify-content: center;">
                    <svg viewBox="0 0 24 24" style="width: 20px; height: 20px; fill: #94a3b8;">
                        <path d="M20.57 14.86L22 13.43 20.57 12 17 15.57 8.43 7 12 3.43 10.57 2 9.14 3.43 7.71 2 5.57 4.14 4.14 2.71 2.71 4.14l1.43 1.43L2 7.71l1.43 1.43L2 10.57 3.43 12 7 8.43 15.57 17 12 20.57 13.43 22l1.43-1.43L16.29 22l2.14-2.14 1.43 1.43 1.43-1.43-1.43-1.43L22 16.29z"/>
                    </svg>
                </div>
                <div style="flex: 1;">
                    <div style="font-weight: 600; color: var(--text-main);">${name}</div>
                    <div style="font-size: 0.8rem; color: var(--text-muted);">Tap to add to workout</div>
                </div>
                <svg viewBox="0 0 24 24" style="width: 24px; height: 24px; fill: var(--primary);">
                    <path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/>
                </svg>
            </div>
        `;
    }).join('');

    resultsContainer.innerHTML = customHtml + libraryHeader + libraryHtml;

    if (displayExercises.length < filteredExercises.length) {
        resultsContainer.innerHTML += `
            <div style="text-align: center; padding: 15px; color: #94a3b8; font-size: 0.85rem;">
                Showing ${displayExercises.length} of ${filteredExercises.length} results. Refine your search for more specific results.
            </div>
        `;
    }
}

// Select exercise to add
async function selectExerciseToAdd(exerciseName) {
    const user = window.currentUser;
    const workoutKey = window.currentWorkoutKey;

    // Create exercise object
    const newExercise = {
        name: exerciseName,
        sets: 3,
        reps: '8-12',
        desc: 'Custom exercise added by you',
        isUserAdded: true
    };

    // Ask user if they want to save permanently
    const saveChoice = confirm(`Add "${exerciseName}" to this workout?\n\nClick OK to save it permanently (it will appear every time you do this workout).\nClick Cancel to just add it for today.`);

    // Add to UI immediately
    addExerciseToUI(newExercise);
    closeAddExerciseModal();

    // Save to database if user confirmed and is logged in
    if (saveChoice && user && workoutKey) {
        try {
            await dbHelpers.workoutCustomizations.addExercise(user.id, workoutKey, {
                name: exerciseName,
                sets: 3,
                reps: '8-12',
                desc: 'Custom exercise added by you'
            });
            console.log(`Exercise "${exerciseName}" saved to workout permanently`);
        } catch (e) {
            console.error('Failed to save exercise to database:', e);
            // Exercise is already added to UI, just log the error
        }
    }
}

// Add exercise to UI
function addExerciseToUI(exercise) {
    const container = document.getElementById('workout-exercises-list');
    const videoUploading = !!exercise.videoUploading || isCustomExerciseVideoUploading(exercise.name, exercise.customExerciseId);
    const videoUrl = videoUploading ? '' : findVideoMatch(exercise.name);
    const videoBlockHtml = videoUrl
        ? createExerciseVideoBlockHtml(videoUrl, exercise.name)
        : (videoUploading ? createExerciseVideoUploadPlaceholderHtml() : '');
    const previousSummaryHtml = formatPreviousWorkoutSummary(exercise.name);
    const previousSummary = getPreviousWorkoutSummary(exercise.name);
    const escapedName = exercise.name.replace(/'/g, "\\'");

    const exerciseHtml = `
        <div class="exercise-logger-card" data-exercise-name="${exercise.name}" data-is-user-added="true" style="animation: slideInUp 0.3s ease;">
            <div style="padding: 15px; background: #f8fafc; border-bottom: 1px solid #e2e8f0;">
                <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                    <div style="flex: 1;">
                        <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 5px; min-width: 0; flex-wrap: wrap;">
                            <span style="font-weight: 700; font-size: 1.05rem; flex: 1; min-width: 0;">${exercise.name}</span>
                            <span data-add-exercise-solid-badge>ADDED</span>
                            ${previousSummaryHtml}
                        </div>
                        <div class="workout-exercise-tip" style="color: var(--text-muted); font-size: 0.85rem;">${exercise.desc || ''}</div>
                    </div>
                    <button onclick="deleteExerciseFromWorkout('${escapedName}', true)" style="background: none; border: none; color: #ef4444; cursor: pointer; padding: 5px; font-size: 0.8rem; font-weight: 600;">
                        <svg viewBox="0 0 24 24" style="width: 18px; height: 18px; fill: currentColor;">
                            <path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/>
                        </svg>
                    </button>
                </div>
            </div>

            ${getExerciseNotesHtml(exercise.name)}

            ${videoBlockHtml}

            <!-- Volume Tracker -->
            <div class="volume-display" style="display: flex; justify-content: space-between; align-items: center; padding: 10px 15px; background: linear-gradient(135deg, #fefce8 0%, #fef9c3 100%); border-bottom: 1px solid #fef08a;">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <svg viewBox="0 0 24 24" style="width: 18px; height: 18px; fill: #ca8a04;"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z"/></svg>
                    <span style="font-size: 0.75rem; font-weight: 700; color: #a16207; text-transform: uppercase;">Volume</span>
                </div>
                <div style="text-align: right;">
                    <div class="volume-value" style="font-size: 1rem; font-weight: 800; color: #854d0e;">0 kg</div>
                    <div class="volume-comparison" style="font-size: 0.7rem; font-weight: 600;">${previousSummary && previousSummary.totalVolume > 0 ? `<span style="color: #94a3b8;">Last: ${previousSummary.totalVolume.toLocaleString()} kg — beat it!</span>` : '<span style="color: #94a3b8;">Enter weight & reps</span>'}</div>
                </div>
                <div class="volume-progress-container" style="display: ${previousSummary && previousSummary.totalVolume > 0 ? 'block' : 'none'}; margin-top: 8px;">
                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                        <span class="volume-target-label" style="font-size: 0.65rem; font-weight: 600; color: #a16207;">Target: ${previousSummary && previousSummary.totalVolume > 0 ? previousSummary.totalVolume.toLocaleString() + ' kg' : '—'}</span>
                        <span class="volume-percentage" style="font-size: 0.65rem; font-weight: 700; color: #a16207;">0%</span>
                    </div>
                    <div style="height: 6px; background: #fef08a; border-radius: 3px; overflow: hidden;">
                        <div class="volume-progress-bar" style="height: 100%; width: 0%; background: #ca8a04; border-radius: 3px; transition: width 0.3s ease, background 0.3s ease;"></div>
                    </div>
                </div>
            </div>

            <div style="display:grid; grid-template-columns:40px 1fr 1fr 1fr 32px 32px; gap:8px; padding:10px 15px 0 15px; font-size:0.7rem; color:#94a3b8; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; text-align:center;">
                <div>Set</div><div>Time</div><div>Reps</div><div>Kg</div><div></div><div></div>
            </div>

            <div class="sets-list-container">
                ${(() => {
                    const numSets = previousSummary && previousSummary.setCount > 0 ? previousSummary.setCount : (exercise.sets || 3);
                    return Array.from({length: numSets}, (_, setIdx) => {
                        const prevSet = previousSummary && previousSummary.sets[setIdx] ? previousSummary.sets[setIdx] : null;
                        const prefillKg = prevSet && prevSet.kg && prevSet.kg !== '0' && prevSet.kg !== '' ? prevSet.kg : '';
                        const prefillReps = prevSet && prevSet.reps ? prevSet.reps : '';
                        const hasPrefill2 = prefillKg || prefillReps;
                        return `
                        <div class="set-wrapper"${hasPrefill2 ? ' data-prefilled="true"' : ''}>
                            <div class="workout-set-row" style="display: grid; grid-template-columns: 40px 1fr 1fr 1fr 32px 32px; gap: 8px; align-items: center; padding: 10px 15px; border-top: 1px solid #f8fafc;">
                                <div class="set-number" style="font-weight: 800; color: #94a3b8; font-size: 0.85rem; text-align: center;">${setIdx + 1}</div>
                                <input type="text" class="input-time" placeholder="-" data-exercise="${exercise.name}" data-set="${setIdx + 1}" data-field="time" style="width:100%; border: none; background: #f8fafc; border-radius: 8px; padding: 10px 5px; text-align: center; font-weight: 700; color: var(--text-main); font-size: 0.9rem;">
                                <input type="text" class="input-reps" placeholder="Reps" value="${prefillReps}" data-exercise="${exercise.name}" data-set="${setIdx + 1}" data-field="reps" style="width:100%; border: none; background: #f8fafc; border-radius: 8px; padding: 10px 5px; text-align: center; font-weight: 700; color: var(--text-main); font-size: 0.9rem;">
                                <input type="text" class="input-kg" placeholder="Kg" value="${prefillKg}" data-exercise="${exercise.name}" data-set="${setIdx + 1}" data-field="weight" style="width:100%; border: none; background: #f8fafc; border-radius: 8px; padding: 10px 5px; text-align: center; font-weight: 700; color: var(--text-main); font-size: 0.9rem;">
                                <button class="drop-set-toggle" onclick="toggleDropSet(this)" title="Toggle Drop Set">DS</button>
                                <button class="delete-set-btn" onclick="deleteSetRow(this)" title="Delete Set" style="width:32px; height:32px; border:none; background:transparent; color:#ef4444; cursor:pointer; border-radius:8px; display:flex; align-items:center; justify-content:center; transition:background 0.2s;"><svg viewBox="0 0 24 24" style="width:16px; height:16px; fill:currentColor;"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z"/></svg></button>
                            </div>
                            <div class="drop-set-container">
                                <div class="drop-set-inputs">
                                    <div class="drop-set-row">
                                        <div class="drop-indicator">↓1</div>
                                        <input type="text" class="drop-reps" placeholder="Reps">
                                        <input type="text" class="drop-kg" placeholder="Kg">
                                        <button class="drop-add-btn" onclick="addDropRow(this)">+</button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    `}).join('');
                })()}
            </div>

            <div style="padding:15px; border-top:1px solid #f8fafc;">
                <button onclick="addWorkoutSet(this, '${escapedName}', false)" style="width:100%; background:transparent; border:2px dashed #e2e8f0; color:#94a3b8; font-weight:700; font-size:0.8rem; padding:12px; border-radius:12px; cursor:pointer;">+ ADD SET</button>
            </div>
        </div>
    `;

    container.insertAdjacentHTML('beforeend', exerciseHtml);

    // Update exercise count in header
    const exerciseCount = document.querySelectorAll('.exercise-logger-card').length;
    const goalEl = document.getElementById('workout-player-goal');
    if (goalEl) {
        const currentText = goalEl.textContent;
        goalEl.textContent = currentText.replace(/\d+ Exercise[s]?/, `${exerciseCount} Exercise${exerciseCount !== 1 ? 's' : ''}`);
    }

    // Scroll to the new exercise and setup volume tracking
    const newCard = container.lastElementChild;
    if (newCard) {
        newCard.dataset.prescribedSets = String(exercise.sets || newCard.querySelectorAll('.set-wrapper').length || 1);
        newCard.dataset.prescribedReps = String(exercise.reps || 'Log each set');
        const playerMode = window.PBBWorkoutSwipePlayer?.sync({ focusName: exercise.name, scroll: true });
        if (playerMode !== 'swipe') newCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setupVolumeTracking(newCard);
    }
}

// Update hideAllAppViews to include new views
const originalHideAllAppViews = hideAllAppViews;
hideAllAppViews = function() {
    originalHideAllAppViews();
    const libraryViews = ['view-workout-library', 'view-workout-subcategories', 'view-workout-list', 'view-prebuilt-programs'];
    libraryViews.forEach(v => {
        const el = document.getElementById(v);
        if(el) {
            el.style.display = 'none';
        }
    });
    // Hide the learning mascot (Shanbot) so it doesn't persist across tab switches
    if (window.LearningMascot) window.LearningMascot.hide();
};

